window.HT = window.HT || {}; HT.CDF = HT.CDF || {};
HT.CDF["G17"] = {"bang":[{"i":0,"tieu_de_bang":"Di sản – Học và làm theo Bác","tieu_de":"Sau mùa thu năm 1969: di sản Hồ Chí Minh trong lòng dân tộc và thế giới","sapo":"Mùa thu năm 1969, cả nước để tang một người vừa đi xa. Hơn nửa thế kỷ sau, người ấy vẫn có mặt: trong dòng người xếp hàng trước một công trình đá hoa cương ở Ba Đình, trong hơn 170.000 trang tài liệu của một bảo tàng mang tên Người, trong chính tên gọi của thành phố lớn nhất phương Nam. Điều gì đã biến một con người thành một di sản sống, được cả dân tộc và thế giới cùng gìn giữ? Câu chuyện bắt đầu từ chính buổi sáng mùa thu năm ấy.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_ba_dinh_square_and_ho_chi_minh_mau.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Buổi sáng không có nắng","text":"Chủ tịch Hồ Chí Minh từ trần lúc 9 giờ 47 phút ngày 2 tháng 9 năm 1969 tại Nhà 67 trong khu Phủ Chủ tịch, Hà Nội, hưởng thọ 79 tuổi. Để ngày mất của Người không trùng với ngày Quốc khánh, tin buồn khi ấy được công bố là ngày 3 tháng 9; phải hai mươi năm sau, tháng 8 năm 1989, Bộ Chính trị mới ra thông báo đính chính. Từ ngày 6 đến hết ngày 8 tháng 9, đồng bào, chiến sĩ và bạn bè quốc tế nối nhau vào viếng Người tại Hội trường Ba Đình. Ngày 9 tháng 9 năm 1969, lễ truy điệu trọng thể được tổ chức tại Quảng trường Ba Đình — nơi 24 năm trước Người đọc Tuyên ngôn Độc lập — và bản Di chúc của Người được công bố trước quốc dân, đồng bào. Những ngày Người lặng lẽ viết bản Di chúc ấy trên nhà sàn đã được kể ở gian Phủ Chủ tịch của bảo tàng số này; còn hành trình bản Di chúc đến với nhân dân qua hai lần công bố, cách nhau đúng hai mươi năm, được kể riêng ở chuyên đề “Di chúc: hai lần công bố, một nguyện vọng” ngay trong gian này.","doc":1},{"loai":"doan","tieu_de":"Một nhiệm vụ giữ trong bí mật","text":"Ngay trong những ngày tang lễ, xuất phát từ tình cảm và nguyện vọng của nhân dân — nhất là đồng bào miền Nam chưa từng có dịp gặp Người — Bộ Chính trị quyết định giữ gìn lâu dài thi hài Chủ tịch Hồ Chí Minh. Đây là một quyết định không dễ dàng: đất nước khi ấy còn chia cắt, cuộc kháng chiến chống Mỹ, cứu nước còn đang ở giai đoạn quyết liệt, và Hà Nội thường xuyên nằm trong tầm không kích. Suốt sáu năm sau đó, một nhiệm vụ được giữ trong vòng bí mật tuyệt đối đã diễn ra: cán bộ, chiến sĩ Đoàn 69 cùng chuyên gia Liên Xô ngày đêm túc trực bảo quản thi hài Người, phần lớn thời gian tại một căn cứ giữa rừng Ba Vì mang mật danh K9. Hành trình sáu năm ấy — với những chuyến di chuyển bí mật, những đêm không ngủ và cả sự tận tụy thầm lặng của người lính canh — được kể chi tiết ở chuyên đề “Sáu năm gìn giữ thi hài Bác giữa chiến tranh” ngay bên cạnh.","doc":2},{"loai":"doan","tieu_de":"Công trình của lòng biết ơn","text":"Ngày 2 tháng 9 năm 1973 — tròn bốn năm sau ngày Người đi xa — công trình Lăng Chủ tịch Hồ Chí Minh được khởi công ngay tại Quảng trường Ba Đình, trên nền lễ đài nơi Người từng đọc Tuyên ngôn Độc lập. Đá, gỗ quý và cây xanh được đưa về từ khắp các miền đất nước; các kiến trúc sư Việt Nam và Liên Xô cùng hàng nghìn người thợ làm việc suốt gần hai năm, ngay trong giai đoạn cuối của cuộc kháng chiến. Ngày 18 tháng 7 năm 1975, thi hài Người được đưa từ K9 về đặt tại Lăng; và chưa đầy bốn tháng sau ngày miền Nam hoàn toàn giải phóng, ngày 29 tháng 8 năm 1975, Lăng được khánh thành, kịp dịp kỷ niệm 30 năm Quốc khánh. Từ đó, hàng triệu người Việt Nam và bạn bè quốc tế mỗi năm tìm về đây, xếp hàng lặng lẽ để được vào viếng Người. Ba lớp kiến trúc, dòng chữ ghép bằng đá ngọc đỏ Cao Bằng và câu chuyện về những hàng tre, hàng vạn tuế quanh Lăng được kể riêng ở chuyên đề về Lăng Chủ tịch Hồ Chí Minh, cũng trong gian này.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_hanoi_vietnam_ho_chi_minh_museum_the_pyramid.jpg","chu_thich":"Bảo tàng Hồ Chí Minh, Hà Nội, khánh thành ngày 19/5/1990, nằm liền kề Lăng và Quảng trường Ba Đình.","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một ngôi nhà cho một cuộc đời, một dân tộc","text":"Ngày 31 tháng 8 năm 1985, công trình Bảo tàng Hồ Chí Minh được khởi công ngay cạnh khu vực Lăng; và đúng ngày 19 tháng 5 năm 1990 — kỷ niệm tròn 100 năm ngày sinh Chủ tịch Hồ Chí Minh — bảo tàng chính thức mở cửa đón khách. Phần trưng bày chính được sắp xếp theo dòng thời gian, tái hiện cuộc đời Người từ thời niên thiếu ở làng Sen, Nghệ An, những năm bôn ba tìm đường cứu nước, đến khi trở thành lãnh tụ của dân tộc; kho lưu trữ của bảo tàng hiện có hơn 170.000 tài liệu, hiện vật và phim ảnh. Liền kề bảo tàng là Khu Di tích Phủ Chủ tịch, nơi có ngôi nhà sàn Người ở và làm việc từ tháng 5 năm 1958 cho đến những ngày cuối đời. Ba công trình — Lăng, Bảo tàng, Khu Di tích Phủ Chủ tịch — cùng nằm trong một quần thể mà mỗi ngày đón hàng nghìn lượt khách, trở thành điểm đến gần như bắt buộc của bất cứ ai muốn tìm hiểu về cuộc đời Chủ tịch Hồ Chí Minh.","doc":4},{"loai":"doan","tieu_de":"Từ Ba Đình ra khắp đất nước","text":"Không chỉ ở Ba Đình, di sản của Chủ tịch Hồ Chí Minh còn trải khắp đất nước, gắn với những chặng đường Người đã đi qua. Đó là Khu di tích Kim Liên ở Nam Đàn, Nghệ An — quê hương của Người; Khu di tích Pác Bó ở Cao Bằng, nơi Người trở về nước ngày 28 tháng 1 năm 1941 sau ba mươi năm bôn ba; Khu di tích Tân Trào ở Tuyên Quang và An toàn khu Định Hóa ở Thái Nguyên, những “thủ đô kháng chiến” thời chống Pháp; và Bến Nhà Rồng ở Thành phố Hồ Chí Minh, nơi năm 1911 chàng thanh niên Nguyễn Tất Thành xuống tàu ra đi tìm đường cứu nước. Ngày 12 tháng 8 năm 2009, Khu lưu niệm Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch được xếp hạng Di tích quốc gia đặc biệt trong đợt đầu tiên của cả nước; ba năm sau, năm 2012, đến lượt Khu lưu niệm tại Kim Liên. Các khu di tích Pác Bó, Tân Trào, An toàn khu Định Hóa cũng lần lượt được ghi danh trong những năm sau đó, cùng nhau tạo thành một “bản đồ di sản” mà người Việt Nam có thể theo chân Người đi suốt một cuộc đời.","doc":5},{"loai":"anh","src":"textures/bang_w/G17_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di sản – Học và làm theo Bác”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một nhân cách được thế giới tôn vinh","text":"Năm 1987, tại khóa họp lần thứ 24, Đại hội đồng Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO) thông qua nghị quyết khuyến nghị các nước thành viên cùng tham gia kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh vào năm 1990, tôn vinh Người là “Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất của Việt Nam”. Đây là một trong số ít trường hợp một tổ chức quốc tế chính thức ghi nhận tầm vóc của một lãnh tụ cách mạng ở cả hai phương diện: đấu tranh giải phóng dân tộc và đóng góp cho văn hóa nhân loại. Năm 1990, lễ kỷ niệm được tổ chức trọng thể không chỉ ở Việt Nam mà tại nhiều quốc gia trên thế giới, với hàng loạt hội thảo khoa học, triển lãm và ấn phẩm giới thiệu về cuộc đời, sự nghiệp và tư tưởng của Người. Từ dấu mốc ấy, hình ảnh và tư tưởng Hồ Chí Minh dần trở thành một phần trong dòng chảy văn hóa, đối ngoại của Việt Nam, hiện diện trong nhiều hoạt động giao lưu, nghiên cứu quốc tế về Người suốt hơn ba mươi năm qua.","doc":6},{"loai":"ban_co_biet","text":"Nghị quyết tôn vinh Chủ tịch Hồ Chí Minh của UNESCO mang số hiệu 24C/18.65, được thông qua tại khóa họp lần thứ 24 Đại hội đồng UNESCO năm 1987, nhân dịp kỷ niệm 100 năm ngày sinh của Người vào năm 1990.","nguon_ten":"Nghị quyết 24C/18.65, khóa họp lần thứ 24 Đại hội đồng UNESCO","doc":7},{"loai":"doan","tieu_de":"Tên Người cho một dòng sông, một thành phố","text":"Ngày 2 tháng 7 năm 1976, tại kỳ họp thứ nhất, Quốc hội khóa VI — Quốc hội đầu tiên của nước Việt Nam thống nhất — đã quyết định đổi tên Thành phố Sài Gòn – Gia Định thành Thành phố Hồ Chí Minh. Đây là thành phố lớn nhất phương Nam, nơi năm 1911 người thanh niên Nguyễn Tất Thành từng làm phụ bếp trên con tàu Đô đốc Latouche-Tréville trước khi rời Bến Nhà Rồng ra đi tìm đường cứu nước. Gần bảy mươi năm sau ngày rời bến ấy, tên của Người trở thành tên gọi chính thức của chính thành phố mà Người đã ra đi từ đó — một vòng khép lại đầy ý nghĩa trong hành trình một dân tộc gọi tên người đã dẫn đường cho mình. Bến Nhà Rồng năm xưa, nơi lưu giữ câu chuyện buổi đầu ấy, nay là một phần của Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh.","doc":8},{"loai":"anh","src":"textures/bang_w/G17_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di sản – Học và làm theo Bác”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Nền tảng tư tưởng của một Đảng cầm quyền","text":"Tháng 6 năm 1991, Đại hội đại biểu toàn quốc lần thứ VII của Đảng Cộng sản Việt Nam chính thức xác định: cùng với chủ nghĩa Mác – Lênin, tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng. Đó là một quá trình nhận thức kéo dài suốt hơn hai mươi năm kể từ ngày Người qua đời. Hơn một thập niên sau, ngày 27 tháng 3 năm 2003, Ban Bí thư ban hành Chỉ thị 23-CT/TW về đẩy mạnh nghiên cứu, tuyên truyền, giáo dục tư tưởng Hồ Chí Minh trong giai đoạn mới, đặt nền cho một loạt cuộc vận động học tập và làm theo Người được phát động liên tục trong hai thập niên tiếp theo. Từ đó, việc học tập tư tưởng Hồ Chí Minh dần được đưa vào chương trình đào tạo lý luận chính trị, giảng dạy trong hệ thống giáo dục quốc dân, trở thành một trong những nội dung quen thuộc với nhiều thế hệ học sinh, sinh viên Việt Nam.","doc":9},{"loai":"doan","tieu_de":"Học và làm theo Bác, qua mỗi nhiệm kỳ","text":"Năm 2006, Bộ Chính trị ban hành Chỉ thị 06-CT/TW, phát động Cuộc vận động “Học tập và làm theo tấm gương đạo đức Hồ Chí Minh” trong toàn Đảng, toàn dân. Năm 2011, Chỉ thị 03-CT/TW tiếp tục đẩy mạnh cuộc vận động này; và từ ngày 15 tháng 5 năm 2016, theo Chỉ thị 05-CT/TW, nội dung học tập được mở rộng thành “Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh” — tên gọi được giữ đến hôm nay qua Kết luận 01-KL/TW năm 2021. Với thế hệ thiếu niên, nhi đồng, việc học Bác đã bắt đầu từ rất sớm: ngày 15 tháng 5 năm 1961, nhân kỷ niệm 20 năm thành lập Đội Thiếu niên Tiền phong Việt Nam, Chủ tịch Hồ Chí Minh gửi thư nêu ra Năm điều Bác Hồ dạy — trở thành lời dặn quen thuộc được đọc lại trong mỗi buổi chào cờ ở trường học Việt Nam suốt hơn sáu mươi năm qua.","doc":10},{"loai":"trich","text":"Yêu Tổ quốc, yêu đồng bào.\nHọc tập tốt, lao động tốt.\nĐoàn kết tốt, kỷ luật tốt.\nGiữ gìn vệ sinh thật tốt.\nKhiêm tốn, thật thà, dũng cảm.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Thư gửi thiếu niên, nhi đồng nhân dịp kỷ niệm 20 năm Ngày thành lập Đội Thiếu niên Tiền phong Việt Nam, 15/5/1961","doc":11},{"loai":"ban_co_biet","text":"Chỉ thị 05-CT/TW về đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh được Bộ Chính trị ký ban hành đúng ngày 15 tháng 5 — cùng ngày mà 55 năm trước, năm 1961, Người gửi thư nêu ra Năm điều Bác Hồ dạy thiếu niên, nhi đồng.","nguon_ten":"Chỉ thị 05-CT/TW (2016); Thư Bác Hồ gửi thiếu niên, nhi đồng (1961)","doc":12},{"loai":"anh","src":"textures/bang_w/G17_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di sản – Học và làm theo Bác”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay: nối sang gian tranh Bác Hồ","text":"Rời gian trưng bày cuối cùng này của bảo tàng số, du khách bước sang một không gian khác: gian tranh Bác Hồ, nơi những tác phẩm hội họa đương đại khắc họa chân dung và cuộc đời Người được giới thiệu bên cạnh Năm điều Bác Hồ dạy. Ở đó cũng là nơi câu chuyện học và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh được kể tiếp bằng những việc làm cụ thể của con người Ninh Bình hôm nay — những phong trào thi đua nhỏ ở cơ sở, những tấm gương cán bộ, đảng viên nêu gương, tiếp nối tinh thần cần, kiệm, liêm, chính mà Người từng căn dặn trong Di chúc. Đi qua Lăng, Bảo tàng, những khu di tích trên khắp đất nước và cả những nghị quyết, chỉ thị suốt hơn nửa thế kỷ, hành trình học Bác cuối cùng vẫn quay về một điểm giản dị nhất: mỗi việc làm tử tế mỗi ngày.","doc":13}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 10, NXB Chính trị quốc gia","Di chúc của Chủ tịch Hồ Chí Minh","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Bảo tàng Hồ Chí Minh","Nghị quyết 24C/18.65, khóa họp lần thứ 24 Đại hội đồng UNESCO, 1987","Chỉ thị 05-CT/TW ngày 15/5/2016 của Bộ Chính trị"],"doc":[{"t":"Sau mùa thu năm 1969: di sản Hồ Chí Minh trong lòng dân tộc và thế giới. Mùa thu năm 1969, cả nước để tang một người vừa đi xa. Hơn nửa thế kỷ sau, người ấy vẫn có mặt: trong dòng người xếp hàng trước một công trình đá hoa cương ở Ba Đình, trong hơn 170.000 trang tài liệu của một bảo tàng mang tên Người, trong chính tên gọi của thành phố lớn nhất phương Nam. Điều gì đã biến một con người thành một di sản sống, được cả dân tộc và thế giới cùng gìn giữ? Câu chuyện bắt đầu từ chính buổi sáng mùa thu năm ấy."},{"t":"Buổi sáng không có nắng. Chủ tịch Hồ Chí Minh từ trần lúc 9 giờ 47 phút ngày 2 tháng 9 năm 1969 tại Nhà 67 trong khu Phủ Chủ tịch, Hà Nội, hưởng thọ 79 tuổi. Để ngày mất của Người không trùng với ngày Quốc khánh, tin buồn khi ấy được công bố là ngày 3 tháng 9; phải hai mươi năm sau, tháng 8 năm 1989, Bộ Chính trị mới ra thông báo đính chính. Từ ngày 6 đến hết ngày 8 tháng 9, đồng bào, chiến sĩ và bạn bè quốc tế nối nhau vào viếng Người tại Hội trường Ba Đình. Ngày 9 tháng 9 năm 1969, lễ truy điệu trọng thể được tổ chức tại Quảng trường Ba Đình — nơi 24 năm trước Người đọc Tuyên ngôn Độc lập — và bản Di chúc của Người được công bố trước quốc dân, đồng bào. Những ngày Người lặng lẽ viết bản Di chúc ấy trên nhà sàn đã được kể ở gian Phủ Chủ tịch của bảo tàng số này; còn hành trình bản Di chúc đến với nhân dân qua hai lần công bố, cách nhau đúng hai mươi năm, được kể riêng ở chuyên đề “Di chúc: hai lần công bố, một nguyện vọng” ngay trong gian này."},{"t":"Một nhiệm vụ giữ trong bí mật. Ngay trong những ngày tang lễ, xuất phát từ tình cảm và nguyện vọng của nhân dân — nhất là đồng bào miền Nam chưa từng có dịp gặp Người — Bộ Chính trị quyết định giữ gìn lâu dài thi hài Chủ tịch Hồ Chí Minh. Đây là một quyết định không dễ dàng: đất nước khi ấy còn chia cắt, cuộc kháng chiến chống Mỹ, cứu nước còn đang ở giai đoạn quyết liệt, và Hà Nội thường xuyên nằm trong tầm không kích. Suốt sáu năm sau đó, một nhiệm vụ được giữ trong vòng bí mật tuyệt đối đã diễn ra: cán bộ, chiến sĩ Đoàn 69 cùng chuyên gia Liên Xô ngày đêm túc trực bảo quản thi hài Người, phần lớn thời gian tại một căn cứ giữa rừng Ba Vì mang mật danh K9. Hành trình sáu năm ấy — với những chuyến di chuyển bí mật, những đêm không ngủ và cả sự tận tụy thầm lặng của người lính canh — được kể chi tiết ở chuyên đề “Sáu năm gìn giữ thi hài Bác giữa chiến tranh” ngay bên cạnh."},{"t":"Công trình của lòng biết ơn. Ngày 2 tháng 9 năm 1973 — tròn bốn năm sau ngày Người đi xa — công trình Lăng Chủ tịch Hồ Chí Minh được khởi công ngay tại Quảng trường Ba Đình, trên nền lễ đài nơi Người từng đọc Tuyên ngôn Độc lập. Đá, gỗ quý và cây xanh được đưa về từ khắp các miền đất nước; các kiến trúc sư Việt Nam và Liên Xô cùng hàng nghìn người thợ làm việc suốt gần hai năm, ngay trong giai đoạn cuối của cuộc kháng chiến. Ngày 18 tháng 7 năm 1975, thi hài Người được đưa từ K9 về đặt tại Lăng; và chưa đầy bốn tháng sau ngày miền Nam hoàn toàn giải phóng, ngày 29 tháng 8 năm 1975, Lăng được khánh thành, kịp dịp kỷ niệm 30 năm Quốc khánh. Từ đó, hàng triệu người Việt Nam và bạn bè quốc tế mỗi năm tìm về đây, xếp hàng lặng lẽ để được vào viếng Người. Ba lớp kiến trúc, dòng chữ ghép bằng đá ngọc đỏ Cao Bằng và câu chuyện về những hàng tre, hàng vạn tuế quanh Lăng được kể riêng ở chuyên đề về Lăng Chủ tịch Hồ Chí Minh, cũng trong gian này."},{"t":"Một ngôi nhà cho một cuộc đời, một dân tộc. Ngày 31 tháng 8 năm 1985, công trình Bảo tàng Hồ Chí Minh được khởi công ngay cạnh khu vực Lăng; và đúng ngày 19 tháng 5 năm 1990 — kỷ niệm tròn 100 năm ngày sinh Chủ tịch Hồ Chí Minh — bảo tàng chính thức mở cửa đón khách. Phần trưng bày chính được sắp xếp theo dòng thời gian, tái hiện cuộc đời Người từ thời niên thiếu ở làng Sen, Nghệ An, những năm bôn ba tìm đường cứu nước, đến khi trở thành lãnh tụ của dân tộc; kho lưu trữ của bảo tàng hiện có hơn 170.000 tài liệu, hiện vật và phim ảnh. Liền kề bảo tàng là Khu Di tích Phủ Chủ tịch, nơi có ngôi nhà sàn Người ở và làm việc từ tháng 5 năm 1958 cho đến những ngày cuối đời. Ba công trình — Lăng, Bảo tàng, Khu Di tích Phủ Chủ tịch — cùng nằm trong một quần thể mà mỗi ngày đón hàng nghìn lượt khách, trở thành điểm đến gần như bắt buộc của bất cứ ai muốn tìm hiểu về cuộc đời Chủ tịch Hồ Chí Minh."},{"t":"Từ Ba Đình ra khắp đất nước. Không chỉ ở Ba Đình, di sản của Chủ tịch Hồ Chí Minh còn trải khắp đất nước, gắn với những chặng đường Người đã đi qua. Đó là Khu di tích Kim Liên ở Nam Đàn, Nghệ An — quê hương của Người; Khu di tích Pác Bó ở Cao Bằng, nơi Người trở về nước ngày 28 tháng 1 năm 1941 sau ba mươi năm bôn ba; Khu di tích Tân Trào ở Tuyên Quang và An toàn khu Định Hóa ở Thái Nguyên, những “thủ đô kháng chiến” thời chống Pháp; và Bến Nhà Rồng ở Thành phố Hồ Chí Minh, nơi năm 1911 chàng thanh niên Nguyễn Tất Thành xuống tàu ra đi tìm đường cứu nước. Ngày 12 tháng 8 năm 2009, Khu lưu niệm Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch được xếp hạng Di tích quốc gia đặc biệt trong đợt đầu tiên của cả nước; ba năm sau, năm 2012, đến lượt Khu lưu niệm tại Kim Liên. Các khu di tích Pác Bó, Tân Trào, An toàn khu Định Hóa cũng lần lượt được ghi danh trong những năm sau đó, cùng nhau tạo thành một “bản đồ di sản” mà người Việt Nam có thể theo chân Người đi suốt một cuộc đời."},{"t":"Một nhân cách được thế giới tôn vinh. Năm 1987, tại khóa họp lần thứ 24, Đại hội đồng Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO) thông qua nghị quyết khuyến nghị các nước thành viên cùng tham gia kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh vào năm 1990, tôn vinh Người là “Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất của Việt Nam”. Đây là một trong số ít trường hợp một tổ chức quốc tế chính thức ghi nhận tầm vóc của một lãnh tụ cách mạng ở cả hai phương diện: đấu tranh giải phóng dân tộc và đóng góp cho văn hóa nhân loại. Năm 1990, lễ kỷ niệm được tổ chức trọng thể không chỉ ở Việt Nam mà tại nhiều quốc gia trên thế giới, với hàng loạt hội thảo khoa học, triển lãm và ấn phẩm giới thiệu về cuộc đời, sự nghiệp và tư tưởng của Người. Từ dấu mốc ấy, hình ảnh và tư tưởng Hồ Chí Minh dần trở thành một phần trong dòng chảy văn hóa, đối ngoại của Việt Nam, hiện diện trong nhiều hoạt động giao lưu, nghiên cứu quốc tế về Người suốt hơn ba mươi năm qua."},{"t":"Bạn có biết? Nghị quyết tôn vinh Chủ tịch Hồ Chí Minh của UNESCO mang số hiệu 24C/18.65, được thông qua tại khóa họp lần thứ 24 Đại hội đồng UNESCO năm 1987, nhân dịp kỷ niệm 100 năm ngày sinh của Người vào năm 1990."},{"t":"Tên Người cho một dòng sông, một thành phố. Ngày 2 tháng 7 năm 1976, tại kỳ họp thứ nhất, Quốc hội khóa VI — Quốc hội đầu tiên của nước Việt Nam thống nhất — đã quyết định đổi tên Thành phố Sài Gòn – Gia Định thành Thành phố Hồ Chí Minh. Đây là thành phố lớn nhất phương Nam, nơi năm 1911 người thanh niên Nguyễn Tất Thành từng làm phụ bếp trên con tàu Đô đốc Latouche-Tréville trước khi rời Bến Nhà Rồng ra đi tìm đường cứu nước. Gần bảy mươi năm sau ngày rời bến ấy, tên của Người trở thành tên gọi chính thức của chính thành phố mà Người đã ra đi từ đó — một vòng khép lại đầy ý nghĩa trong hành trình một dân tộc gọi tên người đã dẫn đường cho mình. Bến Nhà Rồng năm xưa, nơi lưu giữ câu chuyện buổi đầu ấy, nay là một phần của Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh."},{"t":"Nền tảng tư tưởng của một Đảng cầm quyền. Tháng 6 năm 1991, Đại hội đại biểu toàn quốc lần thứ VII của Đảng Cộng sản Việt Nam chính thức xác định: cùng với chủ nghĩa Mác – Lênin, tư tưởng Hồ Chí Minh là nền tảng tư tưởng, kim chỉ nam cho hành động của Đảng. Đó là một quá trình nhận thức kéo dài suốt hơn hai mươi năm kể từ ngày Người qua đời. Hơn một thập niên sau, ngày 27 tháng 3 năm 2003, Ban Bí thư ban hành Chỉ thị 23-CT/TW về đẩy mạnh nghiên cứu, tuyên truyền, giáo dục tư tưởng Hồ Chí Minh trong giai đoạn mới, đặt nền cho một loạt cuộc vận động học tập và làm theo Người được phát động liên tục trong hai thập niên tiếp theo. Từ đó, việc học tập tư tưởng Hồ Chí Minh dần được đưa vào chương trình đào tạo lý luận chính trị, giảng dạy trong hệ thống giáo dục quốc dân, trở thành một trong những nội dung quen thuộc với nhiều thế hệ học sinh, sinh viên Việt Nam."},{"t":"Học và làm theo Bác, qua mỗi nhiệm kỳ. Năm 2006, Bộ Chính trị ban hành Chỉ thị 06-CT/TW, phát động Cuộc vận động “Học tập và làm theo tấm gương đạo đức Hồ Chí Minh” trong toàn Đảng, toàn dân. Năm 2011, Chỉ thị 03-CT/TW tiếp tục đẩy mạnh cuộc vận động này; và từ ngày 15 tháng 5 năm 2016, theo Chỉ thị 05-CT/TW, nội dung học tập được mở rộng thành “Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh” — tên gọi được giữ đến hôm nay qua Kết luận 01-KL/TW năm 2021. Với thế hệ thiếu niên, nhi đồng, việc học Bác đã bắt đầu từ rất sớm: ngày 15 tháng 5 năm 1961, nhân kỷ niệm 20 năm thành lập Đội Thiếu niên Tiền phong Việt Nam, Chủ tịch Hồ Chí Minh gửi thư nêu ra Năm điều Bác Hồ dạy — trở thành lời dặn quen thuộc được đọc lại trong mỗi buổi chào cờ ở trường học Việt Nam suốt hơn sáu mươi năm qua."},{"t":"Yêu Tổ quốc, yêu đồng bào. Học tập tốt, lao động tốt. Đoàn kết tốt, kỷ luật tốt. Giữ gìn vệ sinh thật tốt. Khiêm tốn, thật thà, dũng cảm. — Chủ tịch Hồ Chí Minh"},{"t":"Bạn có biết? Chỉ thị 05-CT/TW về đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh được Bộ Chính trị ký ban hành đúng ngày 15 tháng 5 — cùng ngày mà 55 năm trước, năm 1961, Người gửi thư nêu ra Năm điều Bác Hồ dạy thiếu niên, nhi đồng."},{"t":"Dấu tích hôm nay: nối sang gian tranh Bác Hồ. Rời gian trưng bày cuối cùng này của bảo tàng số, du khách bước sang một không gian khác: gian tranh Bác Hồ, nơi những tác phẩm hội họa đương đại khắc họa chân dung và cuộc đời Người được giới thiệu bên cạnh Năm điều Bác Hồ dạy. Ở đó cũng là nơi câu chuyện học và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh được kể tiếp bằng những việc làm cụ thể của con người Ninh Bình hôm nay — những phong trào thi đua nhỏ ở cơ sở, những tấm gương cán bộ, đảng viên nêu gương, tiếp nối tinh thần cần, kiệm, liêm, chính mà Người từng căn dặn trong Di chúc. Đi qua Lăng, Bảo tàng, những khu di tích trên khắp đất nước và cả những nghị quyết, chỉ thị suốt hơn nửa thế kỷ, hành trình học Bác cuối cùng vẫn quay về một điểm giản dị nhất: mỗi việc làm tử tế mỗi ngày."}],"so_chu":2127},{"i":1,"tieu_de_bang":"Sáu năm gìn giữ thi hài Bác giữa chiến tranh","tieu_de":"1969–1975: hành trình thầm lặng gìn giữ thi hài Chủ tịch Hồ Chí Minh","sapo":"Tháng 9 năm 1969, khi bom Mỹ vẫn trút xuống miền Bắc và đất nước còn chia cắt đôi bờ, một đơn vị đặc biệt nhận nhiệm vụ chưa từng có tiền lệ: giữ gìn thi hài Chủ tịch Hồ Chí Minh cho muôn đời sau. Suốt sáu năm, giữa những đợt sơ tán, những đêm báo động và cả nỗi lo bom rơi ngay trên đầu, họ đã hoàn thành nhiệm vụ ấy trong im lặng tuyệt đối. Đây là câu chuyện về căn cứ mang mật danh K9, về những người lính mang tên Đoàn 69, và về ngày họ đưa Người trở về giữa lòng Hà Nội.","bia":{"src":"textures/bai/G17_v2.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một quyết định giữa lúc đất nước lâm nguy","text":"Chủ tịch Hồ Chí Minh qua đời ngày 2 tháng 9 năm 1969, khi cuộc kháng chiến chống Mỹ, cứu nước đang ở giai đoạn ác liệt và đất nước còn chia cắt làm hai miền. Xuất phát từ tình cảm, nguyện vọng thiết tha của nhân dân cả nước — nhất là đồng bào, chiến sĩ miền Nam chưa từng có dịp gặp Người — Bộ Chính trị quyết định giữ gìn lâu dài thi hài của Người, để một ngày đất nước thống nhất, đồng bào mọi miền đều có thể đến viếng. Đây là một quyết định chưa có tiền lệ ở Việt Nam, được thực hiện với sự giúp đỡ tận tình của các chuyên gia y tế Liên Xô — những người đã có kinh nghiệm gìn giữ thi hài lãnh tụ từ nhiều năm trước đó. Từ ngày 6 đến hết ngày 8 tháng 9 năm 1969, trong lúc công việc gìn giữ vừa mới bắt đầu trong bí mật, hàng chục vạn đồng bào, chiến sĩ và bạn bè quốc tế đã nối nhau vào viếng Người tại Hội trường Ba Đình, trước khi cả nước bước vào lễ truy điệu trọng thể ngày 9 tháng 9.","doc":1},{"loai":"doan","tieu_de":"Đoàn 69 và nhiệm vụ tuyệt mật","text":"Đơn vị trực tiếp đảm nhận nhiệm vụ đặc biệt này được đặt phiên hiệu là Đoàn 69, trực thuộc Bộ Quốc phòng, quy tụ những cán bộ, chiến sĩ, y bác sĩ được tuyển chọn kỹ lưỡng. Mọi thông tin về công việc của Đoàn 69 đều thuộc diện tuyệt mật: nhiều cán bộ, chiến sĩ trong đơn vị suốt nhiều năm liền không thể kể cho người thân biết mình đang làm nhiệm vụ gì, ở đâu. Công việc bảo quản thi hài đòi hỏi những điều kiện kỹ thuật nghiêm ngặt về nhiệt độ, độ ẩm, ánh sáng — những điều kiện rất khó bảo đảm giữa thời chiến, khi điện lưới có thể bị cắt bất cứ lúc nào vì bom đạn, và mọi thiết bị, hóa chất cần thiết đều phải được vận chuyển bí mật từ xa. Gần bảy năm sau, ngày 14 tháng 5 năm 1976, đơn vị này mới được kiện toàn thành Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh — tổ chức vẫn đảm nhận nhiệm vụ gìn giữ thi hài Người cho đến tận hôm nay.","doc":2},{"loai":"doan","tieu_de":"K9 — căn cứ giữa rừng Ba Vì","text":"Hà Nội cuối năm 1969 không còn là nơi an toàn: máy bay Mỹ liên tục đánh phá miền Bắc, và bất kỳ mục tiêu quan trọng nào ở thủ đô cũng có thể trở thành nơi ném bom. Thi hài Chủ tịch Hồ Chí Minh vì vậy được bí mật đưa lên một căn cứ mang mật danh K9, giữa khu rừng Đá Chông, huyện Ba Vì, cách Hà Nội khoảng 60 cây số về phía tây — nơi Bác từng chọn khảo sát từ năm 1957 để làm khu căn cứ dự phòng của Trung ương. Tại K9, một công trình đặc biệt được xây dựng để bảo quản thi hài Người trong điều kiện kỹ thuật khắt khe nhất có thể giữa hoàn cảnh chiến tranh; cán bộ, chiến sĩ Đoàn 69 cùng các chuyên gia Liên Xô thay nhau túc trực ngày đêm, không rời vị trí, kể cả trong những đợt máy bay Mỹ oanh tạc vùng phụ cận.","doc":3},{"loai":"doan","tieu_de":"Những bàn tay xa lạ, tấm lòng gần gũi","text":"Sự giúp đỡ của các chuyên gia y tế, kỹ thuật Liên Xô trong suốt quá trình gìn giữ thi hài Chủ tịch Hồ Chí Minh là một chương hợp tác đặc biệt trong quan hệ hai nước. Từ những ngày đầu tháng 9 năm 1969, đoàn chuyên gia Liên Xô — những người từng có kinh nghiệm với công việc tương tự — đã sang Việt Nam, trực tiếp hướng dẫn kỹ thuật bảo quản, đồng thời cùng ăn ở, làm việc ngay tại K9 giữa những điều kiện thiếu thốn của một đất nước đang có chiến tranh. Sự hợp tác này còn tiếp tục nhiều năm sau ngày Lăng được khánh thành, khi các chuyên gia Liên Xô định kỳ sang Việt Nam kiểm tra, duy trì tình trạng thi hài Người. Với những cán bộ, chiến sĩ Việt Nam khi ấy, đây không chỉ là một quan hệ hợp tác kỹ thuật, mà còn là tình cảm quốc tế trong sáng, được xây đắp qua từng ngày làm việc chung dưới mái nhà giữa rừng Ba Vì.","doc":4},{"loai":"anh","src":"textures/bang_w/G17_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sáu năm gìn giữ thi hài Bác giữa chiến tranh”, nhìn từ xa."},{"loai":"ban_co_biet","text":"Khu K9 – Đá Chông ngày nay là khu di tích lịch sử mở cửa đón khách tham quan, nơi lưu dấu những năm tháng thi hài Chủ tịch Hồ Chí Minh được bảo vệ, giữ gìn trong chiến tranh.","nguon_ten":"Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","doc":5},{"loai":"doan","tieu_de":"Những chuyến đi trong đêm","text":"Theo các tài liệu đã công bố, trong sáu năm chiến tranh, có những thời điểm thi hài Chủ tịch Hồ Chí Minh còn phải được di chuyển đến các địa điểm khác ngoài K9 để bảo đảm an toàn tuyệt đối trước nguy cơ bị đánh phá. Mỗi lần di chuyển là một chiến dịch được tính toán tỉ mỉ đến từng phút, huy động các đơn vị quân đội bảo vệ dọc đường, và luôn diễn ra vào ban đêm để giữ bí mật tối đa. Với những người lính trong Đoàn 69, đó là những năm tháng gần như không có khái niệm ngày nghỉ: mỗi ca trực là một trách nhiệm không được phép sai sót, dù chỉ là một độ lệch nhỏ về nhiệt độ hay độ ẩm trong căn phòng gìn giữ thi hài. Nhiều người trong số họ, khi được hỏi lại nhiều năm sau, chỉ nói ngắn gọn rằng đó là mệnh lệnh của trái tim, không cần ai phải nhắc nhở.","doc":6},{"loai":"doan","tieu_de":"Từ bàn đàm phán Paris đến công trường Ba Đình","text":"Ngày 27 tháng 1 năm 1973, Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết tại Paris, Pháp, mở ra hy vọng về một nền hòa bình, dù cuộc chiến trên chiến trường miền Nam còn tiếp diễn thêm hai năm nữa. Đúng ngày 2 tháng 9 năm 1973, tròn bốn năm sau ngày Chủ tịch Hồ Chí Minh đi xa, công trình Lăng của Người chính thức được khởi công tại Quảng trường Ba Đình. Công trường quy tụ lực lượng từ nhiều ngành, nhiều địa phương trong cả nước; đá, gỗ quý, cây xanh được vận chuyển về từ khắp các miền, với sự hợp tác kỹ thuật của các chuyên gia Liên Xô. Với Đoàn 69, việc khởi công Lăng cũng đồng nghĩa với một nhiệm vụ mới: chuẩn bị mọi điều kiện để chuyển thi hài Người từ K9 về nơi an nghỉ vĩnh viễn ngay khi công trình hoàn thành.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_guards_of_the_ho_chi_minh_mausoleum.jpg","chu_thich":"Đội tiêu binh danh dự trước Lăng hôm nay — sự tiếp nối của nhiệm vụ canh giữ, bảo vệ mà Đoàn 69 khởi đầu từ năm 1969.","credit":"Ảnh: Christophe95 · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ngày 18 tháng 7 và ngày 29 tháng 8 năm 1975","text":"Ngày 30 tháng 4 năm 1975, miền Nam hoàn toàn giải phóng, đất nước thống nhất sau hơn hai mươi năm chia cắt. Chưa đầy ba tháng sau, ngày 18 tháng 7 năm 1975, thi hài Chủ tịch Hồ Chí Minh được bí mật đưa từ K9 về đặt tại Lăng vừa hoàn thành ở Quảng trường Ba Đình; căn cứ K9 từ đó trở thành nơi dự phòng. Ngày 29 tháng 8 năm 1975, chưa đầy bốn tháng sau ngày thống nhất, Lăng Chủ tịch Hồ Chí Minh được khánh thành, kịp dịp kỷ niệm 30 năm Quốc khánh nước Việt Nam Dân chủ Cộng hòa. Nguyện vọng của những người đã âm thầm canh giữ thi hài Người suốt sáu năm chiến tranh trở thành hiện thực: đồng bào cả nước, trong đó có đồng bào miền Nam mà sinh thời Người luôn đau đáu nhớ về, giờ đây có thể vào viếng Người ngay giữa Thủ đô, trong thời bình.","doc":8},{"loai":"anh","src":"textures/bang_w/G17_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sáu năm gìn giữ thi hài Bác giữa chiến tranh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Những người không tên","text":"Suốt sáu năm ấy, danh tính của những người trực tiếp làm nhiệm vụ trong Đoàn 69 hầu như không được nhắc đến công khai. Họ sống, làm việc dưới những cái tên giản dị, không được kể công trạng khi nhiệm vụ còn phải giữ bí mật quân sự, và có người phải xa gia đình liền nhiều năm mà không thể giải thích lý do. Chỉ nhiều năm sau, khi tư liệu dần được công bố, những câu chuyện về sự tận tụy, cả những hy sinh thầm lặng của họ mới được kể lại trên báo chí, trong các cuộc gặp mặt truyền thống của Bộ Tư lệnh Bảo vệ Lăng. Với họ, phần thưởng lớn nhất có lẽ không phải một tấm huân chương, mà là hình ảnh dòng người nối dài trước Lăng mỗi buổi sáng — bằng chứng giản dị cho thấy nhiệm vụ năm xưa đã không uổng phí.","doc":9},{"loai":"ban_co_biet","text":"Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký ngày 27/1/1973 tại Paris, Pháp, với sự tham gia của bốn bên: Việt Nam Dân chủ Cộng hòa, Hoa Kỳ, Cộng hòa miền Nam Việt Nam và Việt Nam Cộng hòa.","nguon_ten":"Hiệp định Paris về Việt Nam, 1973","doc":10},{"loai":"doan","tieu_de":"Ý nghĩa của sáu năm thầm lặng","text":"Nhìn lại, sáu năm gìn giữ thi hài Chủ tịch Hồ Chí Minh giữa chiến tranh là một minh chứng đặc biệt cho tình cảm của một dân tộc dành cho lãnh tụ của mình, được thực hiện trong hoàn cảnh ngặt nghèo bậc nhất: đất nước còn chia cắt, bom đạn còn trút xuống hằng ngày, và mọi nguồn lực đều phải ưu tiên cho tiền tuyến. Ở một góc nhìn khác, đó cũng là câu chuyện về sự hợp tác quốc tế trong những năm chiến tranh Lạnh, khi Liên Xô — đồng minh thân thiết của Việt Nam — đã chia sẻ những kinh nghiệm, kỹ thuật quý giá nhất mà mình có. Với mỗi cán bộ, chiến sĩ trong Đoàn 69, sáu năm ấy có lẽ là quãng thời gian đặc biệt nhất trong đời quân ngũ: không tiếng súng, không trận đánh, nhưng đòi hỏi một kỷ luật thép và một tình cảm sâu nặng dành cho vị lãnh tụ mà nhiều người trong số họ chưa từng một lần được gặp khi Người còn sống.","doc":11},{"loai":"anh","src":"textures/bang_w/G17_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sáu năm gìn giữ thi hài Bác giữa chiến tranh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay: nhiệm vụ không có ngày kết thúc","text":"Sau ngày 29 tháng 8 năm 1975, nhiệm vụ gìn giữ thi hài Chủ tịch Hồ Chí Minh không dừng lại mà chuyển sang một giai đoạn mới, liên tục cho đến hôm nay dưới sự đảm nhiệm của Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh. Khu di tích K9 – Đá Chông giữa rừng Ba Vì, nơi từng giữ bí mật tuyệt đối suốt sáu năm chiến tranh, nay mở cửa đón khách tham quan, kể lại câu chuyện về những người lính gần như vô danh đã hoàn thành một nhiệm vụ chưa từng có tiền lệ. Đứng trước Lăng hôm nay, giữa tiếng bước chân đều đặn của đội tiêu binh danh dự, ít ai hình dung hết những đêm không ngủ, những chuyến di chuyển trong bóng tối và sáu năm âm thầm của Đoàn 69 để có được khoảnh khắc giản dị này: đồng bào cả nước, không phân biệt vùng miền, được đứng lặng trước Người.","doc":12}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 10, NXB Chính trị quốc gia","Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Thông báo của Bộ Chính trị về Di chúc và ngày mất của Chủ tịch Hồ Chí Minh, năm 1989","Hiệp định Paris về Việt Nam, 1973"],"doc":[{"t":"1969–1975: hành trình thầm lặng gìn giữ thi hài Chủ tịch Hồ Chí Minh. Tháng 9 năm 1969, khi bom Mỹ vẫn trút xuống miền Bắc và đất nước còn chia cắt đôi bờ, một đơn vị đặc biệt nhận nhiệm vụ chưa từng có tiền lệ: giữ gìn thi hài Chủ tịch Hồ Chí Minh cho muôn đời sau. Suốt sáu năm, giữa những đợt sơ tán, những đêm báo động và cả nỗi lo bom rơi ngay trên đầu, họ đã hoàn thành nhiệm vụ ấy trong im lặng tuyệt đối. Đây là câu chuyện về căn cứ mang mật danh K9, về những người lính mang tên Đoàn 69, và về ngày họ đưa Người trở về giữa lòng Hà Nội."},{"t":"Một quyết định giữa lúc đất nước lâm nguy. Chủ tịch Hồ Chí Minh qua đời ngày 2 tháng 9 năm 1969, khi cuộc kháng chiến chống Mỹ, cứu nước đang ở giai đoạn ác liệt và đất nước còn chia cắt làm hai miền. Xuất phát từ tình cảm, nguyện vọng thiết tha của nhân dân cả nước — nhất là đồng bào, chiến sĩ miền Nam chưa từng có dịp gặp Người — Bộ Chính trị quyết định giữ gìn lâu dài thi hài của Người, để một ngày đất nước thống nhất, đồng bào mọi miền đều có thể đến viếng. Đây là một quyết định chưa có tiền lệ ở Việt Nam, được thực hiện với sự giúp đỡ tận tình của các chuyên gia y tế Liên Xô — những người đã có kinh nghiệm gìn giữ thi hài lãnh tụ từ nhiều năm trước đó. Từ ngày 6 đến hết ngày 8 tháng 9 năm 1969, trong lúc công việc gìn giữ vừa mới bắt đầu trong bí mật, hàng chục vạn đồng bào, chiến sĩ và bạn bè quốc tế đã nối nhau vào viếng Người tại Hội trường Ba Đình, trước khi cả nước bước vào lễ truy điệu trọng thể ngày 9 tháng 9."},{"t":"Đoàn 69 và nhiệm vụ tuyệt mật. Đơn vị trực tiếp đảm nhận nhiệm vụ đặc biệt này được đặt phiên hiệu là Đoàn 69, trực thuộc Bộ Quốc phòng, quy tụ những cán bộ, chiến sĩ, y bác sĩ được tuyển chọn kỹ lưỡng. Mọi thông tin về công việc của Đoàn 69 đều thuộc diện tuyệt mật: nhiều cán bộ, chiến sĩ trong đơn vị suốt nhiều năm liền không thể kể cho người thân biết mình đang làm nhiệm vụ gì, ở đâu. Công việc bảo quản thi hài đòi hỏi những điều kiện kỹ thuật nghiêm ngặt về nhiệt độ, độ ẩm, ánh sáng — những điều kiện rất khó bảo đảm giữa thời chiến, khi điện lưới có thể bị cắt bất cứ lúc nào vì bom đạn, và mọi thiết bị, hóa chất cần thiết đều phải được vận chuyển bí mật từ xa. Gần bảy năm sau, ngày 14 tháng 5 năm 1976, đơn vị này mới được kiện toàn thành Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh — tổ chức vẫn đảm nhận nhiệm vụ gìn giữ thi hài Người cho đến tận hôm nay."},{"t":"K9 — căn cứ giữa rừng Ba Vì. Hà Nội cuối năm 1969 không còn là nơi an toàn: máy bay Mỹ liên tục đánh phá miền Bắc, và bất kỳ mục tiêu quan trọng nào ở thủ đô cũng có thể trở thành nơi ném bom. Thi hài Chủ tịch Hồ Chí Minh vì vậy được bí mật đưa lên một căn cứ mang mật danh K9, giữa khu rừng Đá Chông, huyện Ba Vì, cách Hà Nội khoảng 60 cây số về phía tây — nơi Bác từng chọn khảo sát từ năm 1957 để làm khu căn cứ dự phòng của Trung ương. Tại K9, một công trình đặc biệt được xây dựng để bảo quản thi hài Người trong điều kiện kỹ thuật khắt khe nhất có thể giữa hoàn cảnh chiến tranh; cán bộ, chiến sĩ Đoàn 69 cùng các chuyên gia Liên Xô thay nhau túc trực ngày đêm, không rời vị trí, kể cả trong những đợt máy bay Mỹ oanh tạc vùng phụ cận."},{"t":"Những bàn tay xa lạ, tấm lòng gần gũi. Sự giúp đỡ của các chuyên gia y tế, kỹ thuật Liên Xô trong suốt quá trình gìn giữ thi hài Chủ tịch Hồ Chí Minh là một chương hợp tác đặc biệt trong quan hệ hai nước. Từ những ngày đầu tháng 9 năm 1969, đoàn chuyên gia Liên Xô — những người từng có kinh nghiệm với công việc tương tự — đã sang Việt Nam, trực tiếp hướng dẫn kỹ thuật bảo quản, đồng thời cùng ăn ở, làm việc ngay tại K9 giữa những điều kiện thiếu thốn của một đất nước đang có chiến tranh. Sự hợp tác này còn tiếp tục nhiều năm sau ngày Lăng được khánh thành, khi các chuyên gia Liên Xô định kỳ sang Việt Nam kiểm tra, duy trì tình trạng thi hài Người. Với những cán bộ, chiến sĩ Việt Nam khi ấy, đây không chỉ là một quan hệ hợp tác kỹ thuật, mà còn là tình cảm quốc tế trong sáng, được xây đắp qua từng ngày làm việc chung dưới mái nhà giữa rừng Ba Vì."},{"t":"Bạn có biết? Khu K9 – Đá Chông ngày nay là khu di tích lịch sử mở cửa đón khách tham quan, nơi lưu dấu những năm tháng thi hài Chủ tịch Hồ Chí Minh được bảo vệ, giữ gìn trong chiến tranh."},{"t":"Những chuyến đi trong đêm. Theo các tài liệu đã công bố, trong sáu năm chiến tranh, có những thời điểm thi hài Chủ tịch Hồ Chí Minh còn phải được di chuyển đến các địa điểm khác ngoài K9 để bảo đảm an toàn tuyệt đối trước nguy cơ bị đánh phá. Mỗi lần di chuyển là một chiến dịch được tính toán tỉ mỉ đến từng phút, huy động các đơn vị quân đội bảo vệ dọc đường, và luôn diễn ra vào ban đêm để giữ bí mật tối đa. Với những người lính trong Đoàn 69, đó là những năm tháng gần như không có khái niệm ngày nghỉ: mỗi ca trực là một trách nhiệm không được phép sai sót, dù chỉ là một độ lệch nhỏ về nhiệt độ hay độ ẩm trong căn phòng gìn giữ thi hài. Nhiều người trong số họ, khi được hỏi lại nhiều năm sau, chỉ nói ngắn gọn rằng đó là mệnh lệnh của trái tim, không cần ai phải nhắc nhở."},{"t":"Từ bàn đàm phán Paris đến công trường Ba Đình. Ngày 27 tháng 1 năm 1973, Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết tại Paris, Pháp, mở ra hy vọng về một nền hòa bình, dù cuộc chiến trên chiến trường miền Nam còn tiếp diễn thêm hai năm nữa. Đúng ngày 2 tháng 9 năm 1973, tròn bốn năm sau ngày Chủ tịch Hồ Chí Minh đi xa, công trình Lăng của Người chính thức được khởi công tại Quảng trường Ba Đình. Công trường quy tụ lực lượng từ nhiều ngành, nhiều địa phương trong cả nước; đá, gỗ quý, cây xanh được vận chuyển về từ khắp các miền, với sự hợp tác kỹ thuật của các chuyên gia Liên Xô. Với Đoàn 69, việc khởi công Lăng cũng đồng nghĩa với một nhiệm vụ mới: chuẩn bị mọi điều kiện để chuyển thi hài Người từ K9 về nơi an nghỉ vĩnh viễn ngay khi công trình hoàn thành."},{"t":"Ngày 18 tháng 7 và ngày 29 tháng 8 năm 1975. Ngày 30 tháng 4 năm 1975, miền Nam hoàn toàn giải phóng, đất nước thống nhất sau hơn hai mươi năm chia cắt. Chưa đầy ba tháng sau, ngày 18 tháng 7 năm 1975, thi hài Chủ tịch Hồ Chí Minh được bí mật đưa từ K9 về đặt tại Lăng vừa hoàn thành ở Quảng trường Ba Đình; căn cứ K9 từ đó trở thành nơi dự phòng. Ngày 29 tháng 8 năm 1975, chưa đầy bốn tháng sau ngày thống nhất, Lăng Chủ tịch Hồ Chí Minh được khánh thành, kịp dịp kỷ niệm 30 năm Quốc khánh nước Việt Nam Dân chủ Cộng hòa. Nguyện vọng của những người đã âm thầm canh giữ thi hài Người suốt sáu năm chiến tranh trở thành hiện thực: đồng bào cả nước, trong đó có đồng bào miền Nam mà sinh thời Người luôn đau đáu nhớ về, giờ đây có thể vào viếng Người ngay giữa Thủ đô, trong thời bình."},{"t":"Những người không tên. Suốt sáu năm ấy, danh tính của những người trực tiếp làm nhiệm vụ trong Đoàn 69 hầu như không được nhắc đến công khai. Họ sống, làm việc dưới những cái tên giản dị, không được kể công trạng khi nhiệm vụ còn phải giữ bí mật quân sự, và có người phải xa gia đình liền nhiều năm mà không thể giải thích lý do. Chỉ nhiều năm sau, khi tư liệu dần được công bố, những câu chuyện về sự tận tụy, cả những hy sinh thầm lặng của họ mới được kể lại trên báo chí, trong các cuộc gặp mặt truyền thống của Bộ Tư lệnh Bảo vệ Lăng. Với họ, phần thưởng lớn nhất có lẽ không phải một tấm huân chương, mà là hình ảnh dòng người nối dài trước Lăng mỗi buổi sáng — bằng chứng giản dị cho thấy nhiệm vụ năm xưa đã không uổng phí."},{"t":"Bạn có biết? Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký ngày 27/1/1973 tại Paris, Pháp, với sự tham gia của bốn bên: Việt Nam Dân chủ Cộng hòa, Hoa Kỳ, Cộng hòa miền Nam Việt Nam và Việt Nam Cộng hòa."},{"t":"Ý nghĩa của sáu năm thầm lặng. Nhìn lại, sáu năm gìn giữ thi hài Chủ tịch Hồ Chí Minh giữa chiến tranh là một minh chứng đặc biệt cho tình cảm của một dân tộc dành cho lãnh tụ của mình, được thực hiện trong hoàn cảnh ngặt nghèo bậc nhất: đất nước còn chia cắt, bom đạn còn trút xuống hằng ngày, và mọi nguồn lực đều phải ưu tiên cho tiền tuyến. Ở một góc nhìn khác, đó cũng là câu chuyện về sự hợp tác quốc tế trong những năm chiến tranh Lạnh, khi Liên Xô — đồng minh thân thiết của Việt Nam — đã chia sẻ những kinh nghiệm, kỹ thuật quý giá nhất mà mình có. Với mỗi cán bộ, chiến sĩ trong Đoàn 69, sáu năm ấy có lẽ là quãng thời gian đặc biệt nhất trong đời quân ngũ: không tiếng súng, không trận đánh, nhưng đòi hỏi một kỷ luật thép và một tình cảm sâu nặng dành cho vị lãnh tụ mà nhiều người trong số họ chưa từng một lần được gặp khi Người còn sống."},{"t":"Dấu tích hôm nay: nhiệm vụ không có ngày kết thúc. Sau ngày 29 tháng 8 năm 1975, nhiệm vụ gìn giữ thi hài Chủ tịch Hồ Chí Minh không dừng lại mà chuyển sang một giai đoạn mới, liên tục cho đến hôm nay dưới sự đảm nhiệm của Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh. Khu di tích K9 – Đá Chông giữa rừng Ba Vì, nơi từng giữ bí mật tuyệt đối suốt sáu năm chiến tranh, nay mở cửa đón khách tham quan, kể lại câu chuyện về những người lính gần như vô danh đã hoàn thành một nhiệm vụ chưa từng có tiền lệ. Đứng trước Lăng hôm nay, giữa tiếng bước chân đều đặn của đội tiêu binh danh dự, ít ai hình dung hết những đêm không ngủ, những chuyến di chuyển trong bóng tối và sáu năm âm thầm của Đoàn 69 để có được khoảnh khắc giản dị này: đồng bào cả nước, không phân biệt vùng miền, được đứng lặng trước Người."}],"so_chu":1937},{"i":2,"tieu_de_bang":"Di chúc: hai lần công bố, một nguyện vọng","tieu_de":"Sau ngày 2/9/1969: bản Di chúc đến với nhân dân qua hai lần công bố, cách nhau hai mươi năm","sapo":"Ở gian Phủ Chủ tịch, bạn đã thấy Bác lặng lẽ ngồi viết Di chúc trên nhà sàn giữa vườn cây. Gian Di sản kể tiếp phần sau của câu chuyện ấy: bản Di chúc thiêng liêng đó đến với nhân dân như thế nào, vì sao phải hai mươi năm sau toàn văn mới được công bố đầy đủ, và có một lời dặn giản dị của Người mà cho đến nay vẫn chưa thể thực hiện đúng như ý nguyện.","bia":{"src":"textures/bai/G17_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Buổi sáng ngày 9 tháng 9 năm 1969","text":"Chủ tịch Hồ Chí Minh từ trần lúc 9 giờ 47 phút sáng ngày 2 tháng 9 năm 1969 tại Hà Nội, hưởng thọ 79 tuổi. Một tuần sau, ngày 9 tháng 9 năm 1969, lễ truy điệu trọng thể được tổ chức tại Quảng trường Ba Đình — nơi 24 năm trước, cũng chính Người đã đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Giữa không khí trang nghiêm của buổi lễ, trước hàng vạn đồng bào có mặt tại quảng trường và qua làn sóng phát thanh vang đến mọi miền đất nước, bản Di chúc của Chủ tịch Hồ Chí Minh được công bố. Văn bản công bố năm ấy do Bộ Chính trị chọn lọc, chỉnh lý từ các bản viết tay của Người trong các năm 1965, 1968 và 1969 — quá trình viết và sửa Di chúc, với những dòng chữ ngày một run hơn theo tuổi tác, đã được kể ở gian Phủ Chủ tịch của bảo tàng số này.","doc":1},{"loai":"doan","tieu_de":"Đến với nhân dân qua báo chí, phát thanh","text":"Ngay trong ngày 9 tháng 9 năm 1969, toàn văn bản Di chúc theo bản chỉnh lý được công bố năm ấy đã đăng trang trọng trên báo Nhân Dân — cơ quan ngôn luận của Đảng — và được phát đi phát lại nhiều lần trên Đài Tiếng nói Việt Nam, để đồng bào ở những vùng xa xôi nhất, kể cả đồng bào, chiến sĩ đang chiến đấu trên các chiến trường miền Nam, cũng có thể nghe được lời dặn dò cuối cùng của Người. Ngay sau đó, Di chúc được in thành sách mỏng, phát hành rộng rãi tới từng chi bộ, từng đơn vị bộ đội, để việc học tập, quán triệt Di chúc trở thành một đợt sinh hoạt chính trị sâu rộng chưa từng có, kéo dài từ những ngày cuối năm 1969 sang đầu năm 1970 trong cả nước. Ở nhiều địa phương, các buổi đọc và thảo luận Di chúc được tổ chức ngay tại nơi sản xuất, nơi chiến đấu, biến lời dặn dò của Người thành những đợt thi đua lao động, chiến đấu cụ thể mang tên “sống, chiến đấu, lao động và học tập theo gương Bác Hồ vĩ đại”.","doc":2},{"loai":"doan","tieu_de":"Một bản Di chúc được viết trong bốn năm","text":"Bản Di chúc mà Chủ tịch Hồ Chí Minh để lại không phải một văn bản viết một lần rồi giữ nguyên, mà là kết quả của một quá trình suy nghĩ, viết và sửa chữa kéo dài từ năm 1965 đến năm 1969. Người thường viết vào dịp sinh nhật của chính mình — thời điểm Người cho là thích hợp để nhìn lại một năm đã qua và dặn dò những điều cần thiết. Bản Di chúc đề cập nhiều vấn đề: việc Đảng, việc bồi dưỡng thế hệ cách mạng cho đời sau, phong trào cộng sản thế giới, cuộc kháng chiến chống Mỹ, việc chăm lo đời sống nhân dân sau chiến tranh, và cuối cùng là những dòng viết về việc riêng của Người — ngắn gọn, giản dị, không một lời than vãn. Bản công bố năm 1969 là bản đã được Bộ Chính trị lựa chọn, sắp xếp lại từ những trang viết ấy; còn toàn bộ quá trình viết và sửa qua từng năm chỉ được công khai đầy đủ hai mươi năm sau đó.","doc":3},{"loai":"trich","text":"Suốt đời tôi hết lòng hết sức phục vụ Tổ quốc, phục vụ cách mạng, phục vụ nhân dân. Nay dù phải từ biệt thế giới này, tôi không có điều gì phải hối hận, chỉ tiếc là tiếc rằng không được phục vụ lâu hơn nữa, nhiều hơn nữa.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Di chúc của Chủ tịch Hồ Chí Minh","doc":4},{"loai":"anh","src":"textures/bang_w/G17_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di chúc: hai lần công bố, một nguyện vọng”, nhìn từ xa."},{"loai":"doan","tieu_de":"Hai mươi năm sau: một thông báo của Bộ Chính trị","text":"Tháng 8 năm 1989, tròn hai mươi năm kể từ ngày Chủ tịch Hồ Chí Minh qua đời, Bộ Chính trị Ban Chấp hành Trung ương Đảng ra thông báo về một số vấn đề liên quan đến Di chúc và ngày mất của Người. Lần đầu tiên, toàn văn các bản viết tay của Người trong các năm 1965, 1968 và 1969 được công bố đầy đủ, không qua chỉnh lý, để nhân dân có thể theo dõi trọn vẹn quá trình Người suy nghĩ, viết và sửa từng câu chữ qua nhiều năm. Cùng với đó, thông báo cũng đính chính một chi tiết đã được giữ kín suốt hai mươi năm: Người mất vào ngày 2 tháng 9 năm 1969, chứ không phải ngày 3 tháng 9 như đã công bố năm ấy. Lý do của sự sai lệch một ngày này gắn liền với một quyết định tế nhị: để ngày mất của Người — một nỗi đau lớn của cả dân tộc — không trùng vào đúng ngày Quốc khánh, ngày vui chung của đất nước, Bộ Chính trị năm 1969 đã quyết định công bố lùi tin buồn lại một ngày.","doc":5},{"loai":"ban_co_biet","text":"Trong phần viết thêm năm 1968, nói về những việc cần làm sau khi cuộc chống Mỹ, cứu nước thắng lợi, Bác viết: “Nay ta đã hoàn toàn thắng lợi, tôi có ý đề nghị miễn thuế nông nghiệp 1 năm cho các hợp tác xã nông nghiệp để cho đồng bào hỉ hả, mát dạ, mát lòng, thêm niềm phấn khởi, đẩy mạnh sản xuất.”","nguon_ten":"Di chúc của Chủ tịch Hồ Chí Minh (toàn văn công bố năm 1989)","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_hanoi_vietnam_interiors_of_ho_chi_minh_museum.jpg","chu_thich":"Không gian trưng bày bên trong Bảo tàng Hồ Chí Minh, nơi giới thiệu tư liệu, hình ảnh về quá trình Người viết Di chúc.","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một lời dặn không thể thực hiện trọn vẹn","text":"Trong phần viết về việc riêng, Chủ tịch Hồ Chí Minh dặn rằng khi Người qua đời, chớ nên tổ chức điếu phúng linh đình, để khỏi lãng phí thì giờ và tiền bạc của nhân dân. Người đề nghị thi hài được hỏa táng, vừa hợp vệ sinh vừa không tốn đất ruộng, rồi chia tro thành ba phần, đựng trong ba hộp sành, đặt ở ba miền Bắc, Trung, Nam. Người dặn mỗi miền chọn một quả đồi mà đặt hộp tro, trên đó không xây bia đá, tượng đồng, chỉ dựng một ngôi nhà giản đơn, rộng rãi, mát mẻ để ai đến thăm có chỗ nghỉ chân, và ai đến thì trồng một cây làm kỷ niệm, lâu dần sẽ thành rừng cây đẹp. Nhưng xuất phát từ tình cảm và nguyện vọng thiết tha của nhân dân cả nước, nhất là đồng bào miền Nam khi ấy chưa có dịp gặp Người, Bộ Chính trị đã quyết định giữ gìn lâu dài thi hài của Người thay vì làm theo đúng lời dặn ấy — một quyết định khó khăn được kể chi tiết ở chuyên đề “Sáu năm gìn giữ thi hài Bác giữa chiến tranh” ngay trong gian này.","doc":7},{"loai":"doan","tieu_de":"Một tài liệu vẫn còn tính thời sự","text":"Không chỉ là một áng văn để tưởng nhớ, Di chúc còn được xem như một cương lĩnh hành động. Ngay sau khi Người qua đời, nhiều nội dung trong Di chúc — về miễn thuế nông nghiệp cho nông dân, về chính sách với bộ đội, thương binh, gia đình liệt sĩ, về hàn gắn vết thương chiến tranh — đã lần lượt được Đảng, Nhà nước cụ thể hóa thành chủ trương, chính sách trong những năm sau ngày đất nước thống nhất. Ở một tầm mức khác, những câu chữ ngắn gọn về giữ gìn sự đoàn kết, về thực hành tự phê bình và phê bình, về vai trò “người đầy tớ thật trung thành của nhân dân” vẫn thường xuyên được viện dẫn trong các văn kiện, nghị quyết của Đảng cho đến hôm nay, như một thước đo để mỗi thế hệ cán bộ, đảng viên soi lại chính mình.","doc":8},{"loai":"anh","src":"textures/bang_w/G17_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di chúc: hai lần công bố, một nguyện vọng”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một áng văn trong nhà trường","text":"Không chỉ là văn kiện chính trị, Di chúc còn được đánh giá là một áng văn chính luận mẫu mực: câu chữ giản dị, súc tích, tình cảm chân thành mà vẫn chặt chẽ về lập luận. Nhiều thế hệ học sinh Việt Nam đã được học, phân tích những đoạn trích trong Di chúc ở chương trình Ngữ văn phổ thông, xem đây là một trong những văn bản tiêu biểu cho phong cách viết của Chủ tịch Hồ Chí Minh — ngắn gọn mà sâu sắc, không cầu kỳ hoa mỹ nhưng chan chứa tình cảm. Mỗi độ tháng Chín về, việc đọc lại Di chúc cũng trở thành một nội dung quen thuộc trong sinh hoạt của các chi bộ, cơ quan, trường học trên cả nước, như một dịp để mỗi người tự soi lại những điều Người đã căn dặn. Không ít nhà nghiên cứu văn học, sử học trong và ngoài nước cũng đã dành nhiều công trình để phân tích riêng về giá trị tư tưởng và văn chương của bản Di chúc này.","doc":9},{"loai":"doan","tieu_de":"Từ lời dặn đến việc làm","text":"Hơn nửa thế kỷ đã qua, bản Di chúc ấy vẫn được đọc lại mỗi dịp tháng Năm — sinh nhật Người — và tháng Chín — ngày Người ra đi. Những lời căn dặn về giữ gìn sự đoàn kết, thống nhất trong Đảng “như giữ gìn con ngươi của mắt mình”, về thực hành dân chủ rộng rãi, thường xuyên và nghiêm chỉnh tự phê bình và phê bình, về bồi dưỡng thế hệ cách mạng cho đời sau, về không ngừng nâng cao đời sống của nhân dân, đã trở thành những chuẩn mực cụ thể được nhắc lại trong sinh hoạt của các tổ chức đảng, đoàn thể suốt nhiều thập niên. Cuộc vận động học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh đang diễn ra hôm nay, suy cho cùng, chính là cách mỗi thế hệ tiếp tục thực hiện những điều Người đã ân cần căn dặn trong những trang viết cuối cùng ấy.","doc":10},{"loai":"ban_co_biet","text":"Bản Di chúc của Chủ tịch Hồ Chí Minh là một trong số ít văn bản viết tay được Nhà nước Việt Nam công nhận là Bảo vật quốc gia, cùng với các tác phẩm “Đường Kách mệnh”, “Nhật ký trong tù”, “Lời kêu gọi toàn quốc kháng chiến” và “Lời kêu gọi đồng bào và chiến sĩ cả nước” của Người.","nguon_ten":"Hồ sơ Bảo vật quốc gia — Cục Di sản văn hóa, Bộ Văn hóa, Thể thao và Du lịch","doc":11},{"loai":"anh","src":"textures/bang_w/G17_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Di chúc: hai lần công bố, một nguyện vọng”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Bản viết tay gốc của Di chúc — cùng các bản Người viết, sửa qua từng năm — hiện được bảo quản theo chế độ đặc biệt tại Kho Lưu trữ Trung ương Đảng, chỉ tồn tại dưới dạng độc bản. Bản sao cùng nhiều hình ảnh, tư liệu liên quan đến quá trình Người viết Di chúc được giới thiệu tại Bảo tàng Hồ Chí Minh, liền kề Lăng và Quảng trường Ba Đình, để bất cứ ai cũng có thể tìm hiểu về những trang viết cuối cùng của Người. Đứng trước những tư liệu ấy hôm nay, người xem không chỉ thấy một văn kiện lịch sử, mà còn thấy nét chữ của một người đã dành những dòng cuối cùng trong đời để nghĩ về Đảng, về dân, về đất nước — và chỉ vài dòng ngắn ngủi cho riêng mình. Đó cũng là điểm khép lại trọn vẹn cho câu chuyện đã mở ra từ gian Phủ Chủ tịch: từ trang viết đầu tiên trên nhà sàn đến hành trình bản Di chúc đi vào đời sống của cả một dân tộc.","doc":12}],"nguon":["Di chúc của Chủ tịch Hồ Chí Minh (toàn văn), NXB Chính trị quốc gia","Thông báo của Bộ Chính trị về một số vấn đề liên quan đến Di chúc và ngày mất của Chủ tịch Hồ Chí Minh (8/1989)","Hồ Chí Minh – Biên niên tiểu sử, tập 10, NXB Chính trị quốc gia","Cục Di sản văn hóa, Bộ Văn hóa, Thể thao và Du lịch — Hồ sơ Bảo vật quốc gia"],"doc":[{"t":"Sau ngày 2/9/1969: bản Di chúc đến với nhân dân qua hai lần công bố, cách nhau hai mươi năm. Ở gian Phủ Chủ tịch, bạn đã thấy Bác lặng lẽ ngồi viết Di chúc trên nhà sàn giữa vườn cây. Gian Di sản kể tiếp phần sau của câu chuyện ấy: bản Di chúc thiêng liêng đó đến với nhân dân như thế nào, vì sao phải hai mươi năm sau toàn văn mới được công bố đầy đủ, và có một lời dặn giản dị của Người mà cho đến nay vẫn chưa thể thực hiện đúng như ý nguyện."},{"t":"Buổi sáng ngày 9 tháng 9 năm 1969. Chủ tịch Hồ Chí Minh từ trần lúc 9 giờ 47 phút sáng ngày 2 tháng 9 năm 1969 tại Hà Nội, hưởng thọ 79 tuổi. Một tuần sau, ngày 9 tháng 9 năm 1969, lễ truy điệu trọng thể được tổ chức tại Quảng trường Ba Đình — nơi 24 năm trước, cũng chính Người đã đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Giữa không khí trang nghiêm của buổi lễ, trước hàng vạn đồng bào có mặt tại quảng trường và qua làn sóng phát thanh vang đến mọi miền đất nước, bản Di chúc của Chủ tịch Hồ Chí Minh được công bố. Văn bản công bố năm ấy do Bộ Chính trị chọn lọc, chỉnh lý từ các bản viết tay của Người trong các năm 1965, 1968 và 1969 — quá trình viết và sửa Di chúc, với những dòng chữ ngày một run hơn theo tuổi tác, đã được kể ở gian Phủ Chủ tịch của bảo tàng số này."},{"t":"Đến với nhân dân qua báo chí, phát thanh. Ngay trong ngày 9 tháng 9 năm 1969, toàn văn bản Di chúc theo bản chỉnh lý được công bố năm ấy đã đăng trang trọng trên báo Nhân Dân — cơ quan ngôn luận của Đảng — và được phát đi phát lại nhiều lần trên Đài Tiếng nói Việt Nam, để đồng bào ở những vùng xa xôi nhất, kể cả đồng bào, chiến sĩ đang chiến đấu trên các chiến trường miền Nam, cũng có thể nghe được lời dặn dò cuối cùng của Người. Ngay sau đó, Di chúc được in thành sách mỏng, phát hành rộng rãi tới từng chi bộ, từng đơn vị bộ đội, để việc học tập, quán triệt Di chúc trở thành một đợt sinh hoạt chính trị sâu rộng chưa từng có, kéo dài từ những ngày cuối năm 1969 sang đầu năm 1970 trong cả nước. Ở nhiều địa phương, các buổi đọc và thảo luận Di chúc được tổ chức ngay tại nơi sản xuất, nơi chiến đấu, biến lời dặn dò của Người thành những đợt thi đua lao động, chiến đấu cụ thể mang tên “sống, chiến đấu, lao động và học tập theo gương Bác Hồ vĩ đại”."},{"t":"Một bản Di chúc được viết trong bốn năm. Bản Di chúc mà Chủ tịch Hồ Chí Minh để lại không phải một văn bản viết một lần rồi giữ nguyên, mà là kết quả của một quá trình suy nghĩ, viết và sửa chữa kéo dài từ năm 1965 đến năm 1969. Người thường viết vào dịp sinh nhật của chính mình — thời điểm Người cho là thích hợp để nhìn lại một năm đã qua và dặn dò những điều cần thiết. Bản Di chúc đề cập nhiều vấn đề: việc Đảng, việc bồi dưỡng thế hệ cách mạng cho đời sau, phong trào cộng sản thế giới, cuộc kháng chiến chống Mỹ, việc chăm lo đời sống nhân dân sau chiến tranh, và cuối cùng là những dòng viết về việc riêng của Người — ngắn gọn, giản dị, không một lời than vãn. Bản công bố năm 1969 là bản đã được Bộ Chính trị lựa chọn, sắp xếp lại từ những trang viết ấy; còn toàn bộ quá trình viết và sửa qua từng năm chỉ được công khai đầy đủ hai mươi năm sau đó."},{"t":"Suốt đời tôi hết lòng hết sức phục vụ Tổ quốc, phục vụ cách mạng, phục vụ nhân dân. Nay dù phải từ biệt thế giới này, tôi không có điều gì phải hối hận, chỉ tiếc là tiếc rằng không được phục vụ lâu hơn nữa, nhiều hơn nữa. — Chủ tịch Hồ Chí Minh"},{"t":"Hai mươi năm sau: một thông báo của Bộ Chính trị. Tháng 8 năm 1989, tròn hai mươi năm kể từ ngày Chủ tịch Hồ Chí Minh qua đời, Bộ Chính trị Ban Chấp hành Trung ương Đảng ra thông báo về một số vấn đề liên quan đến Di chúc và ngày mất của Người. Lần đầu tiên, toàn văn các bản viết tay của Người trong các năm 1965, 1968 và 1969 được công bố đầy đủ, không qua chỉnh lý, để nhân dân có thể theo dõi trọn vẹn quá trình Người suy nghĩ, viết và sửa từng câu chữ qua nhiều năm. Cùng với đó, thông báo cũng đính chính một chi tiết đã được giữ kín suốt hai mươi năm: Người mất vào ngày 2 tháng 9 năm 1969, chứ không phải ngày 3 tháng 9 như đã công bố năm ấy. Lý do của sự sai lệch một ngày này gắn liền với một quyết định tế nhị: để ngày mất của Người — một nỗi đau lớn của cả dân tộc — không trùng vào đúng ngày Quốc khánh, ngày vui chung của đất nước, Bộ Chính trị năm 1969 đã quyết định công bố lùi tin buồn lại một ngày."},{"t":"Bạn có biết? Trong phần viết thêm năm 1968, nói về những việc cần làm sau khi cuộc chống Mỹ, cứu nước thắng lợi, Bác viết: “Nay ta đã hoàn toàn thắng lợi, tôi có ý đề nghị miễn thuế nông nghiệp 1 năm cho các hợp tác xã nông nghiệp để cho đồng bào hỉ hả, mát dạ, mát lòng, thêm niềm phấn khởi, đẩy mạnh sản xuất.”"},{"t":"Một lời dặn không thể thực hiện trọn vẹn. Trong phần viết về việc riêng, Chủ tịch Hồ Chí Minh dặn rằng khi Người qua đời, chớ nên tổ chức điếu phúng linh đình, để khỏi lãng phí thì giờ và tiền bạc của nhân dân. Người đề nghị thi hài được hỏa táng, vừa hợp vệ sinh vừa không tốn đất ruộng, rồi chia tro thành ba phần, đựng trong ba hộp sành, đặt ở ba miền Bắc, Trung, Nam. Người dặn mỗi miền chọn một quả đồi mà đặt hộp tro, trên đó không xây bia đá, tượng đồng, chỉ dựng một ngôi nhà giản đơn, rộng rãi, mát mẻ để ai đến thăm có chỗ nghỉ chân, và ai đến thì trồng một cây làm kỷ niệm, lâu dần sẽ thành rừng cây đẹp. Nhưng xuất phát từ tình cảm và nguyện vọng thiết tha của nhân dân cả nước, nhất là đồng bào miền Nam khi ấy chưa có dịp gặp Người, Bộ Chính trị đã quyết định giữ gìn lâu dài thi hài của Người thay vì làm theo đúng lời dặn ấy — một quyết định khó khăn được kể chi tiết ở chuyên đề “Sáu năm gìn giữ thi hài Bác giữa chiến tranh” ngay trong gian này."},{"t":"Một tài liệu vẫn còn tính thời sự. Không chỉ là một áng văn để tưởng nhớ, Di chúc còn được xem như một cương lĩnh hành động. Ngay sau khi Người qua đời, nhiều nội dung trong Di chúc — về miễn thuế nông nghiệp cho nông dân, về chính sách với bộ đội, thương binh, gia đình liệt sĩ, về hàn gắn vết thương chiến tranh — đã lần lượt được Đảng, Nhà nước cụ thể hóa thành chủ trương, chính sách trong những năm sau ngày đất nước thống nhất. Ở một tầm mức khác, những câu chữ ngắn gọn về giữ gìn sự đoàn kết, về thực hành tự phê bình và phê bình, về vai trò “người đầy tớ thật trung thành của nhân dân” vẫn thường xuyên được viện dẫn trong các văn kiện, nghị quyết của Đảng cho đến hôm nay, như một thước đo để mỗi thế hệ cán bộ, đảng viên soi lại chính mình."},{"t":"Một áng văn trong nhà trường. Không chỉ là văn kiện chính trị, Di chúc còn được đánh giá là một áng văn chính luận mẫu mực: câu chữ giản dị, súc tích, tình cảm chân thành mà vẫn chặt chẽ về lập luận. Nhiều thế hệ học sinh Việt Nam đã được học, phân tích những đoạn trích trong Di chúc ở chương trình Ngữ văn phổ thông, xem đây là một trong những văn bản tiêu biểu cho phong cách viết của Chủ tịch Hồ Chí Minh — ngắn gọn mà sâu sắc, không cầu kỳ hoa mỹ nhưng chan chứa tình cảm. Mỗi độ tháng Chín về, việc đọc lại Di chúc cũng trở thành một nội dung quen thuộc trong sinh hoạt của các chi bộ, cơ quan, trường học trên cả nước, như một dịp để mỗi người tự soi lại những điều Người đã căn dặn. Không ít nhà nghiên cứu văn học, sử học trong và ngoài nước cũng đã dành nhiều công trình để phân tích riêng về giá trị tư tưởng và văn chương của bản Di chúc này."},{"t":"Từ lời dặn đến việc làm. Hơn nửa thế kỷ đã qua, bản Di chúc ấy vẫn được đọc lại mỗi dịp tháng Năm — sinh nhật Người — và tháng Chín — ngày Người ra đi. Những lời căn dặn về giữ gìn sự đoàn kết, thống nhất trong Đảng “như giữ gìn con ngươi của mắt mình”, về thực hành dân chủ rộng rãi, thường xuyên và nghiêm chỉnh tự phê bình và phê bình, về bồi dưỡng thế hệ cách mạng cho đời sau, về không ngừng nâng cao đời sống của nhân dân, đã trở thành những chuẩn mực cụ thể được nhắc lại trong sinh hoạt của các tổ chức đảng, đoàn thể suốt nhiều thập niên. Cuộc vận động học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh đang diễn ra hôm nay, suy cho cùng, chính là cách mỗi thế hệ tiếp tục thực hiện những điều Người đã ân cần căn dặn trong những trang viết cuối cùng ấy."},{"t":"Bạn có biết? Bản Di chúc của Chủ tịch Hồ Chí Minh là một trong số ít văn bản viết tay được Nhà nước Việt Nam công nhận là Bảo vật quốc gia, cùng với các tác phẩm “Đường Kách mệnh”, “Nhật ký trong tù”, “Lời kêu gọi toàn quốc kháng chiến” và “Lời kêu gọi đồng bào và chiến sĩ cả nước” của Người."},{"t":"Dấu tích hôm nay. Bản viết tay gốc của Di chúc — cùng các bản Người viết, sửa qua từng năm — hiện được bảo quản theo chế độ đặc biệt tại Kho Lưu trữ Trung ương Đảng, chỉ tồn tại dưới dạng độc bản. Bản sao cùng nhiều hình ảnh, tư liệu liên quan đến quá trình Người viết Di chúc được giới thiệu tại Bảo tàng Hồ Chí Minh, liền kề Lăng và Quảng trường Ba Đình, để bất cứ ai cũng có thể tìm hiểu về những trang viết cuối cùng của Người. Đứng trước những tư liệu ấy hôm nay, người xem không chỉ thấy một văn kiện lịch sử, mà còn thấy nét chữ của một người đã dành những dòng cuối cùng trong đời để nghĩ về Đảng, về dân, về đất nước — và chỉ vài dòng ngắn ngủi cho riêng mình. Đó cũng là điểm khép lại trọn vẹn cho câu chuyện đã mở ra từ gian Phủ Chủ tịch: từ trang viết đầu tiên trên nhà sàn đến hành trình bản Di chúc đi vào đời sống của cả một dân tộc."}],"so_chu":1914},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ năm 1969 đến nay: những mốc gìn giữ và lan tỏa di sản Hồ Chí Minh","sapo":"Hơn nửa thế kỷ sau ngày Chủ tịch Hồ Chí Minh đi xa, di sản của Người được gìn giữ bằng những công trình, những văn kiện và những cuộc vận động. Có mốc ai cũng biết, như ngày khánh thành Lăng hay ngày mở cửa Bảo tàng; cũng có mốc ít được nhắc đến, như ngày một đơn vị quân đội bí mật được kiện toàn thành một bộ tư lệnh. Dưới đây là những mốc chính, xếp theo trình tự thời gian.","bia":{"src":"textures/bai/G17_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai mạch song song","text":"Các mốc thời gian dưới đây đi theo hai mạch song song, gắn bó chặt chẽ với nhau. Mạch thứ nhất là việc gìn giữ di sản vật chất: thi hài của Người, công trình Lăng, Bảo tàng Hồ Chí Minh và mạng lưới các khu di tích trên khắp đất nước. Mạch thứ hai là việc gìn giữ di sản tinh thần: từ việc công bố Di chúc, xác định tư tưởng Hồ Chí Minh là nền tảng tư tưởng của Đảng, đến những cuộc vận động học tập và làm theo Người được triển khai liên tục qua nhiều nhiệm kỳ, ở mọi cơ quan, đơn vị, địa phương trong cả nước. Nhìn theo trục thời gian, có thể thấy hai mạch ấy không tách rời: mỗi công trình vật chất được dựng lên đều đi kèm một thông điệp tinh thần, và mỗi văn kiện, chỉ thị đều gắn với một dấu mốc cụ thể trong đời sống của đất nước.","doc":1},{"loai":"moc","items":[["15/5/1961","Chủ tịch Hồ Chí Minh gửi thư nêu Năm điều Bác Hồ dạy, nhân kỷ niệm 20 năm Ngày thành lập Đội Thiếu niên Tiền phong Việt Nam"],["2/9/1969, 9 giờ 47 phút","Chủ tịch Hồ Chí Minh từ trần tại Nhà 67, Hà Nội (ngày mất khi ấy được công bố là 3/9)"],["6–8/9/1969","Đồng bào, chiến sĩ, bạn bè quốc tế vào viếng Người tại Hội trường Ba Đình"],["9/9/1969","Lễ truy điệu tại Quảng trường Ba Đình; Di chúc của Người được công bố"],["1969 – 1975","Đoàn 69 cùng chuyên gia Liên Xô bí mật giữ gìn thi hài Người, chủ yếu tại căn cứ K9 (Đá Chông, Ba Vì)"],["27/1/1973","Ký Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam"],["2/9/1973","Khởi công xây dựng Lăng Chủ tịch Hồ Chí Minh tại Quảng trường Ba Đình"],["30/4/1975","Miền Nam hoàn toàn giải phóng, đất nước thống nhất"],["18/7/1975","Thi hài Người được đưa từ K9 về đặt tại Lăng vừa hoàn thành"],["29/8/1975","Khánh thành Lăng Chủ tịch Hồ Chí Minh"],["14/5/1976","Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh (tiền thân là Đoàn 69) chính thức được thành lập"],["2/7/1976","Quốc hội khóa VI quyết định đổi tên Thành phố Sài Gòn – Gia Định thành Thành phố Hồ Chí Minh"],["31/8/1985","Khởi công xây dựng Bảo tàng Hồ Chí Minh"],["1987","Khóa họp lần thứ 24 Đại hội đồng UNESCO ra nghị quyết tôn vinh Hồ Chí Minh là Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất của Việt Nam"],["8/1989","Bộ Chính trị công bố toàn văn Di chúc và đính chính ngày mất của Người là 2/9/1969"],["19/5/1990","Khánh thành Bảo tàng Hồ Chí Minh, đúng kỷ niệm 100 năm ngày sinh của Người"],["6/1991","Đại hội VII của Đảng xác định tư tưởng Hồ Chí Minh cùng chủ nghĩa Mác – Lênin là nền tảng tư tưởng, kim chỉ nam cho hành động"],["27/3/2003","Chỉ thị 23-CT/TW về đẩy mạnh nghiên cứu, tuyên truyền, giáo dục tư tưởng Hồ Chí Minh trong giai đoạn mới"],["7/11/2006","Chỉ thị 06-CT/TW về tổ chức Cuộc vận động “Học tập và làm theo tấm gương đạo đức Hồ Chí Minh”"],["12/8/2009","Khu lưu niệm Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch được xếp hạng Di tích quốc gia đặc biệt, đợt đầu tiên của cả nước"],["14/5/2011","Chỉ thị 03-CT/TW về tiếp tục đẩy mạnh việc học tập và làm theo tấm gương đạo đức Hồ Chí Minh"],["2012","Khu lưu niệm Chủ tịch Hồ Chí Minh tại Kim Liên, Nam Đàn, Nghệ An được xếp hạng Di tích quốc gia đặc biệt, đợt thứ hai"],["15/5/2016","Chỉ thị 05-CT/TW về đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh"],["18/5/2021","Kết luận 01-KL/TW về tiếp tục thực hiện Chỉ thị 05-CT/TW"]],"doc":2},{"loai":"ban_co_biet","text":"Ngày Chủ tịch Hồ Chí Minh từ trần, 2/9/1969, cũng là ngày kỷ niệm 24 năm Quốc khánh nước Việt Nam Dân chủ Cộng hòa — chính vì vậy mà ngày mất của Người khi ấy được công bố lùi sang ngày 3/9.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, tập 10, NXB Chính trị quốc gia","doc":3},{"loai":"anh","src":"textures/bang_w/G17_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ xa."},{"loai":"doan","tieu_de":"Những ngày được chọn","text":"Nhìn lại các mốc, có thể thấy nhiều công việc gìn giữ di sản được gắn với những ngày mang ý nghĩa biểu tượng: Lăng khởi công đúng ngày 2 tháng 9 năm 1973, tròn bốn năm ngày Người đi xa, và khánh thành ngày 29 tháng 8 năm 1975, kịp dịp kỷ niệm 30 năm Quốc khánh; Bảo tàng Hồ Chí Minh khánh thành đúng ngày 19 tháng 5 năm 1990, tròn 100 năm ngày sinh của Người. Các văn kiện về học tập và làm theo Bác trong những năm gần đây cũng thường được ban hành vào tháng Năm — tháng sinh của Người: Chỉ thị 03-CT/TW ngày 14 tháng 5 năm 2011, Chỉ thị 05-CT/TW ngày 15 tháng 5 năm 2016, và Kết luận 01-KL/TW ngày 18 tháng 5 năm 2021 — như thể mỗi lần nhắc lại lời dặn của Người, người ta lại chọn đúng dịp gần với ngày sinh của Người nhất.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_quang_truong_ba_dinh_ve_dem.jpg","chu_thich":"Quảng trường Ba Đình lên đèn về đêm — nơi giao nhau của mọi mốc son trong hành trình gìn giữ di sản Hồ Chí Minh.","credit":"Ảnh: Nguyễn Thanh Quang · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Từ một đơn vị bí mật đến một bộ tư lệnh","text":"Trong mạch gìn giữ di sản vật chất, có một dấu mốc ít được biết đến rộng rãi: ngày 14 tháng 5 năm 1976, đơn vị từng mang phiên hiệu Đoàn 69 — lực lượng trực tiếp bảo vệ, giữ gìn thi hài Chủ tịch Hồ Chí Minh suốt những năm chiến tranh — được kiện toàn thành Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh, tổ chức vẫn đảm nhận nhiệm vụ ấy cho đến hôm nay. Mốc này diễn ra chưa đầy một năm sau ngày đất nước thống nhất, khi nhiệm vụ gìn giữ thi hài Người — vốn được thực hiện trong bí mật thời chiến — chuyển sang một giai đoạn ổn định, lâu dài hơn trong thời bình. Câu chuyện đầy đủ về sáu năm gìn giữ thi hài Người giữa chiến tranh, từ căn cứ K9 giữa rừng Ba Vì đến ngày đưa Người về Lăng, được kể riêng ở chuyên đề bên cạnh.","doc":5},{"loai":"doan","tieu_de":"Thế hệ nối thế hệ","text":"Song song với các nghị quyết, chỉ thị dành cho cán bộ, đảng viên, có một mạch nhỏ dành riêng cho thế hệ nhỏ tuổi: từ Năm điều Bác Hồ dạy năm 1961, phong trào thi đua “Cháu ngoan Bác Hồ” ra đời trong các trường học, đội thiếu niên trên cả nước, trở thành danh hiệu quen thuộc được trao mỗi năm học cho những học sinh chăm ngoan, học giỏi. Đó là cách di sản tinh thần của Người được gieo trồng ngay từ những năm tháng đầu đời của mỗi công dân, trước khi họ trở thành đoàn viên, đảng viên và tiếp tục hành trình học và làm theo Bác ở tuổi trưởng thành. Nhiều thế hệ học sinh Việt Nam, dù sinh ra rất lâu sau năm 1969, vẫn thuộc lòng Năm điều Bác Hồ dạy trước khi biết đầy đủ về cuộc đời Người — một cách di sản đến với hậu thế không qua sách vở nặng nề, mà qua những lời dặn ngắn gọn, dễ nhớ.","doc":6},{"loai":"anh","src":"textures/bang_w/G17_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một tấm bản đồ di sản trải khắp đất nước","text":"Song song với các mốc ở Ba Đình, di sản của Chủ tịch Hồ Chí Minh còn được ghi danh chính thức tại nhiều địa phương. Ngày 12 tháng 8 năm 2009, Khu lưu niệm Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch được xếp hạng Di tích quốc gia đặc biệt trong đợt đầu tiên của cả nước; ba năm sau, năm 2012, đến lượt Khu lưu niệm tại Kim Liên, Nam Đàn, Nghệ An — quê hương của Người. Các khu di tích Pác Bó, Tân Trào, An toàn khu Định Hóa cũng lần lượt được ghi danh trong những năm sau đó, cùng nhau tạo thành một mạng lưới di tích mà người Việt Nam có thể theo chân Người đi suốt một cuộc đời, từ làng Sen đến hang Pác Bó, từ chiến khu Việt Bắc đến Bến Nhà Rồng bên sông Sài Gòn.","doc":7},{"loai":"ban_co_biet","text":"Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh, thành lập ngày 14/5/1976, có tiền thân là Đoàn 69 — đơn vị được giao nhiệm vụ giữ gìn thi hài Chủ tịch Hồ Chí Minh ngay từ tháng 9 năm 1969.","nguon_ten":"Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","doc":8},{"loai":"anh","src":"textures/bang_w/G17_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Nhịp điệu của một hành trình","text":"Nhìn vào toàn bộ các mốc trên, có thể nhận ra một nhịp điệu rõ rệt. Sáu năm đầu, từ 1969 đến 1975, là giai đoạn dồn dập nhất với hàng loạt sự kiện nối tiếp nhau ngay trong hoàn cảnh chiến tranh: từ ngày Người mất, việc bí mật gìn giữ thi hài, đến ngày khởi công và khánh thành Lăng. Từ giữa thập niên 1980 trở đi, khi đất nước bước vào thời kỳ hòa bình, xây dựng, trọng tâm của các mốc dần chuyển từ những công trình cụ thể sang những nghị quyết, chỉ thị về tư tưởng, đạo đức — phản ánh một sự chuyển dịch tự nhiên: khi phần “vật chất” của di sản đã dần hoàn thiện, phần “tinh thần” mới thực sự bắt đầu một hành trình dài, một hành trình đến nay vẫn chưa có điểm dừng.","doc":9},{"loai":"doan","tieu_de":"Từ nghị quyết đến việc làm mỗi ngày","text":"Đọc theo trục thời gian, các chỉ thị, kết luận về học tập và làm theo Bác — từ Chỉ thị 23 năm 2003, Chỉ thị 06 năm 2006, Chỉ thị 03 năm 2011, Chỉ thị 05 năm 2016 đến Kết luận 01 năm 2021 — cho thấy một điều: việc học Bác không phải một phong trào phát động rồi kết thúc, mà là một quá trình được nối tiếp, điều chỉnh liên tục qua nhiều nhiệm kỳ, mỗi lần một tên gọi mới nhưng vẫn chung một tinh thần cốt lõi. Nhìn suốt hơn năm mươi năm, từ buổi sáng mùa thu năm 1969 đến những mốc gần nhất, di sản Hồ Chí Minh hiện diện đồng thời ở hai chiều: những công trình bằng đá, bằng gỗ có thể đến tận nơi chiêm ngưỡng, và những lời dặn dò được nhắc lại mỗi ngày trong công việc, lối sống của hàng triệu con người — điều mà không một tấm bia đá nào có thể ghi hết.","doc":10}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, tập 10, NXB Chính trị quốc gia","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","Bảo tàng Hồ Chí Minh","Nghị quyết 24C/18.65, khóa họp lần thứ 24 Đại hội đồng UNESCO, 1987","Các Chỉ thị 23-CT/TW (2003), 06-CT/TW (2006), 03-CT/TW (2011), 05-CT/TW (2016) và Kết luận 01-KL/TW (2021) của Bộ Chính trị"],"doc":[{"t":"Từ năm 1969 đến nay: những mốc gìn giữ và lan tỏa di sản Hồ Chí Minh. Hơn nửa thế kỷ sau ngày Chủ tịch Hồ Chí Minh đi xa, di sản của Người được gìn giữ bằng những công trình, những văn kiện và những cuộc vận động. Có mốc ai cũng biết, như ngày khánh thành Lăng hay ngày mở cửa Bảo tàng; cũng có mốc ít được nhắc đến, như ngày một đơn vị quân đội bí mật được kiện toàn thành một bộ tư lệnh. Dưới đây là những mốc chính, xếp theo trình tự thời gian."},{"t":"Hai mạch song song. Các mốc thời gian dưới đây đi theo hai mạch song song, gắn bó chặt chẽ với nhau. Mạch thứ nhất là việc gìn giữ di sản vật chất: thi hài của Người, công trình Lăng, Bảo tàng Hồ Chí Minh và mạng lưới các khu di tích trên khắp đất nước. Mạch thứ hai là việc gìn giữ di sản tinh thần: từ việc công bố Di chúc, xác định tư tưởng Hồ Chí Minh là nền tảng tư tưởng của Đảng, đến những cuộc vận động học tập và làm theo Người được triển khai liên tục qua nhiều nhiệm kỳ, ở mọi cơ quan, đơn vị, địa phương trong cả nước. Nhìn theo trục thời gian, có thể thấy hai mạch ấy không tách rời: mỗi công trình vật chất được dựng lên đều đi kèm một thông điệp tinh thần, và mỗi văn kiện, chỉ thị đều gắn với một dấu mốc cụ thể trong đời sống của đất nước."},{"t":"Các mốc thời gian. 15/5/1961: Chủ tịch Hồ Chí Minh gửi thư nêu Năm điều Bác Hồ dạy, nhân kỷ niệm 20 năm Ngày thành lập Đội Thiếu niên Tiền phong Việt Nam. 2/9/1969, 9 giờ 47 phút: Chủ tịch Hồ Chí Minh từ trần tại Nhà 67, Hà Nội (ngày mất khi ấy được công bố là 3/9). 6–8/9/1969: Đồng bào, chiến sĩ, bạn bè quốc tế vào viếng Người tại Hội trường Ba Đình. 9/9/1969: Lễ truy điệu tại Quảng trường Ba Đình; Di chúc của Người được công bố. 1969 – 1975: Đoàn 69 cùng chuyên gia Liên Xô bí mật giữ gìn thi hài Người, chủ yếu tại căn cứ K9 (Đá Chông, Ba Vì). 27/1/1973: Ký Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam. 2/9/1973: Khởi công xây dựng Lăng Chủ tịch Hồ Chí Minh tại Quảng trường Ba Đình. 30/4/1975: Miền Nam hoàn toàn giải phóng, đất nước thống nhất. 18/7/1975: Thi hài Người được đưa từ K9 về đặt tại Lăng vừa hoàn thành. 29/8/1975: Khánh thành Lăng Chủ tịch Hồ Chí Minh. 14/5/1976: Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh (tiền thân là Đoàn 69) chính thức được thành lập. 2/7/1976: Quốc hội khóa VI quyết định đổi tên Thành phố Sài Gòn – Gia Định thành Thành phố Hồ Chí Minh. 31/8/1985: Khởi công xây dựng Bảo tàng Hồ Chí Minh. 1987: Khóa họp lần thứ 24 Đại hội đồng UNESCO ra nghị quyết tôn vinh Hồ Chí Minh là Anh hùng giải phóng dân tộc, Nhà văn hóa kiệt xuất của Việt Nam. 8/1989: Bộ Chính trị công bố toàn văn Di chúc và đính chính ngày mất của Người là 2/9/1969. 19/5/1990: Khánh thành Bảo tàng Hồ Chí Minh, đúng kỷ niệm 100 năm ngày sinh của Người. 6/1991: Đại hội VII của Đảng xác định tư tưởng Hồ Chí Minh cùng chủ nghĩa Mác – Lênin là nền tảng tư tưởng, kim chỉ nam cho hành động. 27/3/2003: Chỉ thị 23-CT/TW về đẩy mạnh nghiên cứu, tuyên truyền, giáo dục tư tưởng Hồ Chí Minh trong giai đoạn mới. 7/11/2006: Chỉ thị 06-CT/TW về tổ chức Cuộc vận động “Học tập và làm theo tấm gương đạo đức Hồ Chí Minh”. 12/8/2009: Khu lưu niệm Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch được xếp hạng Di tích quốc gia đặc biệt, đợt đầu tiên của cả nước. 14/5/2011: Chỉ thị 03-CT/TW về tiếp tục đẩy mạnh việc học tập và làm theo tấm gương đạo đức Hồ Chí Minh. 2012: Khu lưu niệm Chủ tịch Hồ Chí Minh tại Kim Liên, Nam Đàn, Nghệ An được xếp hạng Di tích quốc gia đặc biệt, đợt thứ hai. 15/5/2016: Chỉ thị 05-CT/TW về đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh. 18/5/2021: Kết luận 01-KL/TW về tiếp tục thực hiện Chỉ thị 05-CT/TW."},{"t":"Bạn có biết? Ngày Chủ tịch Hồ Chí Minh từ trần, 2/9/1969, cũng là ngày kỷ niệm 24 năm Quốc khánh nước Việt Nam Dân chủ Cộng hòa — chính vì vậy mà ngày mất của Người khi ấy được công bố lùi sang ngày 3/9."},{"t":"Những ngày được chọn. Nhìn lại các mốc, có thể thấy nhiều công việc gìn giữ di sản được gắn với những ngày mang ý nghĩa biểu tượng: Lăng khởi công đúng ngày 2 tháng 9 năm 1973, tròn bốn năm ngày Người đi xa, và khánh thành ngày 29 tháng 8 năm 1975, kịp dịp kỷ niệm 30 năm Quốc khánh; Bảo tàng Hồ Chí Minh khánh thành đúng ngày 19 tháng 5 năm 1990, tròn 100 năm ngày sinh của Người. Các văn kiện về học tập và làm theo Bác trong những năm gần đây cũng thường được ban hành vào tháng Năm — tháng sinh của Người: Chỉ thị 03-CT/TW ngày 14 tháng 5 năm 2011, Chỉ thị 05-CT/TW ngày 15 tháng 5 năm 2016, và Kết luận 01-KL/TW ngày 18 tháng 5 năm 2021 — như thể mỗi lần nhắc lại lời dặn của Người, người ta lại chọn đúng dịp gần với ngày sinh của Người nhất."},{"t":"Từ một đơn vị bí mật đến một bộ tư lệnh. Trong mạch gìn giữ di sản vật chất, có một dấu mốc ít được biết đến rộng rãi: ngày 14 tháng 5 năm 1976, đơn vị từng mang phiên hiệu Đoàn 69 — lực lượng trực tiếp bảo vệ, giữ gìn thi hài Chủ tịch Hồ Chí Minh suốt những năm chiến tranh — được kiện toàn thành Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh, tổ chức vẫn đảm nhận nhiệm vụ ấy cho đến hôm nay. Mốc này diễn ra chưa đầy một năm sau ngày đất nước thống nhất, khi nhiệm vụ gìn giữ thi hài Người — vốn được thực hiện trong bí mật thời chiến — chuyển sang một giai đoạn ổn định, lâu dài hơn trong thời bình. Câu chuyện đầy đủ về sáu năm gìn giữ thi hài Người giữa chiến tranh, từ căn cứ K9 giữa rừng Ba Vì đến ngày đưa Người về Lăng, được kể riêng ở chuyên đề bên cạnh."},{"t":"Thế hệ nối thế hệ. Song song với các nghị quyết, chỉ thị dành cho cán bộ, đảng viên, có một mạch nhỏ dành riêng cho thế hệ nhỏ tuổi: từ Năm điều Bác Hồ dạy năm 1961, phong trào thi đua “Cháu ngoan Bác Hồ” ra đời trong các trường học, đội thiếu niên trên cả nước, trở thành danh hiệu quen thuộc được trao mỗi năm học cho những học sinh chăm ngoan, học giỏi. Đó là cách di sản tinh thần của Người được gieo trồng ngay từ những năm tháng đầu đời của mỗi công dân, trước khi họ trở thành đoàn viên, đảng viên và tiếp tục hành trình học và làm theo Bác ở tuổi trưởng thành. Nhiều thế hệ học sinh Việt Nam, dù sinh ra rất lâu sau năm 1969, vẫn thuộc lòng Năm điều Bác Hồ dạy trước khi biết đầy đủ về cuộc đời Người — một cách di sản đến với hậu thế không qua sách vở nặng nề, mà qua những lời dặn ngắn gọn, dễ nhớ."},{"t":"Một tấm bản đồ di sản trải khắp đất nước. Song song với các mốc ở Ba Đình, di sản của Chủ tịch Hồ Chí Minh còn được ghi danh chính thức tại nhiều địa phương. Ngày 12 tháng 8 năm 2009, Khu lưu niệm Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch được xếp hạng Di tích quốc gia đặc biệt trong đợt đầu tiên của cả nước; ba năm sau, năm 2012, đến lượt Khu lưu niệm tại Kim Liên, Nam Đàn, Nghệ An — quê hương của Người. Các khu di tích Pác Bó, Tân Trào, An toàn khu Định Hóa cũng lần lượt được ghi danh trong những năm sau đó, cùng nhau tạo thành một mạng lưới di tích mà người Việt Nam có thể theo chân Người đi suốt một cuộc đời, từ làng Sen đến hang Pác Bó, từ chiến khu Việt Bắc đến Bến Nhà Rồng bên sông Sài Gòn."},{"t":"Bạn có biết? Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh, thành lập ngày 14/5/1976, có tiền thân là Đoàn 69 — đơn vị được giao nhiệm vụ giữ gìn thi hài Chủ tịch Hồ Chí Minh ngay từ tháng 9 năm 1969."},{"t":"Nhịp điệu của một hành trình. Nhìn vào toàn bộ các mốc trên, có thể nhận ra một nhịp điệu rõ rệt. Sáu năm đầu, từ 1969 đến 1975, là giai đoạn dồn dập nhất với hàng loạt sự kiện nối tiếp nhau ngay trong hoàn cảnh chiến tranh: từ ngày Người mất, việc bí mật gìn giữ thi hài, đến ngày khởi công và khánh thành Lăng. Từ giữa thập niên 1980 trở đi, khi đất nước bước vào thời kỳ hòa bình, xây dựng, trọng tâm của các mốc dần chuyển từ những công trình cụ thể sang những nghị quyết, chỉ thị về tư tưởng, đạo đức — phản ánh một sự chuyển dịch tự nhiên: khi phần “vật chất” của di sản đã dần hoàn thiện, phần “tinh thần” mới thực sự bắt đầu một hành trình dài, một hành trình đến nay vẫn chưa có điểm dừng."},{"t":"Từ nghị quyết đến việc làm mỗi ngày. Đọc theo trục thời gian, các chỉ thị, kết luận về học tập và làm theo Bác — từ Chỉ thị 23 năm 2003, Chỉ thị 06 năm 2006, Chỉ thị 03 năm 2011, Chỉ thị 05 năm 2016 đến Kết luận 01 năm 2021 — cho thấy một điều: việc học Bác không phải một phong trào phát động rồi kết thúc, mà là một quá trình được nối tiếp, điều chỉnh liên tục qua nhiều nhiệm kỳ, mỗi lần một tên gọi mới nhưng vẫn chung một tinh thần cốt lõi. Nhìn suốt hơn năm mươi năm, từ buổi sáng mùa thu năm 1969 đến những mốc gần nhất, di sản Hồ Chí Minh hiện diện đồng thời ở hai chiều: những công trình bằng đá, bằng gỗ có thể đến tận nơi chiêm ngưỡng, và những lời dặn dò được nhắc lại mỗi ngày trong công việc, lối sống của hàng triệu con người — điều mà không một tấm bia đá nào có thể ghi hết."}],"so_chu":1296},{"i":4,"tieu_de_bang":"Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh","tieu_de":"Từ vườn hoa mang tên một giám mục Pháp đến trái tim của một dân tộc","sapo":"Tấm ảnh chụp năm 2008 ghi lại một khoảng sân rộng, cỏ xanh mướt, và phía xa là khối kiến trúc uy nghiêm của Lăng Chủ tịch Hồ Chí Minh. Ít ai còn nhớ, hơn một thế kỷ trước, chính mảnh đất này từng mang tên một vị giám mục người Pháp. Vì sao một vườn hoa nhỏ giữa khu phố Tây lại trở thành nơi khai sinh một quốc gia, rồi sau đó là nơi Người tìm về yên nghỉ giữa lòng nhân dân? Câu chuyện bắt đầu từ một cuộc đổi tên, giữa những ngày tháng Tám sục sôi năm 1945.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_ba_dinh_square_and_ho_chi_minh_mau.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một vòng xoay mang tên giám mục Pháp","text":"Cuối thế kỷ XIX, khi thực dân Pháp quy hoạch khu vực phía tây thành cổ Hà Nội thành trung tâm hành chính của Liên bang Đông Dương, giữa khu ấy hình thành một vườn hoa hình tròn nhỏ, nơi các tuyến phố tỏa ra như nan quạt. Vườn hoa được đặt tên Rond Point Puginier — vườn hoa Puginier — theo tên giám mục Paul-François Puginier, một giáo sĩ người Pháp có ảnh hưởng lớn trong chính quyền thuộc địa ở Bắc Kỳ cuối thế kỷ XIX. Suốt gần nửa thế kỷ, đây chỉ là một vườn hoa yên tĩnh nằm giữa những dinh thự kiểu Pháp, ít ai hình dung nổi vai trò mà nó sẽ đảm nhận trong lịch sử dân tộc. Tên gọi ấy gắn với một thời kỳ mà những con phố quanh đây còn mang tên các viên toàn quyền, các thống sứ, các nhà truyền giáo phương Tây — dấu ấn của một Hà Nội thuộc địa mà rồi sẽ sớm đổi thay.","doc":1},{"loai":"ban_co_biet","text":"Ba làng Mậu Thịnh, Thượng Thọ và Mỹ Khê (huyện Nga Sơn, Thanh Hóa) — nơi nghĩa quân Cần Vương xây dựng căn cứ Ba Đình năm 1886, dưới sự lãnh đạo của Phạm Bành và Đinh Công Tráng — nhìn thấy nhau qua ba ngôi đình làng, nên căn cứ được gọi là “Ba Đình”. Gần sáu mươi năm sau, cái tên ấy được đặt cho một vườn hoa giữa Thủ đô Hà Nội.","nguon_ten":"Lịch sử Việt Nam, NXB Khoa học xã hội","doc":2},{"loai":"doan","tieu_de":"Cuộc đổi tên giữa những ngày tháng Tám","text":"Tháng 7 và 8 năm 1945, giữa lúc chính phủ Trần Trọng Kim quản lý Bắc Kỳ, bác sĩ Trần Văn Lai giữ chức Đốc lý (thị trưởng) Hà Nội đã cho tiến hành một việc chưa từng có: đổi hàng loạt tên phố, tên vườn hoa từ tên người Pháp sang tên các anh hùng, danh nhân, địa danh lịch sử của dân tộc Việt Nam. Đó là một hành động mang tính biểu tượng, diễn ra ngay trước thời khắc đất nước giành lại độc lập. Trong đợt đổi tên ấy, vườn hoa Puginier được đặt lại: Ba Đình — cái tên lấy từ cuộc khởi nghĩa chống Pháp do các thủ lĩnh Phạm Bành và Đinh Công Tráng lãnh đạo tại ba làng Mậu Thịnh, Thượng Thọ và Mỹ Khê, một trong những cuộc khởi nghĩa tiêu biểu của phong trào Cần Vương những năm 1886 – 1887. Việc thay một cái tên Pháp bằng tên một cuộc khởi nghĩa của người Việt, ngay giữa trung tâm quyền lực cũ của chính quyền thuộc địa, đã là một tín hiệu báo trước thời cuộc sắp đổi thay.","doc":3},{"loai":"anh","src":"textures/bang_w/G17_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Buổi chiều định mệnh, chưa đầy một tháng sau","text":"Chỉ ít lâu sau khi cái tên Ba Đình được đặt, chính vườn hoa ấy chứng kiến một sự kiện làm thay đổi vận mệnh dân tộc. Chiều ngày 2 tháng 9 năm 1945, hàng chục vạn người dân Hà Nội và các vùng lân cận đổ về, đứng chật kín từ vườn hoa ra các con phố xung quanh. Trên một lễ đài dựng tạm bằng gỗ, Chủ tịch Hồ Chí Minh, thay mặt Chính phủ lâm thời, đọc bản Tuyên ngôn Độc lập, tuyên bố với quốc dân và thế giới về sự ra đời của nước Việt Nam Dân chủ Cộng hòa. Từ buổi chiều hôm ấy, cái tên Ba Đình không còn đơn thuần là tên một vườn hoa mới được đổi theo phong trào — nó gắn liền vĩnh viễn với ngày độc lập của cả một dân tộc, trở thành một trong những địa danh có ý nghĩa thiêng liêng nhất của Việt Nam hiện đại.","doc":4},{"loai":"trich","text":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Tuyên ngôn Độc lập, đọc tại vườn hoa Ba Đình ngày 2/9/1945","doc":5},{"loai":"doan","tieu_de":"Từ vườn hoa thành quảng trường","text":"Sau ngày độc lập, khu vực quanh vườn hoa Ba Đình dần được mở rộng, cải tạo qua nhiều giai đoạn để trở thành quảng trường rộng lớn như ngày nay, nơi tiếp tục diễn ra những sự kiện trọng đại của đất nước trong suốt tám mươi năm sau đó (xem thêm chuyên đề Quảng trường Ba Đình). Nhưng bước ngoặt lớn nhất đến vào năm 1973, khi Đảng và Nhà nước quyết định xây dựng, ngay giữa quảng trường lịch sử ấy, một công trình đặc biệt: nơi Người — chính Người đã đọc Tuyên ngôn Độc lập hai mươi tám năm trước — sẽ về yên nghỉ.","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_hanoi_vietnam_ba_dinh_square_and_ho_chi_minh_mau.jpg","chu_thich":"Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh, nhìn từ phía quảng trường (ảnh chụp năm 2008).","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Vì sao chọn đúng nơi này để xây Lăng","text":"Khi bàn việc xây dựng Lăng, lựa chọn địa điểm Quảng trường Ba Đình mang một ý nghĩa được cân nhắc kỹ lưỡng: Người sẽ yên nghỉ tại chính nơi Người từng đứng tuyên bố với quốc dân và thế giới về quyền độc lập, tự do của dân tộc Việt Nam. Công trình được khởi công đúng ngày 2 tháng 9 năm 1973 — tròn bốn năm sau ngày Chủ tịch Hồ Chí Minh qua đời — và hoàn thành sau gần hai năm xây dựng, kịp khánh thành vào ngày 29 tháng 8 năm 1975, trước dịp kỷ niệm ba mươi năm Quốc khánh. Từ đó, mỗi ngày, dòng người vào viếng Lăng đều đi qua chính không gian đã chứng kiến ngày khai sinh đất nước, nối liền khoảnh khắc lịch sử năm 1945 với lòng biết ơn của nhiều thế hệ sau này.","doc":7},{"loai":"anh","src":"textures/bang_w/G17_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một địa danh, nhiều tầng ký ức","text":"Ít có địa danh nào ở Việt Nam mang trong mình nhiều tầng ký ức lịch sử như Ba Đình. Đó từng là một vườn hoa thời Pháp thuộc, mang tên một giáo sĩ phương Tây; rồi trở thành nơi tưởng nhớ một cuộc khởi nghĩa chống Pháp của nông dân xứ Thanh cuối thế kỷ XIX; rồi lại là nơi một dân tộc tuyên bố với thế giới về quyền được sống độc lập, tự do; và cuối cùng là nơi vị lãnh tụ của dân tộc ấy chọn làm chốn yên nghỉ. Mỗi lớp ý nghĩa được đắp thêm qua từng giai đoạn, mà không lớp nào xóa đi lớp trước — tất cả cùng tồn tại trong một cái tên, một khoảng không gian giữa lòng Thủ đô.\n\nCũng bởi vậy, khi các đoàn khách quốc tế hay các đoàn học sinh, sinh viên được hướng dẫn viên giới thiệu về nơi này, câu chuyện thường không dừng lại ở việc tả cảnh Lăng và quảng trường, mà đi ngược về tận cuộc khởi nghĩa nông dân năm 1886, rồi mới quay lại buổi chiều mùa thu năm 1945. Chính chiều sâu lịch sử ấy khiến một chuyến viếng thăm Ba Đình trở thành nhiều hơn một điểm dừng chân — nó là một lát cắt cô đọng của cả một chặng đường dân tộc đã đi qua để có được ngày độc lập, tự do.","doc":8},{"loai":"ban_co_biet","text":"Bác sĩ Trần Văn Lai, Đốc lý Hà Nội năm 1945, là người khởi xướng đợt đổi tên hàng loạt phố phường, vườn hoa của Hà Nội từ tên Pháp sang tên các anh hùng, danh nhân Việt Nam — trong đó vườn hoa Puginier được đổi thành vườn hoa Ba Đình.","nguon_ten":"Tư liệu lịch sử Hà Nội; báo điện tử Kiến Thức","doc":9},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh nằm trong quần thể Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, được xếp hạng Di tích quốc gia đặc biệt, gồm Lăng, Nhà sàn, ao cá, Bảo tàng Hồ Chí Minh, chùa Một Cột và nhiều công trình khác. Mỗi ngày, hàng nghìn người trong nước và quốc tế đến viếng Lăng, thăm quần thể di tích, đi qua đúng khoảng sân từng là vườn hoa Puginier một thế kỷ trước. Ở quê hương của cuộc khởi nghĩa xưa — huyện Nga Sơn, Thanh Hóa — một khu di tích lịch sử mang tên Chiến khu Ba Đình cũng được gìn giữ, cách Quảng trường Ba Đình ở Hà Nội hơn trăm cây số về phía nam, như một cách nối liền hai địa danh cùng tên.","doc":10},{"loai":"anh","src":"textures/bang_w/G17_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Một cái tên, một lời nhắc","text":"Mỗi khi vang lên hai tiếng Ba Đình, người Việt Nam thường nghĩ ngay đến ngày độc lập, đến hình ảnh Lăng Chủ tịch Hồ Chí Minh giữa quảng trường rợp cờ hoa. Nhưng đằng sau cái tên quen thuộc ấy còn là câu chuyện về một cuộc đổi tên giữa thời khắc chuyển giao lịch sử, về những người nông dân áo vải đã ngã xuống ở Thanh Hóa hơn một thế kỷ trước, và về quyết định đặt một vườn hoa nhỏ vào đúng dòng chảy của lịch sử dân tộc. Không nhiều địa danh trên thế giới mang trong mình một hành trình ý nghĩa dài và liên tục như vậy.","doc":11}],"nguon":["Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Lịch sử Việt Nam, NXB Khoa học xã hội","Tuyên ngôn Độc lập, 2/9/1945","Báo điện tử Kiến Thức – tư liệu lịch sử Hà Nội"],"doc":[{"t":"Từ vườn hoa mang tên một giám mục Pháp đến trái tim của một dân tộc. Tấm ảnh chụp năm 2008 ghi lại một khoảng sân rộng, cỏ xanh mướt, và phía xa là khối kiến trúc uy nghiêm của Lăng Chủ tịch Hồ Chí Minh. Ít ai còn nhớ, hơn một thế kỷ trước, chính mảnh đất này từng mang tên một vị giám mục người Pháp. Vì sao một vườn hoa nhỏ giữa khu phố Tây lại trở thành nơi khai sinh một quốc gia, rồi sau đó là nơi Người tìm về yên nghỉ giữa lòng nhân dân? Câu chuyện bắt đầu từ một cuộc đổi tên, giữa những ngày tháng Tám sục sôi năm 1945."},{"t":"Một vòng xoay mang tên giám mục Pháp. Cuối thế kỷ XIX, khi thực dân Pháp quy hoạch khu vực phía tây thành cổ Hà Nội thành trung tâm hành chính của Liên bang Đông Dương, giữa khu ấy hình thành một vườn hoa hình tròn nhỏ, nơi các tuyến phố tỏa ra như nan quạt. Vườn hoa được đặt tên Rond Point Puginier — vườn hoa Puginier — theo tên giám mục Paul-François Puginier, một giáo sĩ người Pháp có ảnh hưởng lớn trong chính quyền thuộc địa ở Bắc Kỳ cuối thế kỷ XIX. Suốt gần nửa thế kỷ, đây chỉ là một vườn hoa yên tĩnh nằm giữa những dinh thự kiểu Pháp, ít ai hình dung nổi vai trò mà nó sẽ đảm nhận trong lịch sử dân tộc. Tên gọi ấy gắn với một thời kỳ mà những con phố quanh đây còn mang tên các viên toàn quyền, các thống sứ, các nhà truyền giáo phương Tây — dấu ấn của một Hà Nội thuộc địa mà rồi sẽ sớm đổi thay."},{"t":"Bạn có biết? Ba làng Mậu Thịnh, Thượng Thọ và Mỹ Khê (huyện Nga Sơn, Thanh Hóa) — nơi nghĩa quân Cần Vương xây dựng căn cứ Ba Đình năm 1886, dưới sự lãnh đạo của Phạm Bành và Đinh Công Tráng — nhìn thấy nhau qua ba ngôi đình làng, nên căn cứ được gọi là “Ba Đình”. Gần sáu mươi năm sau, cái tên ấy được đặt cho một vườn hoa giữa Thủ đô Hà Nội."},{"t":"Cuộc đổi tên giữa những ngày tháng Tám. Tháng 7 và 8 năm 1945, giữa lúc chính phủ Trần Trọng Kim quản lý Bắc Kỳ, bác sĩ Trần Văn Lai giữ chức Đốc lý (thị trưởng) Hà Nội đã cho tiến hành một việc chưa từng có: đổi hàng loạt tên phố, tên vườn hoa từ tên người Pháp sang tên các anh hùng, danh nhân, địa danh lịch sử của dân tộc Việt Nam. Đó là một hành động mang tính biểu tượng, diễn ra ngay trước thời khắc đất nước giành lại độc lập. Trong đợt đổi tên ấy, vườn hoa Puginier được đặt lại: Ba Đình — cái tên lấy từ cuộc khởi nghĩa chống Pháp do các thủ lĩnh Phạm Bành và Đinh Công Tráng lãnh đạo tại ba làng Mậu Thịnh, Thượng Thọ và Mỹ Khê, một trong những cuộc khởi nghĩa tiêu biểu của phong trào Cần Vương những năm 1886 – 1887. Việc thay một cái tên Pháp bằng tên một cuộc khởi nghĩa của người Việt, ngay giữa trung tâm quyền lực cũ của chính quyền thuộc địa, đã là một tín hiệu báo trước thời cuộc sắp đổi thay."},{"t":"Buổi chiều định mệnh, chưa đầy một tháng sau. Chỉ ít lâu sau khi cái tên Ba Đình được đặt, chính vườn hoa ấy chứng kiến một sự kiện làm thay đổi vận mệnh dân tộc. Chiều ngày 2 tháng 9 năm 1945, hàng chục vạn người dân Hà Nội và các vùng lân cận đổ về, đứng chật kín từ vườn hoa ra các con phố xung quanh. Trên một lễ đài dựng tạm bằng gỗ, Chủ tịch Hồ Chí Minh, thay mặt Chính phủ lâm thời, đọc bản Tuyên ngôn Độc lập, tuyên bố với quốc dân và thế giới về sự ra đời của nước Việt Nam Dân chủ Cộng hòa. Từ buổi chiều hôm ấy, cái tên Ba Đình không còn đơn thuần là tên một vườn hoa mới được đổi theo phong trào — nó gắn liền vĩnh viễn với ngày độc lập của cả một dân tộc, trở thành một trong những địa danh có ý nghĩa thiêng liêng nhất của Việt Nam hiện đại."},{"t":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc. — Chủ tịch Hồ Chí Minh"},{"t":"Từ vườn hoa thành quảng trường. Sau ngày độc lập, khu vực quanh vườn hoa Ba Đình dần được mở rộng, cải tạo qua nhiều giai đoạn để trở thành quảng trường rộng lớn như ngày nay, nơi tiếp tục diễn ra những sự kiện trọng đại của đất nước trong suốt tám mươi năm sau đó (xem thêm chuyên đề Quảng trường Ba Đình). Nhưng bước ngoặt lớn nhất đến vào năm 1973, khi Đảng và Nhà nước quyết định xây dựng, ngay giữa quảng trường lịch sử ấy, một công trình đặc biệt: nơi Người — chính Người đã đọc Tuyên ngôn Độc lập hai mươi tám năm trước — sẽ về yên nghỉ."},{"t":"Vì sao chọn đúng nơi này để xây Lăng. Khi bàn việc xây dựng Lăng, lựa chọn địa điểm Quảng trường Ba Đình mang một ý nghĩa được cân nhắc kỹ lưỡng: Người sẽ yên nghỉ tại chính nơi Người từng đứng tuyên bố với quốc dân và thế giới về quyền độc lập, tự do của dân tộc Việt Nam. Công trình được khởi công đúng ngày 2 tháng 9 năm 1973 — tròn bốn năm sau ngày Chủ tịch Hồ Chí Minh qua đời — và hoàn thành sau gần hai năm xây dựng, kịp khánh thành vào ngày 29 tháng 8 năm 1975, trước dịp kỷ niệm ba mươi năm Quốc khánh. Từ đó, mỗi ngày, dòng người vào viếng Lăng đều đi qua chính không gian đã chứng kiến ngày khai sinh đất nước, nối liền khoảnh khắc lịch sử năm 1945 với lòng biết ơn của nhiều thế hệ sau này."},{"t":"Một địa danh, nhiều tầng ký ức. Ít có địa danh nào ở Việt Nam mang trong mình nhiều tầng ký ức lịch sử như Ba Đình. Đó từng là một vườn hoa thời Pháp thuộc, mang tên một giáo sĩ phương Tây; rồi trở thành nơi tưởng nhớ một cuộc khởi nghĩa chống Pháp của nông dân xứ Thanh cuối thế kỷ XIX; rồi lại là nơi một dân tộc tuyên bố với thế giới về quyền được sống độc lập, tự do; và cuối cùng là nơi vị lãnh tụ của dân tộc ấy chọn làm chốn yên nghỉ. Mỗi lớp ý nghĩa được đắp thêm qua từng giai đoạn, mà không lớp nào xóa đi lớp trước — tất cả cùng tồn tại trong một cái tên, một khoảng không gian giữa lòng Thủ đô. Cũng bởi vậy, khi các đoàn khách quốc tế hay các đoàn học sinh, sinh viên được hướng dẫn viên giới thiệu về nơi này, câu chuyện thường không dừng lại ở việc tả cảnh Lăng và quảng trường, mà đi ngược về tận cuộc khởi nghĩa nông dân năm 1886, rồi mới quay lại buổi chiều mùa thu năm 1945. Chính chiều sâu lịch sử ấy khiến một chuyến viếng thăm Ba Đình trở thành nhiều hơn một điểm dừng chân — nó là một lát cắt cô đọng của cả một chặng đường dân tộc đã đi qua để có được ngày độc lập, tự do."},{"t":"Bạn có biết? Bác sĩ Trần Văn Lai, Đốc lý Hà Nội năm 1945, là người khởi xướng đợt đổi tên hàng loạt phố phường, vườn hoa của Hà Nội từ tên Pháp sang tên các anh hùng, danh nhân Việt Nam — trong đó vườn hoa Puginier được đổi thành vườn hoa Ba Đình."},{"t":"Dấu tích hôm nay. Ngày nay, Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh nằm trong quần thể Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch, được xếp hạng Di tích quốc gia đặc biệt, gồm Lăng, Nhà sàn, ao cá, Bảo tàng Hồ Chí Minh, chùa Một Cột và nhiều công trình khác. Mỗi ngày, hàng nghìn người trong nước và quốc tế đến viếng Lăng, thăm quần thể di tích, đi qua đúng khoảng sân từng là vườn hoa Puginier một thế kỷ trước. Ở quê hương của cuộc khởi nghĩa xưa — huyện Nga Sơn, Thanh Hóa — một khu di tích lịch sử mang tên Chiến khu Ba Đình cũng được gìn giữ, cách Quảng trường Ba Đình ở Hà Nội hơn trăm cây số về phía nam, như một cách nối liền hai địa danh cùng tên."},{"t":"Một cái tên, một lời nhắc. Mỗi khi vang lên hai tiếng Ba Đình, người Việt Nam thường nghĩ ngay đến ngày độc lập, đến hình ảnh Lăng Chủ tịch Hồ Chí Minh giữa quảng trường rợp cờ hoa. Nhưng đằng sau cái tên quen thuộc ấy còn là câu chuyện về một cuộc đổi tên giữa thời khắc chuyển giao lịch sử, về những người nông dân áo vải đã ngã xuống ở Thanh Hóa hơn một thế kỷ trước, và về quyết định đặt một vườn hoa nhỏ vào đúng dòng chảy của lịch sử dân tộc. Không nhiều địa danh trên thế giới mang trong mình một hành trình ý nghĩa dài và liên tục như vậy."}],"so_chu":1548},{"i":5,"tieu_de_bang":"Tiêu binh trước Lăng","tieu_de":"Đoàn 275: những người lính đứng gác bên giấc ngủ của Người","sapo":"Họ đứng bất động hàng giờ trước cửa Lăng, dưới nắng hè gay gắt hay trong gió mùa đông buốt giá. Tấm ảnh chụp năm 2018 ghi lại hình ảnh quen thuộc với hàng triệu người từng đến viếng Chủ tịch Hồ Chí Minh: những người lính tiêu binh của Đoàn 275. Ít ai biết, đằng sau vẻ nghiêm trang bất động ấy là hàng chục nghìn giờ luyện tập và trực gác, được ghi lại bằng những con số cụ thể mỗi năm.","bia":{"src":"textures/ht/ht_anh_guards_of_the_ho_chi_minh_mausoleum.jpg","credit":"Ảnh: Christophe95 · CC BY-SA 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Đoàn 275 — những người lính của một nhiệm vụ đặc biệt","text":"Những người lính đứng gác trước cửa Lăng thuộc Đoàn 275, đơn vị nằm trong Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh của Quân đội nhân dân Việt Nam. Nhiệm vụ của đơn vị không chỉ là đứng gác danh dự: đó còn là bảo vệ, gìn giữ lâu dài, tuyệt đối an toàn thi hài Chủ tịch Hồ Chí Minh, tổ chức đón tiếp và phục vụ đồng bào, khách quốc tế đến viếng Người. Việc gìn giữ ấy có gốc rễ từ những năm chiến tranh, khi thi hài Người được di chuyển, bảo quản bí mật suốt sáu năm giữa bom đạn, trước khi Lăng được xây dựng và khánh thành (xem chuyên đề Sáu năm gìn giữ thi hài Bác giữa chiến tranh). Từ ngày Lăng mở cửa đón khách năm 1975, hình ảnh những người lính tiêu binh đứng gác đã trở thành một phần không thể tách rời của Quảng trường Ba Đình.","doc":1},{"loai":"doan","tieu_de":"Một phiên gác, được tính bằng con số","text":"Ít ai hình dung công việc thầm lặng của tiêu binh lớn đến mức nào, cho đến khi nhìn vào những con số công việc mà đơn vị công bố mỗi năm: hàng chục nghìn giờ canh gác tại cửa Lăng, hàng nghìn giờ trực tiếp gác giữ thi hài Người, hàng nghìn lần thực hiện nghi lễ thượng cờ, hạ cờ, cùng hàng triệu lượt khách được đón tiếp. Đằng sau mỗi con số ấy là hàng nghìn phiên gác nối tiếp nhau không nghỉ, bất kể ngày lễ, ngày thường, mưa hay nắng — một guồng quay vận hành đều đặn suốt nửa thế kỷ qua, kể từ ngày Lăng khánh thành năm 1975.","doc":2},{"loai":"anh","src":"textures/bang_w/G17_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tiêu binh trước Lăng”, nhìn từ xa."},{"loai":"doan","tieu_de":"Đứng gác như một nghi lễ","text":"Tiêu binh gác Lăng được tuyển chọn kỹ lưỡng và huấn luyện công phu về điều lệnh, tác phong, thể lực trước khi được đứng gác chính thức. Trong suốt phiên gác, người lính đứng nghiêm, gần như bất động, ánh mắt nhìn thẳng, dù đứng dưới nắng gắt mùa hè hay gió lạnh mùa đông Hà Nội. Khi đổi gác, đội hình bước đi theo nhịp đều, dứt khoát, theo đúng nghi thức đã được quy định chặt chẽ. Lễ phục của tiêu binh cũng thay đổi theo mùa, từ phục trang mùa hè đến áo choàng dày mùa đông. Mỗi chi tiết nhỏ, từ tư thế cầm súng đến bước chân đổi gác, đều nhằm thể hiện sự trang nghiêm và lòng thành kính của quân đội, của nhân dân đối với Người.","doc":3},{"loai":"ban_co_biet","text":"Riêng giai đoạn 2019–2024, Đoàn 275 đã thực hiện 43.800 giờ gác tại cửa Lăng, 7.700 giờ gác giữ thi hài Người, tổ chức 3.450 lần lễ thượng cờ và hạ cờ, đón hơn 6 triệu lượt khách viếng, trong đó có gần 800.000 khách quốc tế.","nguon_ten":"Báo Tiền Phong, dẫn số liệu Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","doc":4},{"loai":"doan","tieu_de":"Rèn luyện để đứng vững hàng giờ","text":"Để có thể đứng bất động hàng giờ liền mà không lộ rõ mệt mỏi, không lung lay tư thế, mỗi chiến sĩ tiêu binh phải trải qua quá trình huấn luyện khắc nghiệt: tập đứng nghiêm trong thời gian dài, tập đi đều từng bước theo đúng khoảng cách, tập giữ ánh mắt, tập kiểm soát hơi thở. Ngoài thể lực, người lính còn cần một sự tĩnh tại về tinh thần, bởi mỗi ngày, hàng nghìn ánh mắt của người đến viếng đều hướng về phía họ. Nhiều cựu chiến sĩ từng chia sẻ trên báo chí rằng thử thách lớn nhất không phải là cái nắng hay cái rét, mà là việc phải giữ được sự tĩnh lặng tuyệt đối trong tâm trí suốt phiên gác — một dạng kỷ luật mà không phải người lính nào cũng dễ dàng đạt được ngay từ những ngày đầu.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_guards_of_the_ho_chi_minh_mausoleum.jpg","chu_thich":"Tiêu binh đứng gác trước cửa Lăng Chủ tịch Hồ Chí Minh (ảnh chụp năm 2018).","credit":"Ảnh: Christophe95 · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Niềm tự hào của người lính cận vệ","text":"Với nhiều chiến sĩ, được chọn đứng gác bên Lăng Chủ tịch Hồ Chí Minh là vinh dự lớn nhất trong đời quân ngũ. Họ thường được người dân gọi bằng cái tên trìu mến: những người lính cận vệ của Bác. Không ít người, sau khi hoàn thành nghĩa vụ, vẫn giữ thói quen trở lại thăm Lăng, đứng lặng nhìn nơi mình từng đứng gác năm nào. Với họ, đó không đơn thuần là một nhiệm vụ quân sự, mà là một phần ký ức gắn liền với lòng biết ơn dành cho vị lãnh tụ của dân tộc — thứ tình cảm mà nhiều người lính từng thừa nhận chỉ thật sự thấu hiểu trọn vẹn sau khi đã một lần đứng gác giữa Quảng trường Ba Đình.","doc":6},{"loai":"anh","src":"textures/bang_w/G17_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tiêu binh trước Lăng”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Khách viếng cũng giữ nghi thức","text":"Sự trang nghiêm ấy cũng được chính những người đến viếng Lăng góp phần gìn giữ. Khách vào Lăng mặc trang phục lịch sự, xếp hàng trật tự thành hai hàng dọc, không mang theo máy quay, máy ảnh, giữ im lặng và bước đều khi đi qua phòng đặt thi hài. Lăng thường mở cửa đón khách vào các buổi sáng trong tuần, nghỉ vào thứ Hai và thứ Sáu, và mỗi năm tạm ngừng đón khách một khoảng thời gian nhất định để tu bổ định kỳ, bảo đảm điều kiện gìn giữ thi hài Người ở trạng thái tốt nhất. Người đến viếng lần đầu thường được nhắc theo dõi thông báo của Ban Quản lý Lăng trước khi đến, đặc biệt vào những đợt tu bổ định kỳ hằng năm.","doc":7},{"loai":"ban_co_biet","text":"Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh còn quản lý Khu di tích K9 – Đá Chông (Ba Vì, Hà Nội) — nơi thi hài Chủ tịch Hồ Chí Minh từng được bí mật gìn giữ trong nhiều năm chiến tranh, trước khi Lăng được xây dựng.","nguon_ten":"Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","doc":8},{"loai":"doan","tieu_de":"Không chỉ có Đoàn 275","text":"Bên cạnh Đoàn 275 phụ trách nghi lễ gác và đón tiếp khách, Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh còn có các đơn vị khác đảm nhiệm công tác y tế, kỹ thuật đặc biệt, ngày đêm theo dõi, bảo đảm các điều kiện nghiêm ngặt để gìn giữ thi hài Người trong trạng thái tốt nhất suốt nhiều thập kỷ qua. Công việc thầm lặng ấy diễn ra phía sau cánh cửa Lăng, ít khi được nhắc tới, nhưng lại là nền tảng để mỗi buổi lễ thượng cờ, hạ cờ, mỗi phiên gác trước Lăng có thể diễn ra đúng nghi thức, không một sai sót nhỏ nào được phép xảy ra. Các đơn vị phối hợp với nhau theo một quy trình chặt chẽ, được duy trì gần như không thay đổi qua nhiều thế hệ cán bộ, chiến sĩ kế tiếp nhau nhận nhiệm vụ.","doc":9},{"loai":"doan","tieu_de":"Gương mặt lặng lẽ trong ống kính của thế giới","text":"Tấm ảnh tiêu binh đứng gác được sử dụng trong bảng này, chụp năm 2018, là một trong rất nhiều bức ảnh về Lăng Chủ tịch Hồ Chí Minh được chia sẻ công khai trên nền tảng lưu trữ ảnh tư liệu mở Wikimedia Commons, dưới giấy phép cho phép sử dụng rộng rãi. Qua những bức ảnh như vậy, hình ảnh người lính tiêu binh Việt Nam — đứng nghiêm, bất động, mắt nhìn thẳng phía trước — đã đến được với nhiều người ở nước ngoài chưa từng có dịp đặt chân tới Hà Nội. Với không ít du khách quốc tế, đây là hình ảnh đầu tiên họ nhớ đến khi nhắc tới nghi thức tưởng niệm một vị lãnh tụ tại Việt Nam, trước cả khi họ tìm hiểu về cuộc đời và sự nghiệp của Người.","doc":10},{"loai":"anh","src":"textures/bang_w/G17_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tiêu binh trước Lăng”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, hình ảnh tiêu binh đứng gác trước Lăng đã trở thành một biểu tượng quen thuộc, xuất hiện trong vô số bức ảnh của du khách trong và ngoài nước. Mỗi sáng, trước giờ Lăng mở cửa, dòng người đã xếp hàng dài để chờ được vào viếng và chứng kiến những người lính đổi gác. Với nhiều gia đình, đưa con em đến xem lễ đổi gác trước Lăng đã trở thành một phần trong hành trình giáo dục truyền thống, một cách để thế hệ trẻ hiểu thêm về sự trang nghiêm mà đất nước dành cho vị lãnh tụ của mình, và về những người lính vẫn ngày đêm lặng lẽ đứng đó.\n\nNhiều cựu chiến sĩ từng khoác quân phục tiêu binh, sau khi rời quân ngũ, vẫn được mời trở lại nói chuyện truyền thống với thế hệ đàn em hoặc với học sinh, sinh viên các trường trên địa bàn Hà Nội. Với họ, câu chuyện về những năm tháng đứng gác bên Lăng không chỉ là ký ức cá nhân, mà còn là một cách để tiếp tục lan tỏa tinh thần kỷ luật, sự tận tụy và lòng biết ơn đối với Chủ tịch Hồ Chí Minh tới những người trẻ chưa từng có cơ hội được gặp Người.","doc":11}],"nguon":["Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Báo Tiền Phong – Đoàn 275 trung thành vô hạn, hoàn thành xuất sắc nhiệm vụ đặc biệt","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia"],"doc":[{"t":"Đoàn 275: những người lính đứng gác bên giấc ngủ của Người. Họ đứng bất động hàng giờ trước cửa Lăng, dưới nắng hè gay gắt hay trong gió mùa đông buốt giá. Tấm ảnh chụp năm 2018 ghi lại hình ảnh quen thuộc với hàng triệu người từng đến viếng Chủ tịch Hồ Chí Minh: những người lính tiêu binh của Đoàn 275. Ít ai biết, đằng sau vẻ nghiêm trang bất động ấy là hàng chục nghìn giờ luyện tập và trực gác, được ghi lại bằng những con số cụ thể mỗi năm."},{"t":"Đoàn 275 — những người lính của một nhiệm vụ đặc biệt. Những người lính đứng gác trước cửa Lăng thuộc Đoàn 275, đơn vị nằm trong Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh của Quân đội nhân dân Việt Nam. Nhiệm vụ của đơn vị không chỉ là đứng gác danh dự: đó còn là bảo vệ, gìn giữ lâu dài, tuyệt đối an toàn thi hài Chủ tịch Hồ Chí Minh, tổ chức đón tiếp và phục vụ đồng bào, khách quốc tế đến viếng Người. Việc gìn giữ ấy có gốc rễ từ những năm chiến tranh, khi thi hài Người được di chuyển, bảo quản bí mật suốt sáu năm giữa bom đạn, trước khi Lăng được xây dựng và khánh thành (xem chuyên đề Sáu năm gìn giữ thi hài Bác giữa chiến tranh). Từ ngày Lăng mở cửa đón khách năm 1975, hình ảnh những người lính tiêu binh đứng gác đã trở thành một phần không thể tách rời của Quảng trường Ba Đình."},{"t":"Một phiên gác, được tính bằng con số. Ít ai hình dung công việc thầm lặng của tiêu binh lớn đến mức nào, cho đến khi nhìn vào những con số công việc mà đơn vị công bố mỗi năm: hàng chục nghìn giờ canh gác tại cửa Lăng, hàng nghìn giờ trực tiếp gác giữ thi hài Người, hàng nghìn lần thực hiện nghi lễ thượng cờ, hạ cờ, cùng hàng triệu lượt khách được đón tiếp. Đằng sau mỗi con số ấy là hàng nghìn phiên gác nối tiếp nhau không nghỉ, bất kể ngày lễ, ngày thường, mưa hay nắng — một guồng quay vận hành đều đặn suốt nửa thế kỷ qua, kể từ ngày Lăng khánh thành năm 1975."},{"t":"Đứng gác như một nghi lễ. Tiêu binh gác Lăng được tuyển chọn kỹ lưỡng và huấn luyện công phu về điều lệnh, tác phong, thể lực trước khi được đứng gác chính thức. Trong suốt phiên gác, người lính đứng nghiêm, gần như bất động, ánh mắt nhìn thẳng, dù đứng dưới nắng gắt mùa hè hay gió lạnh mùa đông Hà Nội. Khi đổi gác, đội hình bước đi theo nhịp đều, dứt khoát, theo đúng nghi thức đã được quy định chặt chẽ. Lễ phục của tiêu binh cũng thay đổi theo mùa, từ phục trang mùa hè đến áo choàng dày mùa đông. Mỗi chi tiết nhỏ, từ tư thế cầm súng đến bước chân đổi gác, đều nhằm thể hiện sự trang nghiêm và lòng thành kính của quân đội, của nhân dân đối với Người."},{"t":"Bạn có biết? Riêng giai đoạn 2019–2024, Đoàn 275 đã thực hiện 43.800 giờ gác tại cửa Lăng, 7.700 giờ gác giữ thi hài Người, tổ chức 3.450 lần lễ thượng cờ và hạ cờ, đón hơn 6 triệu lượt khách viếng, trong đó có gần 800.000 khách quốc tế."},{"t":"Rèn luyện để đứng vững hàng giờ. Để có thể đứng bất động hàng giờ liền mà không lộ rõ mệt mỏi, không lung lay tư thế, mỗi chiến sĩ tiêu binh phải trải qua quá trình huấn luyện khắc nghiệt: tập đứng nghiêm trong thời gian dài, tập đi đều từng bước theo đúng khoảng cách, tập giữ ánh mắt, tập kiểm soát hơi thở. Ngoài thể lực, người lính còn cần một sự tĩnh tại về tinh thần, bởi mỗi ngày, hàng nghìn ánh mắt của người đến viếng đều hướng về phía họ. Nhiều cựu chiến sĩ từng chia sẻ trên báo chí rằng thử thách lớn nhất không phải là cái nắng hay cái rét, mà là việc phải giữ được sự tĩnh lặng tuyệt đối trong tâm trí suốt phiên gác — một dạng kỷ luật mà không phải người lính nào cũng dễ dàng đạt được ngay từ những ngày đầu."},{"t":"Niềm tự hào của người lính cận vệ. Với nhiều chiến sĩ, được chọn đứng gác bên Lăng Chủ tịch Hồ Chí Minh là vinh dự lớn nhất trong đời quân ngũ. Họ thường được người dân gọi bằng cái tên trìu mến: những người lính cận vệ của Bác. Không ít người, sau khi hoàn thành nghĩa vụ, vẫn giữ thói quen trở lại thăm Lăng, đứng lặng nhìn nơi mình từng đứng gác năm nào. Với họ, đó không đơn thuần là một nhiệm vụ quân sự, mà là một phần ký ức gắn liền với lòng biết ơn dành cho vị lãnh tụ của dân tộc — thứ tình cảm mà nhiều người lính từng thừa nhận chỉ thật sự thấu hiểu trọn vẹn sau khi đã một lần đứng gác giữa Quảng trường Ba Đình."},{"t":"Khách viếng cũng giữ nghi thức. Sự trang nghiêm ấy cũng được chính những người đến viếng Lăng góp phần gìn giữ. Khách vào Lăng mặc trang phục lịch sự, xếp hàng trật tự thành hai hàng dọc, không mang theo máy quay, máy ảnh, giữ im lặng và bước đều khi đi qua phòng đặt thi hài. Lăng thường mở cửa đón khách vào các buổi sáng trong tuần, nghỉ vào thứ Hai và thứ Sáu, và mỗi năm tạm ngừng đón khách một khoảng thời gian nhất định để tu bổ định kỳ, bảo đảm điều kiện gìn giữ thi hài Người ở trạng thái tốt nhất. Người đến viếng lần đầu thường được nhắc theo dõi thông báo của Ban Quản lý Lăng trước khi đến, đặc biệt vào những đợt tu bổ định kỳ hằng năm."},{"t":"Bạn có biết? Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh còn quản lý Khu di tích K9 – Đá Chông (Ba Vì, Hà Nội) — nơi thi hài Chủ tịch Hồ Chí Minh từng được bí mật gìn giữ trong nhiều năm chiến tranh, trước khi Lăng được xây dựng."},{"t":"Không chỉ có Đoàn 275. Bên cạnh Đoàn 275 phụ trách nghi lễ gác và đón tiếp khách, Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh còn có các đơn vị khác đảm nhiệm công tác y tế, kỹ thuật đặc biệt, ngày đêm theo dõi, bảo đảm các điều kiện nghiêm ngặt để gìn giữ thi hài Người trong trạng thái tốt nhất suốt nhiều thập kỷ qua. Công việc thầm lặng ấy diễn ra phía sau cánh cửa Lăng, ít khi được nhắc tới, nhưng lại là nền tảng để mỗi buổi lễ thượng cờ, hạ cờ, mỗi phiên gác trước Lăng có thể diễn ra đúng nghi thức, không một sai sót nhỏ nào được phép xảy ra. Các đơn vị phối hợp với nhau theo một quy trình chặt chẽ, được duy trì gần như không thay đổi qua nhiều thế hệ cán bộ, chiến sĩ kế tiếp nhau nhận nhiệm vụ."},{"t":"Gương mặt lặng lẽ trong ống kính của thế giới. Tấm ảnh tiêu binh đứng gác được sử dụng trong bảng này, chụp năm 2018, là một trong rất nhiều bức ảnh về Lăng Chủ tịch Hồ Chí Minh được chia sẻ công khai trên nền tảng lưu trữ ảnh tư liệu mở Wikimedia Commons, dưới giấy phép cho phép sử dụng rộng rãi. Qua những bức ảnh như vậy, hình ảnh người lính tiêu binh Việt Nam — đứng nghiêm, bất động, mắt nhìn thẳng phía trước — đã đến được với nhiều người ở nước ngoài chưa từng có dịp đặt chân tới Hà Nội. Với không ít du khách quốc tế, đây là hình ảnh đầu tiên họ nhớ đến khi nhắc tới nghi thức tưởng niệm một vị lãnh tụ tại Việt Nam, trước cả khi họ tìm hiểu về cuộc đời và sự nghiệp của Người."},{"t":"Dấu tích hôm nay. Ngày nay, hình ảnh tiêu binh đứng gác trước Lăng đã trở thành một biểu tượng quen thuộc, xuất hiện trong vô số bức ảnh của du khách trong và ngoài nước. Mỗi sáng, trước giờ Lăng mở cửa, dòng người đã xếp hàng dài để chờ được vào viếng và chứng kiến những người lính đổi gác. Với nhiều gia đình, đưa con em đến xem lễ đổi gác trước Lăng đã trở thành một phần trong hành trình giáo dục truyền thống, một cách để thế hệ trẻ hiểu thêm về sự trang nghiêm mà đất nước dành cho vị lãnh tụ của mình, và về những người lính vẫn ngày đêm lặng lẽ đứng đó. Nhiều cựu chiến sĩ từng khoác quân phục tiêu binh, sau khi rời quân ngũ, vẫn được mời trở lại nói chuyện truyền thống với thế hệ đàn em hoặc với học sinh, sinh viên các trường trên địa bàn Hà Nội. Với họ, câu chuyện về những năm tháng đứng gác bên Lăng không chỉ là ký ức cá nhân, mà còn là một cách để tiếp tục lan tỏa tinh thần kỷ luật, sự tận tụy và lòng biết ơn đối với Chủ tịch Hồ Chí Minh tới những người trẻ chưa từng có cơ hội được gặp Người."}],"so_chu":1525},{"i":6,"tieu_de_bang":"Quảng trường Ba Đình về đêm","tieu_de":"Khi Ba Đình lên đèn: nghi lễ cờ và những công trình quanh quảng trường","sapo":"Ban ngày, Ba Đình là nơi dòng người nối dài chờ vào viếng Lăng. Khi đêm buông, quảng trường lên đèn, khoác một vẻ tĩnh lặng khác hẳn. Tấm ảnh chụp năm 2010 ghi lại khoảnh khắc ấy — và phía sau ánh đèn là một nghi lễ đã diễn ra đều đặn mỗi ngày, suốt nửa thế kỷ.","bia":{"src":"textures/ht/ht_anh_quang_truong_ba_dinh_ve_dem.jpg","credit":"Ảnh: Nguyễn Thanh Quang · CC BY-SA 3.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một ngày mở đầu và khép lại bằng một nghi lễ","text":"Giữa Quảng trường Ba Đình sừng sững một cột cờ, nơi mỗi ngày diễn ra hai nghi lễ đều đặn: lễ thượng cờ vào lúc mặt trời mọc và lễ hạ cờ vào lúc mặt trời lặn — thời điểm cụ thể thay đổi theo mùa trong năm. Nghi lễ do các chiến sĩ tiêu binh của Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh thực hiện, với đội hình chỉnh tề, bước chân đều, dứt khoát, theo đúng nghi thức được quy định chặt chẽ (xem thêm chuyên đề Tiêu binh trước Lăng). Nhiều người dân, du khách cố tình dậy thật sớm hoặc nán lại đến tối để được tận mắt chứng kiến khoảnh khắc lá Quốc kỳ được kéo lên hay hạ xuống, giữa đúng quảng trường nơi lá cờ đỏ sao vàng từng tung bay trong ngày độc lập năm 1945.","doc":1},{"loai":"ban_co_biet","text":"Lễ thượng cờ tại Quảng trường Ba Đình diễn ra đúng vào thời điểm mặt trời mọc, lễ hạ cờ vào thời điểm mặt trời lặn; do đó giờ làm lễ thay đổi theo mùa trong năm, sớm hơn vào mùa hè và muộn hơn vào mùa đông.","nguon_ten":"Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","doc":2},{"loai":"doan","tieu_de":"Khi ánh đèn thay cho ánh nắng","text":"Khi lễ hạ cờ khép lại một ngày, Quảng trường Ba Đình không chìm vào bóng tối mà bừng lên trong ánh đèn. Hệ thống chiếu sáng được bố trí quanh quảng trường, hắt lên những thảm cỏ xanh, hàng cây và mặt tiền các công trình xung quanh, tạo nên một không gian khác hẳn với vẻ trang nghiêm, đông đúc ban ngày. Dòng người xếp hàng vào viếng Lăng đã vãn từ lâu; thay vào đó là những nhóm nhỏ người dân, du khách chậm rãi dạo bước, chụp ảnh, hoặc chỉ đơn giản ngồi lặng ngắm khung cảnh về đêm — một nhịp sống khác hẳn của cùng một địa danh.","doc":3},{"loai":"anh","src":"textures/bang_w/G17_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình về đêm”, nhìn từ xa."},{"loai":"doan","tieu_de":"Những công trình quanh quảng trường","text":"Quanh Quảng trường Ba Đình là một quần thể công trình gắn liền với những giai đoạn khác nhau của lịch sử đất nước. Phủ Chủ tịch là tòa nhà màu vàng đồ sộ, xây dựng từ đầu thế kỷ XX theo phong cách kiến trúc Pháp, khi đó là dinh Toàn quyền Đông Dương; phía sau là ngôi nhà sàn giản dị nơi Chủ tịch Hồ Chí Minh sống và làm việc những năm cuối đời. Nhà Quốc hội, khánh thành năm 2014, được xây dựng trên chính nền của Hội trường Ba Đình cũ — nơi từng diễn ra lễ viếng Chủ tịch Hồ Chí Minh vào tháng 9 năm 1969. Không xa đó là chùa Một Cột, ngôi chùa nhỏ mang dáng một đài sen vươn lên từ mặt nước, và Bảo tàng Hồ Chí Minh với khối kiến trúc hiện đại (xem chuyên đề Bảo tàng Hồ Chí Minh, Hà Nội). Về đêm, ánh đèn làm nổi bật từng khối kiến trúc ấy trên nền trời Hà Nội, tạo nên một không gian vừa trang nghiêm vừa gần gũi.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_quang_truong_ba_dinh_ve_dem.jpg","chu_thich":"Quảng trường Ba Đình lên đèn về đêm (ảnh chụp năm 2010).","credit":"Ảnh: Nguyễn Thanh Quang · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một ngôi chùa nghìn năm tuổi bên cạnh","text":"Trong số những công trình quanh Quảng trường Ba Đình, chùa Một Cột là công trình có tuổi đời lâu nhất — được xây dựng từ năm 1049 dưới triều vua Lý Thái Tông, mang dáng một đài sen vươn lên giữa hồ nước, tượng trưng cho đóa sen mà nhà vua từng thấy trong một giấc mơ. Ngôi chùa từng bị quân Pháp phá hủy trước khi rút khỏi Hà Nội năm 1954, và được phục dựng lại theo đúng dáng cũ vào năm 1955. Trải qua gần một nghìn năm và nhiều lần trùng tu, ngôi chùa nhỏ bé ấy vẫn đứng đó, bên cạnh những công trình mới xây dựng trong thế kỷ XX, XXI. Sự hiện diện của một di tích nghìn năm tuổi ngay cạnh Lăng Chủ tịch Hồ Chí Minh và Nhà Quốc hội hiện đại cho thấy phần nào chiều sâu lịch sử của khu vực Ba Đình — nơi các thời đại nối tiếp nhau để lại dấu ấn trên cùng một mảnh đất.","doc":5},{"loai":"ban_co_biet","text":"Nhà Quốc hội hiện nay được xây dựng trên nền Hội trường Ba Đình cũ. Hội trường Ba Đình, khánh thành năm 1963, là nơi diễn ra lễ viếng Chủ tịch Hồ Chí Minh vào tháng 9 năm 1969.","nguon_ten":"Văn phòng Quốc hội; Hồ Chí Minh – Biên niên tiểu sử, tập 10, NXB Chính trị quốc gia","doc":6},{"loai":"anh","src":"textures/bang_w/G17_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình về đêm”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Thảm cỏ giữ nghi thức cả khi không có nghi lễ","text":"Không chỉ có cột cờ và các công trình kiến trúc, Quảng trường Ba Đình còn được biết đến với những ô cỏ vuông vắn, xanh mướt quanh năm, xen giữa các lối đi lát đá. Việc chăm sóc thảm cỏ ấy được thực hiện thường xuyên, tỉ mỉ, giữ cho quảng trường luôn trong trạng thái chỉn chu, sẵn sàng cho bất cứ nghi lễ, sự kiện nào diễn ra vào bất kỳ thời điểm nào trong năm. Về đêm, dưới ánh đèn, những ô cỏ ấy trở thành những mảng màu êm dịu, làm dịu bớt vẻ uy nghiêm của khối kiến trúc đá xám, tạo cảm giác gần gũi hơn cho những người đến dạo bước.","doc":7},{"loai":"doan","tieu_de":"Nơi cất lên những lời thề buổi sớm","text":"Không chỉ về đêm, những giờ phút tinh mơ trước lễ thượng cờ cũng mang một không khí đặc biệt ở Quảng trường Ba Đình. Nhiều trường học, đoàn thể chọn đúng khoảnh khắc lá cờ được kéo lên buổi sáng để tổ chức các buổi lễ kết nạp Đoàn, kết nạp Đội cho học sinh, sinh viên — một cách để những lời thề đầu đời của tuổi trẻ được cất lên ngay tại nơi từng vang lên bản Tuyên ngôn Độc lập. Với nhiều người, ký ức về một buổi sáng đứng giữa quảng trường, dưới cờ đỏ sao vàng, nghe lời thề của chính mình hoặc của con em mình, trở thành một dấu mốc khó quên trong đời, nối tiếp mạch cảm xúc mà không gian này đã gìn giữ suốt tám mươi năm qua.","doc":8},{"loai":"doan","tieu_de":"Quảng trường của mọi người","text":"Ba Đình không phải là một không gian xa cách, chỉ dành cho các nghi lễ trang trọng. Buổi tối, người Hà Nội đưa con nhỏ ra đây đi dạo, hóng gió; học sinh từ các tỉnh xa về Thủ đô dừng chân chụp ảnh lưu niệm trước Lăng; những đoàn khách nước ngoài đứng lặng ngắm khung cảnh trong ánh đèn dịu. Vào những dịp lễ lớn của đất nước, quảng trường được trang hoàng cờ hoa rực rỡ, trở thành điểm hội tụ của hàng vạn người. Sự hòa quyện giữa nghi lễ trang nghiêm ban ngày và nhịp sống bình dị ban đêm ấy cũng là một nét đẹp riêng của không gian này.","doc":9},{"loai":"anh","src":"textures/bang_w/G17_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình về đêm”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Một biểu tượng được gìn giữ qua nhiều thế hệ","text":"Suốt nhiều thập kỷ, diện mạo Quảng trường Ba Đình được gìn giữ, tôn tạo qua nhiều đợt chỉnh trang, nhưng vẫn giữ nguyên bố cục cơ bản: cột cờ ở trung tâm, thảm cỏ xanh mở rộng ra bốn phía, và Lăng Chủ tịch Hồ Chí Minh sừng sững ở một đầu quảng trường. Sự ổn định ấy, giữa một Hà Nội không ngừng đổi thay, khiến Ba Đình trở thành một trong số ít không gian đô thị mà nhiều thế hệ người Việt Nam, dù cách nhau hàng chục năm, vẫn có thể nhận ra ngay khi nhìn thấy.","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, Quảng trường Ba Đình về đêm là điểm dừng chân quen thuộc trong hành trình khám phá Hà Nội của nhiều du khách, đặc biệt vào mùa hè khi thời tiết ban đêm dễ chịu hơn ban ngày. Khách tham quan có thể đứng từ nhiều góc quảng trường để chiêm ngưỡng Lăng, Nhà Quốc hội, Phủ Chủ tịch cùng lên đèn, hoặc dạo bước qua khu vực chùa Một Cột gần đó. Với người Hà Nội, đây cũng là nơi gắn với nhiều kỷ niệm cá nhân — từ những buổi tối đi dạo cùng gia đình đến những lần đứng lặng trước Lăng vào một dịp lễ nào đó trong đời.\n\nMỗi năm, vào những dịp lễ lớn như Quốc khánh hay Tết Nguyên đán, quảng trường và khu vực xung quanh còn được trang trí thêm ánh sáng, cờ hoa, thu hút đông đảo người dân và du khách đến chụp ảnh, dạo chơi vào buổi tối. Chính sự đan xen giữa một không gian lịch sử trang nghiêm bậc nhất đất nước với đời sống thường nhật của người dân Thủ đô đã khiến Ba Đình, dù đã tồn tại qua bao thăng trầm, vẫn luôn là một phần sống động, gần gũi trong nhịp sống thường nhật của Hà Nội hôm nay, chứ không chỉ là một biểu tượng để chiêm ngưỡng từ xa.","doc":11}],"nguon":["Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch","Văn phòng Quốc hội","Tư liệu lịch sử Hà Nội"],"doc":[{"t":"Khi Ba Đình lên đèn: nghi lễ cờ và những công trình quanh quảng trường. Ban ngày, Ba Đình là nơi dòng người nối dài chờ vào viếng Lăng. Khi đêm buông, quảng trường lên đèn, khoác một vẻ tĩnh lặng khác hẳn. Tấm ảnh chụp năm 2010 ghi lại khoảnh khắc ấy — và phía sau ánh đèn là một nghi lễ đã diễn ra đều đặn mỗi ngày, suốt nửa thế kỷ."},{"t":"Một ngày mở đầu và khép lại bằng một nghi lễ. Giữa Quảng trường Ba Đình sừng sững một cột cờ, nơi mỗi ngày diễn ra hai nghi lễ đều đặn: lễ thượng cờ vào lúc mặt trời mọc và lễ hạ cờ vào lúc mặt trời lặn — thời điểm cụ thể thay đổi theo mùa trong năm. Nghi lễ do các chiến sĩ tiêu binh của Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh thực hiện, với đội hình chỉnh tề, bước chân đều, dứt khoát, theo đúng nghi thức được quy định chặt chẽ (xem thêm chuyên đề Tiêu binh trước Lăng). Nhiều người dân, du khách cố tình dậy thật sớm hoặc nán lại đến tối để được tận mắt chứng kiến khoảnh khắc lá Quốc kỳ được kéo lên hay hạ xuống, giữa đúng quảng trường nơi lá cờ đỏ sao vàng từng tung bay trong ngày độc lập năm 1945."},{"t":"Bạn có biết? Lễ thượng cờ tại Quảng trường Ba Đình diễn ra đúng vào thời điểm mặt trời mọc, lễ hạ cờ vào thời điểm mặt trời lặn; do đó giờ làm lễ thay đổi theo mùa trong năm, sớm hơn vào mùa hè và muộn hơn vào mùa đông."},{"t":"Khi ánh đèn thay cho ánh nắng. Khi lễ hạ cờ khép lại một ngày, Quảng trường Ba Đình không chìm vào bóng tối mà bừng lên trong ánh đèn. Hệ thống chiếu sáng được bố trí quanh quảng trường, hắt lên những thảm cỏ xanh, hàng cây và mặt tiền các công trình xung quanh, tạo nên một không gian khác hẳn với vẻ trang nghiêm, đông đúc ban ngày. Dòng người xếp hàng vào viếng Lăng đã vãn từ lâu; thay vào đó là những nhóm nhỏ người dân, du khách chậm rãi dạo bước, chụp ảnh, hoặc chỉ đơn giản ngồi lặng ngắm khung cảnh về đêm — một nhịp sống khác hẳn của cùng một địa danh."},{"t":"Những công trình quanh quảng trường. Quanh Quảng trường Ba Đình là một quần thể công trình gắn liền với những giai đoạn khác nhau của lịch sử đất nước. Phủ Chủ tịch là tòa nhà màu vàng đồ sộ, xây dựng từ đầu thế kỷ XX theo phong cách kiến trúc Pháp, khi đó là dinh Toàn quyền Đông Dương; phía sau là ngôi nhà sàn giản dị nơi Chủ tịch Hồ Chí Minh sống và làm việc những năm cuối đời. Nhà Quốc hội, khánh thành năm 2014, được xây dựng trên chính nền của Hội trường Ba Đình cũ — nơi từng diễn ra lễ viếng Chủ tịch Hồ Chí Minh vào tháng 9 năm 1969. Không xa đó là chùa Một Cột, ngôi chùa nhỏ mang dáng một đài sen vươn lên từ mặt nước, và Bảo tàng Hồ Chí Minh với khối kiến trúc hiện đại (xem chuyên đề Bảo tàng Hồ Chí Minh, Hà Nội). Về đêm, ánh đèn làm nổi bật từng khối kiến trúc ấy trên nền trời Hà Nội, tạo nên một không gian vừa trang nghiêm vừa gần gũi."},{"t":"Một ngôi chùa nghìn năm tuổi bên cạnh. Trong số những công trình quanh Quảng trường Ba Đình, chùa Một Cột là công trình có tuổi đời lâu nhất — được xây dựng từ năm 1049 dưới triều vua Lý Thái Tông, mang dáng một đài sen vươn lên giữa hồ nước, tượng trưng cho đóa sen mà nhà vua từng thấy trong một giấc mơ. Ngôi chùa từng bị quân Pháp phá hủy trước khi rút khỏi Hà Nội năm 1954, và được phục dựng lại theo đúng dáng cũ vào năm 1955. Trải qua gần một nghìn năm và nhiều lần trùng tu, ngôi chùa nhỏ bé ấy vẫn đứng đó, bên cạnh những công trình mới xây dựng trong thế kỷ XX, XXI. Sự hiện diện của một di tích nghìn năm tuổi ngay cạnh Lăng Chủ tịch Hồ Chí Minh và Nhà Quốc hội hiện đại cho thấy phần nào chiều sâu lịch sử của khu vực Ba Đình — nơi các thời đại nối tiếp nhau để lại dấu ấn trên cùng một mảnh đất."},{"t":"Bạn có biết? Nhà Quốc hội hiện nay được xây dựng trên nền Hội trường Ba Đình cũ. Hội trường Ba Đình, khánh thành năm 1963, là nơi diễn ra lễ viếng Chủ tịch Hồ Chí Minh vào tháng 9 năm 1969."},{"t":"Thảm cỏ giữ nghi thức cả khi không có nghi lễ. Không chỉ có cột cờ và các công trình kiến trúc, Quảng trường Ba Đình còn được biết đến với những ô cỏ vuông vắn, xanh mướt quanh năm, xen giữa các lối đi lát đá. Việc chăm sóc thảm cỏ ấy được thực hiện thường xuyên, tỉ mỉ, giữ cho quảng trường luôn trong trạng thái chỉn chu, sẵn sàng cho bất cứ nghi lễ, sự kiện nào diễn ra vào bất kỳ thời điểm nào trong năm. Về đêm, dưới ánh đèn, những ô cỏ ấy trở thành những mảng màu êm dịu, làm dịu bớt vẻ uy nghiêm của khối kiến trúc đá xám, tạo cảm giác gần gũi hơn cho những người đến dạo bước."},{"t":"Nơi cất lên những lời thề buổi sớm. Không chỉ về đêm, những giờ phút tinh mơ trước lễ thượng cờ cũng mang một không khí đặc biệt ở Quảng trường Ba Đình. Nhiều trường học, đoàn thể chọn đúng khoảnh khắc lá cờ được kéo lên buổi sáng để tổ chức các buổi lễ kết nạp Đoàn, kết nạp Đội cho học sinh, sinh viên — một cách để những lời thề đầu đời của tuổi trẻ được cất lên ngay tại nơi từng vang lên bản Tuyên ngôn Độc lập. Với nhiều người, ký ức về một buổi sáng đứng giữa quảng trường, dưới cờ đỏ sao vàng, nghe lời thề của chính mình hoặc của con em mình, trở thành một dấu mốc khó quên trong đời, nối tiếp mạch cảm xúc mà không gian này đã gìn giữ suốt tám mươi năm qua."},{"t":"Quảng trường của mọi người. Ba Đình không phải là một không gian xa cách, chỉ dành cho các nghi lễ trang trọng. Buổi tối, người Hà Nội đưa con nhỏ ra đây đi dạo, hóng gió; học sinh từ các tỉnh xa về Thủ đô dừng chân chụp ảnh lưu niệm trước Lăng; những đoàn khách nước ngoài đứng lặng ngắm khung cảnh trong ánh đèn dịu. Vào những dịp lễ lớn của đất nước, quảng trường được trang hoàng cờ hoa rực rỡ, trở thành điểm hội tụ của hàng vạn người. Sự hòa quyện giữa nghi lễ trang nghiêm ban ngày và nhịp sống bình dị ban đêm ấy cũng là một nét đẹp riêng của không gian này."},{"t":"Một biểu tượng được gìn giữ qua nhiều thế hệ. Suốt nhiều thập kỷ, diện mạo Quảng trường Ba Đình được gìn giữ, tôn tạo qua nhiều đợt chỉnh trang, nhưng vẫn giữ nguyên bố cục cơ bản: cột cờ ở trung tâm, thảm cỏ xanh mở rộng ra bốn phía, và Lăng Chủ tịch Hồ Chí Minh sừng sững ở một đầu quảng trường. Sự ổn định ấy, giữa một Hà Nội không ngừng đổi thay, khiến Ba Đình trở thành một trong số ít không gian đô thị mà nhiều thế hệ người Việt Nam, dù cách nhau hàng chục năm, vẫn có thể nhận ra ngay khi nhìn thấy."},{"t":"Dấu tích hôm nay. Ngày nay, Quảng trường Ba Đình về đêm là điểm dừng chân quen thuộc trong hành trình khám phá Hà Nội của nhiều du khách, đặc biệt vào mùa hè khi thời tiết ban đêm dễ chịu hơn ban ngày. Khách tham quan có thể đứng từ nhiều góc quảng trường để chiêm ngưỡng Lăng, Nhà Quốc hội, Phủ Chủ tịch cùng lên đèn, hoặc dạo bước qua khu vực chùa Một Cột gần đó. Với người Hà Nội, đây cũng là nơi gắn với nhiều kỷ niệm cá nhân — từ những buổi tối đi dạo cùng gia đình đến những lần đứng lặng trước Lăng vào một dịp lễ nào đó trong đời. Mỗi năm, vào những dịp lễ lớn như Quốc khánh hay Tết Nguyên đán, quảng trường và khu vực xung quanh còn được trang trí thêm ánh sáng, cờ hoa, thu hút đông đảo người dân và du khách đến chụp ảnh, dạo chơi vào buổi tối. Chính sự đan xen giữa một không gian lịch sử trang nghiêm bậc nhất đất nước với đời sống thường nhật của người dân Thủ đô đã khiến Ba Đình, dù đã tồn tại qua bao thăng trầm, vẫn luôn là một phần sống động, gần gũi trong nhịp sống thường nhật của Hà Nội hôm nay, chứ không chỉ là một biểu tượng để chiêm ngưỡng từ xa."}],"so_chu":1471},{"i":7,"tieu_de_bang":"Bảo tàng Hồ Chí Minh, Hà Nội","tieu_de":"Bảo tàng Hồ Chí Minh: bông sen trắng dâng Người tròn trăm tuổi","sapo":"Ngày 19 tháng 5 năm 1990, đúng 100 năm ngày sinh Chủ tịch Hồ Chí Minh, một công trình mang dáng bông sen trắng khổng lồ mở cửa ngay cạnh Lăng của Người. Từ đó, Bảo tàng Hồ Chí Minh trở thành nơi lưu giữ, nghiên cứu và giới thiệu toàn diện nhất về cuộc đời, sự nghiệp của Người — không chỉ bằng hiện vật, mà bằng chính ngôn ngữ của kiến trúc.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_ho_chi_minh_museum_the_pyramid.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một công trình cho ngày trăm tuổi","text":"Bảo tàng Hồ Chí Minh được khởi công ngày 31 tháng 8 năm 1985 và khánh thành ngày 19 tháng 5 năm 1990, đúng vào dịp kỷ niệm 100 năm ngày sinh của Người — sự kiện mà Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO) đã ra nghị quyết khuyến nghị các nước thành viên cùng tham gia kỷ niệm từ năm 1987. Công trình được xây dựng với sự giúp đỡ của Liên Xô, do kiến trúc sư trưởng Garôn Ixacôvích cùng các cộng sự thiết kế, nằm trong quần thể di tích quanh Quảng trường Ba Đình, sát cạnh Lăng Chủ tịch Hồ Chí Minh, Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch và chùa Một Cột. Tấm ảnh tư liệu trong bảng được chụp tại Bảo tàng năm 2008.","doc":1},{"loai":"doan","tieu_de":"Kiến trúc hình bông sen","text":"Khối kiến trúc của Bảo tàng được cách điệu từ hình ảnh một bông sen trắng — loài hoa gắn với tên làng Sen quê hương Người và với phẩm chất thanh cao mà người Việt vẫn gửi gắm vào hình tượng hoa sen. Tòa nhà có bình đồ hình vuông vát bốn góc, cao gần 20 mét, mỗi cạnh dài khoảng 70 mét; bốn khối hình vuông xếp ở phần trên cùng vừa tạo hình bốn cánh sen, vừa là những lối nhìn hướng ra các di tích lịch sử xung quanh. Chọn bông sen làm hình tượng cho một bảo tàng về Chủ tịch Hồ Chí Minh là cách nói về cuộc đời Người bằng ngôn ngữ kiến trúc: giản dị, trong sáng, gắn bó với cội nguồn dân tộc. Từ ao sen làng Kim Liên đến bông sen giữa Thủ đô là cả một hành trình của một đời người.","doc":2},{"loai":"anh","src":"textures/bang_w/G17_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bảo tàng Hồ Chí Minh, Hà Nội”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một hồ nước và hòn đảo đá bao quanh","text":"Bao quanh tòa nhà chính là một hồ nước nhân tạo hình tròn, đường kính khoảng 18 mét, giữa hồ nổi lên một hòn đảo đá tự nhiên cao hơn 7 mét — chi tiết kiến trúc gợi liên tưởng đến những vùng non nước quê hương Việt Nam. Mặt nước phẳng lặng phản chiếu khối kiến trúc trắng của Bảo tàng, tạo nên một tổng thể vừa hiện đại vừa mang hơi thở thiên nhiên — khác hẳn với vẻ uy nghiêm bằng đá granite xám của Lăng ở ngay bên cạnh. Sự tương phản có chủ ý ấy giữa hai công trình gần nhau — một nơi để tưởng niệm, một nơi để tìm hiểu — cũng phần nào phản ánh hai cách người đời sau bày tỏ tình cảm với Người: bằng sự trang nghiêm lặng lẽ và bằng sự trân trọng, tìm tòi hiểu biết.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_hanoi_vietnam_ho_chi_minh_museum_the_pyramid.jpg","chu_thich":"Bảo tàng Hồ Chí Minh, Hà Nội, khánh thành ngày 19/5/1990 (ảnh chụp năm 2008).","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Bên trong sảnh chính","text":"Bước vào sảnh chính của Bảo tàng, hình ảnh đầu tiên đập vào mắt du khách là bức tượng đồng Chủ tịch Hồ Chí Minh, cao khoảng 3,5 mét, đặt trang trọng giữa không gian rộng lớn. Từ sảnh chính, các lối đi dẫn khách tham quan lần lượt qua từng khu trưng bày, được sắp xếp theo dòng thời gian cuộc đời Người — từ thời niên thiếu ở Nghệ An, những năm bôn ba tìm đường cứu nước, đến sự nghiệp lãnh đạo cách mạng và tình cảm của nhân dân, bạn bè quốc tế dành cho Người (xem chuyên đề Bên trong Bảo tàng Hồ Chí Minh). Không gian trưng bày rộng khoảng 13.000 mét vuông, trong tổng diện tích xây dựng 18.000 mét vuông của toàn bộ công trình.","doc":4},{"loai":"ban_co_biet","text":"Bốn khối hình vuông ở phần trên tòa nhà Bảo tàng vừa tạo hình bốn cánh sen, vừa là bốn lối nhìn hướng ra các di tích lịch sử xung quanh Quảng trường Ba Đình — một chi tiết kiến trúc kết hợp giữa hình thức thẩm mỹ và công năng sử dụng.","nguon_ten":"Sở Văn hóa và Thể thao Hà Nội; Bảo tàng Hồ Chí Minh","doc":5},{"loai":"anh","src":"textures/bang_w/G17_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bảo tàng Hồ Chí Minh, Hà Nội”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Một nghị quyết của thế giới","text":"Việc chọn đúng dịp 100 năm ngày sinh Chủ tịch Hồ Chí Minh để khánh thành Bảo tàng không phải ngẫu nhiên. Năm 1987, Đại hội đồng UNESCO đã thông qua nghị quyết vinh danh Hồ Chí Minh là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam, khuyến nghị các nước thành viên tổ chức kỷ niệm 100 năm ngày sinh của Người vào năm 1990. Đây là một trong số ít trường hợp một tổ chức quốc tế chính thức ghi nhận tầm vóc của một lãnh tụ cách mạng ở cả hai phương diện: đấu tranh giải phóng dân tộc và đóng góp văn hóa cho nhân loại. Bảo tàng Hồ Chí Minh, vì vậy, không chỉ là một công trình tưởng niệm trong nước mà còn mang ý nghĩa của một sự kiện văn hóa được thế giới ghi nhận.","doc":6},{"loai":"doan","tieu_de":"Kho tư liệu về một cuộc đời","text":"Kho của Bảo tàng lưu giữ hơn 170.000 tài liệu, hiện vật và phim ảnh về cuộc đời, sự nghiệp của Chủ tịch Hồ Chí Minh. Không chỉ trưng bày, Bảo tàng còn là trung tâm sưu tầm, nghiên cứu, tổ chức các trưng bày chuyên đề và triển lãm lưu động trong và ngoài nước, góp phần đưa hình ảnh của Người đến gần hơn với công chúng, nhất là thế hệ trẻ. Mỗi hiện vật được sưu tầm thêm là một mảnh ghép giúp câu chuyện về Người đầy đặn hơn.","doc":7},{"loai":"ban_co_biet","text":"Ngoài trụ sở chính ở Hà Nội, Bảo tàng Hồ Chí Minh còn có chi nhánh tại Thành phố Hồ Chí Minh, đặt ở Bến Nhà Rồng — nơi Nguyễn Tất Thành ra đi tìm đường cứu nước ngày 5/6/1911.","nguon_ten":"Bảo tàng Hồ Chí Minh","doc":8},{"loai":"anh","src":"textures/bang_w/G17_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bảo tàng Hồ Chí Minh, Hà Nội”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Một hình tượng kiến trúc hiếm có","text":"Trong số các bảo tàng lớn ở Việt Nam, Bảo tàng Hồ Chí Minh là một trong số ít công trình được thiết kế theo một hình tượng biểu trưng xuyên suốt toàn bộ khối kiến trúc, thay vì theo dạng khối hành chính vuông vắn thông thường. Lựa chọn ấy đặt ra không ít thách thức kỹ thuật cho các kiến trúc sư và kỹ sư thi công vào giữa thập niên 1980, khi điều kiện vật tư, phương tiện xây dựng ở Việt Nam còn nhiều hạn chế. Việc hoàn thành một công trình có hình khối phức tạp như vậy, đúng tiến độ để kịp khánh thành vào dịp kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh, cũng vì thế mà trở thành một nỗ lực đáng ghi nhận của cả đội ngũ thiết kế, thi công Việt Nam và các chuyên gia Liên Xô cùng tham gia dự án.","doc":9},{"loai":"doan","tieu_de":"Nơi hội tụ của quần thể di tích","text":"Đứng từ Bảo tàng Hồ Chí Minh, du khách có thể nhìn thấy gần như trọn vẹn quần thể di tích quanh Quảng trường Ba Đình: Lăng Chủ tịch Hồ Chí Minh phía trước, Khu Di tích Phủ Chủ tịch với ngôi nhà sàn giản dị phía sau, Nhà Quốc hội hiện đại, và chùa Một Cột nghìn năm tuổi ở một góc gần đó. Nhiều đoàn khách, cả trong nước lẫn quốc tế, thường sắp xếp lịch tham quan theo trình tự: vào Lăng viếng Người vào buổi sáng, sau đó thăm Khu Di tích Phủ Chủ tịch, rồi kết thúc hành trình tại Bảo tàng để tìm hiểu sâu hơn, kỹ hơn về cuộc đời và sự nghiệp Người qua từng tài liệu, hiện vật được trưng bày. Cách sắp xếp không gian ấy khiến toàn bộ quần thể trở thành một hành trình cảm xúc liền mạch, đi từ sự tưởng niệm trang nghiêm đến sự thấu hiểu sâu sắc hơn về một cuộc đời.","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hơn ba mươi năm kể từ ngày khánh thành, Bảo tàng Hồ Chí Minh vẫn là một trong những điểm đến quan trọng bậc nhất khi tìm hiểu về Chủ tịch Hồ Chí Minh tại Hà Nội, đón hàng trăm nghìn lượt khách tham quan mỗi năm, trong đó có nhiều đoàn học sinh, sinh viên, cựu chiến binh và khách quốc tế. Bảo tàng vẫn tiếp tục công việc sưu tầm, bổ sung hiện vật, tổ chức các trưng bày chuyên đề nhân những dịp kỷ niệm lớn của đất nước. Với nhiều thế hệ học sinh, sinh viên, một buổi tham quan Bảo tàng Hồ Chí Minh vẫn thường là bài học lịch sử sống động đầu tiên về cuộc đời của vị lãnh tụ dân tộc, trước khi các em tìm đọc thêm sách vở hay đến thăm những khu di tích khác gắn với Người trên khắp đất nước, từ quê hương Kim Liên, Nghệ An cho tới hang Pác Bó, Cao Bằng.","doc":11}],"nguon":["Bảo tàng Hồ Chí Minh","Nghị quyết 24C/18.65, khóa họp lần thứ 24 Đại hội đồng UNESCO, 1987","Sở Văn hóa và Thể thao Hà Nội","Cổng Thông tin điện tử Chính phủ (baochinhphu.vn)"],"doc":[{"t":"Bảo tàng Hồ Chí Minh: bông sen trắng dâng Người tròn trăm tuổi. Ngày 19 tháng 5 năm 1990, đúng 100 năm ngày sinh Chủ tịch Hồ Chí Minh, một công trình mang dáng bông sen trắng khổng lồ mở cửa ngay cạnh Lăng của Người. Từ đó, Bảo tàng Hồ Chí Minh trở thành nơi lưu giữ, nghiên cứu và giới thiệu toàn diện nhất về cuộc đời, sự nghiệp của Người — không chỉ bằng hiện vật, mà bằng chính ngôn ngữ của kiến trúc."},{"t":"Một công trình cho ngày trăm tuổi. Bảo tàng Hồ Chí Minh được khởi công ngày 31 tháng 8 năm 1985 và khánh thành ngày 19 tháng 5 năm 1990, đúng vào dịp kỷ niệm 100 năm ngày sinh của Người — sự kiện mà Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO) đã ra nghị quyết khuyến nghị các nước thành viên cùng tham gia kỷ niệm từ năm 1987. Công trình được xây dựng với sự giúp đỡ của Liên Xô, do kiến trúc sư trưởng Garôn Ixacôvích cùng các cộng sự thiết kế, nằm trong quần thể di tích quanh Quảng trường Ba Đình, sát cạnh Lăng Chủ tịch Hồ Chí Minh, Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch và chùa Một Cột. Tấm ảnh tư liệu trong bảng được chụp tại Bảo tàng năm 2008."},{"t":"Kiến trúc hình bông sen. Khối kiến trúc của Bảo tàng được cách điệu từ hình ảnh một bông sen trắng — loài hoa gắn với tên làng Sen quê hương Người và với phẩm chất thanh cao mà người Việt vẫn gửi gắm vào hình tượng hoa sen. Tòa nhà có bình đồ hình vuông vát bốn góc, cao gần 20 mét, mỗi cạnh dài khoảng 70 mét; bốn khối hình vuông xếp ở phần trên cùng vừa tạo hình bốn cánh sen, vừa là những lối nhìn hướng ra các di tích lịch sử xung quanh. Chọn bông sen làm hình tượng cho một bảo tàng về Chủ tịch Hồ Chí Minh là cách nói về cuộc đời Người bằng ngôn ngữ kiến trúc: giản dị, trong sáng, gắn bó với cội nguồn dân tộc. Từ ao sen làng Kim Liên đến bông sen giữa Thủ đô là cả một hành trình của một đời người."},{"t":"Một hồ nước và hòn đảo đá bao quanh. Bao quanh tòa nhà chính là một hồ nước nhân tạo hình tròn, đường kính khoảng 18 mét, giữa hồ nổi lên một hòn đảo đá tự nhiên cao hơn 7 mét — chi tiết kiến trúc gợi liên tưởng đến những vùng non nước quê hương Việt Nam. Mặt nước phẳng lặng phản chiếu khối kiến trúc trắng của Bảo tàng, tạo nên một tổng thể vừa hiện đại vừa mang hơi thở thiên nhiên — khác hẳn với vẻ uy nghiêm bằng đá granite xám của Lăng ở ngay bên cạnh. Sự tương phản có chủ ý ấy giữa hai công trình gần nhau — một nơi để tưởng niệm, một nơi để tìm hiểu — cũng phần nào phản ánh hai cách người đời sau bày tỏ tình cảm với Người: bằng sự trang nghiêm lặng lẽ và bằng sự trân trọng, tìm tòi hiểu biết."},{"t":"Bên trong sảnh chính. Bước vào sảnh chính của Bảo tàng, hình ảnh đầu tiên đập vào mắt du khách là bức tượng đồng Chủ tịch Hồ Chí Minh, cao khoảng 3,5 mét, đặt trang trọng giữa không gian rộng lớn. Từ sảnh chính, các lối đi dẫn khách tham quan lần lượt qua từng khu trưng bày, được sắp xếp theo dòng thời gian cuộc đời Người — từ thời niên thiếu ở Nghệ An, những năm bôn ba tìm đường cứu nước, đến sự nghiệp lãnh đạo cách mạng và tình cảm của nhân dân, bạn bè quốc tế dành cho Người (xem chuyên đề Bên trong Bảo tàng Hồ Chí Minh). Không gian trưng bày rộng khoảng 13.000 mét vuông, trong tổng diện tích xây dựng 18.000 mét vuông của toàn bộ công trình."},{"t":"Bạn có biết? Bốn khối hình vuông ở phần trên tòa nhà Bảo tàng vừa tạo hình bốn cánh sen, vừa là bốn lối nhìn hướng ra các di tích lịch sử xung quanh Quảng trường Ba Đình — một chi tiết kiến trúc kết hợp giữa hình thức thẩm mỹ và công năng sử dụng."},{"t":"Một nghị quyết của thế giới. Việc chọn đúng dịp 100 năm ngày sinh Chủ tịch Hồ Chí Minh để khánh thành Bảo tàng không phải ngẫu nhiên. Năm 1987, Đại hội đồng UNESCO đã thông qua nghị quyết vinh danh Hồ Chí Minh là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam, khuyến nghị các nước thành viên tổ chức kỷ niệm 100 năm ngày sinh của Người vào năm 1990. Đây là một trong số ít trường hợp một tổ chức quốc tế chính thức ghi nhận tầm vóc của một lãnh tụ cách mạng ở cả hai phương diện: đấu tranh giải phóng dân tộc và đóng góp văn hóa cho nhân loại. Bảo tàng Hồ Chí Minh, vì vậy, không chỉ là một công trình tưởng niệm trong nước mà còn mang ý nghĩa của một sự kiện văn hóa được thế giới ghi nhận."},{"t":"Kho tư liệu về một cuộc đời. Kho của Bảo tàng lưu giữ hơn 170.000 tài liệu, hiện vật và phim ảnh về cuộc đời, sự nghiệp của Chủ tịch Hồ Chí Minh. Không chỉ trưng bày, Bảo tàng còn là trung tâm sưu tầm, nghiên cứu, tổ chức các trưng bày chuyên đề và triển lãm lưu động trong và ngoài nước, góp phần đưa hình ảnh của Người đến gần hơn với công chúng, nhất là thế hệ trẻ. Mỗi hiện vật được sưu tầm thêm là một mảnh ghép giúp câu chuyện về Người đầy đặn hơn."},{"t":"Bạn có biết? Ngoài trụ sở chính ở Hà Nội, Bảo tàng Hồ Chí Minh còn có chi nhánh tại Thành phố Hồ Chí Minh, đặt ở Bến Nhà Rồng — nơi Nguyễn Tất Thành ra đi tìm đường cứu nước ngày 5/6/1911."},{"t":"Một hình tượng kiến trúc hiếm có. Trong số các bảo tàng lớn ở Việt Nam, Bảo tàng Hồ Chí Minh là một trong số ít công trình được thiết kế theo một hình tượng biểu trưng xuyên suốt toàn bộ khối kiến trúc, thay vì theo dạng khối hành chính vuông vắn thông thường. Lựa chọn ấy đặt ra không ít thách thức kỹ thuật cho các kiến trúc sư và kỹ sư thi công vào giữa thập niên 1980, khi điều kiện vật tư, phương tiện xây dựng ở Việt Nam còn nhiều hạn chế. Việc hoàn thành một công trình có hình khối phức tạp như vậy, đúng tiến độ để kịp khánh thành vào dịp kỷ niệm 100 năm ngày sinh Chủ tịch Hồ Chí Minh, cũng vì thế mà trở thành một nỗ lực đáng ghi nhận của cả đội ngũ thiết kế, thi công Việt Nam và các chuyên gia Liên Xô cùng tham gia dự án."},{"t":"Nơi hội tụ của quần thể di tích. Đứng từ Bảo tàng Hồ Chí Minh, du khách có thể nhìn thấy gần như trọn vẹn quần thể di tích quanh Quảng trường Ba Đình: Lăng Chủ tịch Hồ Chí Minh phía trước, Khu Di tích Phủ Chủ tịch với ngôi nhà sàn giản dị phía sau, Nhà Quốc hội hiện đại, và chùa Một Cột nghìn năm tuổi ở một góc gần đó. Nhiều đoàn khách, cả trong nước lẫn quốc tế, thường sắp xếp lịch tham quan theo trình tự: vào Lăng viếng Người vào buổi sáng, sau đó thăm Khu Di tích Phủ Chủ tịch, rồi kết thúc hành trình tại Bảo tàng để tìm hiểu sâu hơn, kỹ hơn về cuộc đời và sự nghiệp Người qua từng tài liệu, hiện vật được trưng bày. Cách sắp xếp không gian ấy khiến toàn bộ quần thể trở thành một hành trình cảm xúc liền mạch, đi từ sự tưởng niệm trang nghiêm đến sự thấu hiểu sâu sắc hơn về một cuộc đời."},{"t":"Dấu tích hôm nay. Hơn ba mươi năm kể từ ngày khánh thành, Bảo tàng Hồ Chí Minh vẫn là một trong những điểm đến quan trọng bậc nhất khi tìm hiểu về Chủ tịch Hồ Chí Minh tại Hà Nội, đón hàng trăm nghìn lượt khách tham quan mỗi năm, trong đó có nhiều đoàn học sinh, sinh viên, cựu chiến binh và khách quốc tế. Bảo tàng vẫn tiếp tục công việc sưu tầm, bổ sung hiện vật, tổ chức các trưng bày chuyên đề nhân những dịp kỷ niệm lớn của đất nước. Với nhiều thế hệ học sinh, sinh viên, một buổi tham quan Bảo tàng Hồ Chí Minh vẫn thường là bài học lịch sử sống động đầu tiên về cuộc đời của vị lãnh tụ dân tộc, trước khi các em tìm đọc thêm sách vở hay đến thăm những khu di tích khác gắn với Người trên khắp đất nước, từ quê hương Kim Liên, Nghệ An cho tới hang Pác Bó, Cao Bằng."}],"so_chu":1478},{"i":8,"tieu_de_bang":"Bên trong Bảo tàng Hồ Chí Minh","tieu_de":"Bên trong Bảo tàng: đi hết một cuộc đời qua tài liệu, hiện vật và nghệ thuật","sapo":"Bước vào Bảo tàng Hồ Chí Minh, khách tham quan lần lượt đi qua những chặng đường của một cuộc đời: từ làng Sen đến những bến cảng xa, từ hang Pác Bó đến Quảng trường Ba Đình. Tấm ảnh chụp năm 2008 ghi lại một góc không gian trưng bày bên trong — nơi hàng triệu người đã dừng chân, có người đứng thật lâu trước một bức thư viết tay, có người lặng đi trước một đôi dép cao su đã mòn.","bia":{"src":"textures/ht/ht_anh_hanoi_vietnam_interiors_of_ho_chi_minh_museum.jpg","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một buổi sáng giữa tháng Năm","text":"Sáng 19 tháng 5 năm 1990, đúng ngày kỷ niệm tròn một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, một tòa nhà mới bên cạnh Quảng trường Ba Đình chính thức mở cửa đón khách. Đó là Bảo tàng Hồ Chí Minh — công trình được chuẩn bị suốt nhiều năm để lưu giữ và kể lại cuộc đời của Người bằng tài liệu, hiện vật gốc. Từ ngày ấy, hàng triệu lượt người, cả trong nước lẫn quốc tế, đã bước qua cánh cửa này, đi chậm rãi qua từng gian trưng bày. Tấm ảnh chụp năm 2008 ghi lại đúng một khoảnh khắc bình thường như thế: một góc không gian bên trong bảo tàng, nơi câu chuyện về một cuộc đời vẫn đang được kể lại mỗi ngày cho những người mới đến.","doc":1},{"loai":"doan","tieu_de":"Hai mươi năm từ nghị quyết đến ngày khánh thành","text":"Trước khi có tòa nhà, đã có một quyết định. Ngày 25 tháng 11 năm 1970, khi cuộc kháng chiến chống Mỹ, cứu nước còn đang ở giai đoạn ác liệt, Ban Bí thư Trung ương Đảng ra Nghị quyết số 206-NQ/TW, thành lập Ban phụ trách xây dựng Bảo tàng Hồ Chí Minh. Đất nước khi ấy còn chưa thống nhất, nhưng việc sưu tầm, gìn giữ tài liệu, hiện vật về Người đã được đặt ra như một nhiệm vụ cấp thiết, bởi ký ức và kỷ vật là thứ dễ mất đi nhất theo thời gian và chiến tranh. Phải đến khi đất nước hòa bình, thống nhất, công trình mới thật sự được khởi công, trên khu đất gần Lăng Chủ tịch Hồ Chí Minh, trong quần thể di tích Ba Đình. Gần hai mươi năm từ ngày có nghị quyết đầu tiên đến ngày khánh thành là quãng thời gian đủ để hàng vạn tài liệu, hiện vật, hồi ức của những người từng sống, làm việc bên Người được sưu tầm, thẩm định, hệ thống hóa thành một câu chuyện hoàn chỉnh.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_hanoi_vietnam_ho_chi_minh_museum_the_pyramid.jpg","chu_thich":"Bảo tàng Hồ Chí Minh nhìn từ bên ngoài — công trình khánh thành ngày 19/5/1990 (ảnh chụp năm 2008).","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một hình khối mang ý nghĩa biểu tượng","text":"Tòa nhà bảo tàng gây ấn tượng ngay từ khối kiến trúc bên ngoài: đường nét vuông vắn, khỏe khoắn, được nhiều người ví như một đóa sen cách điệu — loài hoa vẫn được coi là biểu tượng cho phẩm cách thanh cao, giản dị của Chủ tịch Hồ Chí Minh. Phía trước là khoảng sân rộng, nhìn thẳng sang Lăng và Quảng trường Ba Đình, tạo thành một trục không gian liền mạch: từ nơi Người an nghỉ đến nơi cuộc đời Người được kể lại bằng hiện vật. Bên trong, các phòng trưng bày nối với nhau bằng những khoảng sảnh rộng, đủ chỗ cho những đoàn khách đông đúc vẫn thường xếp hàng vào những dịp lễ lớn. Ánh sáng trong bảo tàng phần lớn là ánh sáng nhân tạo, được tính toán kỹ để vừa bảo vệ tài liệu, hiện vật quý khỏi tác động của nắng, vừa làm nổi bật từng hiện vật khi khách đứng ngắm.","doc":3},{"loai":"anh","src":"textures/bang_w/G17_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bên trong Bảo tàng Hồ Chí Minh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Một hành trình theo dòng thời gian","text":"Phần trưng bày chính của bảo tàng được sắp xếp theo trình tự thời gian, bắt đầu từ quê hương Nghệ An, nơi cậu bé Nguyễn Sinh Cung ra đời năm 1890, đi qua những năm tháng dạy học ở Phan Thiết, buổi sáng ngày 5 tháng 6 năm 1911 rời bến Nhà Rồng ra đi tìm đường cứu nước, rồi ba mươi năm bôn ba qua nhiều châu lục, cho tới ngày 28 tháng 1 năm 1941 trở về nước qua cột mốc 108 ở Pác Bó. Từ đó, mạch trưng bày tiếp tục theo những năm tháng lãnh đạo cách mạng ở Việt Bắc, ngày đọc Tuyên ngôn Độc lập 2 tháng 9 năm 1945 tại Ba Đình, hai cuộc kháng chiến, cho đến những dòng cuối trong bản Di chúc. Mỗi giai đoạn được minh họa bằng tài liệu gốc: thư từ, bài viết, ảnh chụp, cùng những vật dụng giản dị Người từng dùng. Cách sắp xếp ấy giúp người xem không cần đọc một cuốn sách dày, vẫn có thể hình dung được trọn vẹn một cuộc đời chỉ qua một buổi tham quan.","doc":4},{"loai":"ban_co_biet","text":"Bảo tàng khánh thành đúng ngày 19 tháng 5 năm 1990 — cùng năm Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO) ra nghị quyết tôn vinh Hồ Chí Minh là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam, tại kỳ họp Đại hội đồng năm 1987.","nguon_ten":"Nghị quyết 24C/18.65 của UNESCO, 1987","doc":5},{"loai":"anh","src":"textures/bang_w/G17_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bên trong Bảo tàng Hồ Chí Minh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hiện vật thật và không gian biểu tượng","text":"Bên cạnh những tài liệu, hiện vật gốc, bảo tàng còn có một điểm khác biệt so với nhiều bảo tàng lịch sử thông thường: xen giữa các gian trưng bày theo dòng thời gian là những không gian được dàn dựng bằng hình khối, chất liệu, ánh sáng mang tính biểu tượng, gợi lại bối cảnh những biến động lớn của thế kỷ XX mà Người đã sống và hoạt động trong đó. Cách kể chuyện song song ấy — vừa cụ thể bằng hiện vật thật, vừa gợi mở bằng hình tượng nghệ thuật — giúp người xem cảm nhận được không chỉ Người đã làm gì, mà còn hiểu vì sao Người lại đi đến những quyết định ấy, giữa một thế giới đầy biến động.","doc":6},{"loai":"doan","tieu_de":"Một phần của cụm di tích Ba Đình","text":"Bảo tàng Hồ Chí Minh không đứng riêng lẻ, mà nằm trong Cụm di tích lịch sử - văn hóa Ba Đình, liền kề Lăng Chủ tịch Hồ Chí Minh, Phủ Chủ tịch, nhà sàn và ao cá Bác Hồ, chùa Một Cột. Nhiều đoàn khách, sau khi vào Lăng viếng Người, sẽ tiếp tục hành trình sang thăm nơi Người từng sống và làm việc, rồi kết thúc bằng buổi tham quan bảo tàng — nơi toàn bộ câu chuyện được hệ thống lại một lần nữa, đầy đủ và có bối cảnh hơn. Với nhiều học sinh, sinh viên, đây thường là điểm đến trong những chuyến đi thực tế, ngoại khóa tìm hiểu về lịch sử dân tộc.","doc":7},{"loai":"ban_co_biet","text":"Ngoài trụ sở chính ở Hà Nội, hệ thống bảo tàng và khu di tích lưu niệm về Chủ tịch Hồ Chí Minh hiện có mặt tại nhiều tỉnh, thành trong cả nước, trong đó có các chi nhánh tại Thừa Thiên Huế, Cần Thơ và khu vực Quân khu 5 — mỗi nơi giữ một phần câu chuyện gắn với những năm tháng Người từng đi qua.","nguon_ten":"Cổng thông tin về Chủ tịch Hồ Chí Minh (hochiminh.vn)","doc":8},{"loai":"doan","tieu_de":"Nơi gặp gỡ của nhiều thế hệ","text":"Không chỉ đón khách tham quan thông thường, bảo tàng còn là nơi tổ chức lễ kết nạp Đảng, lễ báo công, lễ dâng hoa của nhiều cơ quan, đơn vị, trường học mỗi khi có dịp kỷ niệm lớn. Vào những ngày như sinh nhật Bác 19 tháng 5, Quốc khánh 2 tháng 9, dòng người xếp hàng vào bảo tàng thường đông hơn hẳn ngày thường, có cả những đoàn học sinh tiểu học lần đầu được nghe kể về cuộc đời một con người mà trước đó các em chỉ biết qua sách giáo khoa. Với nhiều gia đình, một chuyến thăm bảo tàng cùng con cháu vẫn là cách được chọn để kể lại câu chuyện lịch sử theo một cách trực quan, sống động hơn những trang sách.","doc":9},{"loai":"anh","src":"textures/bang_w/G17_8_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bên trong Bảo tàng Hồ Chí Minh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Ảnh tư liệu và những người gìn giữ","text":"Phần lớn ảnh, tài liệu trưng bày trong bảo tàng là bản gốc hoặc bản sao có kiểm định chặt chẽ, được các cán bộ lưu trữ, nghiên cứu dày công sưu tầm suốt nhiều thập kỷ, từ trong nước lẫn từ các viện lưu trữ, thư viện ở nước ngoài. Nhiều bức ảnh, trong đó có tấm ảnh chụp năm 2008 minh họa cho bài viết này, đến được với công chúng nhờ những người chụp ảnh sẵn lòng chia sẻ tác phẩm của mình theo giấy phép mở, giúp tư liệu về đất nước, con người Việt Nam lan tỏa rộng hơn ra ngoài biên giới. Những năm gần đây, một phần tài liệu, hiện vật của bảo tàng cũng đã được số hóa, giới thiệu trên các nền tảng trực tuyến, giúp công chúng ở xa vẫn có thể tra cứu, tìm hiểu.","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hơn ba mươi lăm năm kể từ ngày khánh thành, Bảo tàng Hồ Chí Minh vẫn mở cửa đều đặn các ngày trong tuần, đón khách trong nước và quốc tế, đồng thời là nơi thường xuyên tổ chức các cuộc triển lãm chuyên đề về cuộc đời, sự nghiệp Chủ tịch Hồ Chí Minh và về lịch sử cách mạng Việt Nam. Kho tài liệu, hiện vật của bảo tàng vẫn tiếp tục được bổ sung qua các đợt sưu tầm mới, khi nhiều tư liệu về những năm Người hoạt động ở nước ngoài dần được tìm thấy, hiến tặng hoặc sao chụp về.","doc":11},{"loai":"doan","tieu_de":"Nối dài không gian trưng bày","text":"Ngày nay, cách kể về Chủ tịch Hồ Chí Minh không chỉ nằm trong bốn bức tường của bảo tàng. Các chuyên đề, triển lãm lưu động đưa tài liệu về Người đến trường học, cơ quan, địa phương; những ứng dụng số, không gian ảo giúp người ở xa cũng có thể hình dung được những nơi Người từng sống và làm việc. Bảo tàng số mà bạn đang tham quan cũng là một cách nối dài hành trình ấy — từ làng Sen đến Quảng trường Ba Đình, chỉ bằng vài cú chạm.","doc":12}],"nguon":["Bảo tàng Hồ Chí Minh","Nghị quyết số 206-NQ/TW ngày 25/11/1970 của Ban Bí thư Trung ương Đảng","Nghị quyết 24C/18.65 của UNESCO, 1987","Cổng thông tin về Chủ tịch Hồ Chí Minh (hochiminh.vn)","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia"],"doc":[{"t":"Bên trong Bảo tàng: đi hết một cuộc đời qua tài liệu, hiện vật và nghệ thuật. Bước vào Bảo tàng Hồ Chí Minh, khách tham quan lần lượt đi qua những chặng đường của một cuộc đời: từ làng Sen đến những bến cảng xa, từ hang Pác Bó đến Quảng trường Ba Đình. Tấm ảnh chụp năm 2008 ghi lại một góc không gian trưng bày bên trong — nơi hàng triệu người đã dừng chân, có người đứng thật lâu trước một bức thư viết tay, có người lặng đi trước một đôi dép cao su đã mòn."},{"t":"Một buổi sáng giữa tháng Năm. Sáng 19 tháng 5 năm 1990, đúng ngày kỷ niệm tròn một trăm năm ngày sinh Chủ tịch Hồ Chí Minh, một tòa nhà mới bên cạnh Quảng trường Ba Đình chính thức mở cửa đón khách. Đó là Bảo tàng Hồ Chí Minh — công trình được chuẩn bị suốt nhiều năm để lưu giữ và kể lại cuộc đời của Người bằng tài liệu, hiện vật gốc. Từ ngày ấy, hàng triệu lượt người, cả trong nước lẫn quốc tế, đã bước qua cánh cửa này, đi chậm rãi qua từng gian trưng bày. Tấm ảnh chụp năm 2008 ghi lại đúng một khoảnh khắc bình thường như thế: một góc không gian bên trong bảo tàng, nơi câu chuyện về một cuộc đời vẫn đang được kể lại mỗi ngày cho những người mới đến."},{"t":"Hai mươi năm từ nghị quyết đến ngày khánh thành. Trước khi có tòa nhà, đã có một quyết định. Ngày 25 tháng 11 năm 1970, khi cuộc kháng chiến chống Mỹ, cứu nước còn đang ở giai đoạn ác liệt, Ban Bí thư Trung ương Đảng ra Nghị quyết số 206-NQ/TW, thành lập Ban phụ trách xây dựng Bảo tàng Hồ Chí Minh. Đất nước khi ấy còn chưa thống nhất, nhưng việc sưu tầm, gìn giữ tài liệu, hiện vật về Người đã được đặt ra như một nhiệm vụ cấp thiết, bởi ký ức và kỷ vật là thứ dễ mất đi nhất theo thời gian và chiến tranh. Phải đến khi đất nước hòa bình, thống nhất, công trình mới thật sự được khởi công, trên khu đất gần Lăng Chủ tịch Hồ Chí Minh, trong quần thể di tích Ba Đình. Gần hai mươi năm từ ngày có nghị quyết đầu tiên đến ngày khánh thành là quãng thời gian đủ để hàng vạn tài liệu, hiện vật, hồi ức của những người từng sống, làm việc bên Người được sưu tầm, thẩm định, hệ thống hóa thành một câu chuyện hoàn chỉnh."},{"t":"Một hình khối mang ý nghĩa biểu tượng. Tòa nhà bảo tàng gây ấn tượng ngay từ khối kiến trúc bên ngoài: đường nét vuông vắn, khỏe khoắn, được nhiều người ví như một đóa sen cách điệu — loài hoa vẫn được coi là biểu tượng cho phẩm cách thanh cao, giản dị của Chủ tịch Hồ Chí Minh. Phía trước là khoảng sân rộng, nhìn thẳng sang Lăng và Quảng trường Ba Đình, tạo thành một trục không gian liền mạch: từ nơi Người an nghỉ đến nơi cuộc đời Người được kể lại bằng hiện vật. Bên trong, các phòng trưng bày nối với nhau bằng những khoảng sảnh rộng, đủ chỗ cho những đoàn khách đông đúc vẫn thường xếp hàng vào những dịp lễ lớn. Ánh sáng trong bảo tàng phần lớn là ánh sáng nhân tạo, được tính toán kỹ để vừa bảo vệ tài liệu, hiện vật quý khỏi tác động của nắng, vừa làm nổi bật từng hiện vật khi khách đứng ngắm."},{"t":"Một hành trình theo dòng thời gian. Phần trưng bày chính của bảo tàng được sắp xếp theo trình tự thời gian, bắt đầu từ quê hương Nghệ An, nơi cậu bé Nguyễn Sinh Cung ra đời năm 1890, đi qua những năm tháng dạy học ở Phan Thiết, buổi sáng ngày 5 tháng 6 năm 1911 rời bến Nhà Rồng ra đi tìm đường cứu nước, rồi ba mươi năm bôn ba qua nhiều châu lục, cho tới ngày 28 tháng 1 năm 1941 trở về nước qua cột mốc 108 ở Pác Bó. Từ đó, mạch trưng bày tiếp tục theo những năm tháng lãnh đạo cách mạng ở Việt Bắc, ngày đọc Tuyên ngôn Độc lập 2 tháng 9 năm 1945 tại Ba Đình, hai cuộc kháng chiến, cho đến những dòng cuối trong bản Di chúc. Mỗi giai đoạn được minh họa bằng tài liệu gốc: thư từ, bài viết, ảnh chụp, cùng những vật dụng giản dị Người từng dùng. Cách sắp xếp ấy giúp người xem không cần đọc một cuốn sách dày, vẫn có thể hình dung được trọn vẹn một cuộc đời chỉ qua một buổi tham quan."},{"t":"Bạn có biết? Bảo tàng khánh thành đúng ngày 19 tháng 5 năm 1990 — cùng năm Tổ chức Giáo dục, Khoa học và Văn hóa Liên hợp quốc (UNESCO) ra nghị quyết tôn vinh Hồ Chí Minh là Anh hùng giải phóng dân tộc và Nhà văn hóa kiệt xuất của Việt Nam, tại kỳ họp Đại hội đồng năm 1987."},{"t":"Hiện vật thật và không gian biểu tượng. Bên cạnh những tài liệu, hiện vật gốc, bảo tàng còn có một điểm khác biệt so với nhiều bảo tàng lịch sử thông thường: xen giữa các gian trưng bày theo dòng thời gian là những không gian được dàn dựng bằng hình khối, chất liệu, ánh sáng mang tính biểu tượng, gợi lại bối cảnh những biến động lớn của thế kỷ XX mà Người đã sống và hoạt động trong đó. Cách kể chuyện song song ấy — vừa cụ thể bằng hiện vật thật, vừa gợi mở bằng hình tượng nghệ thuật — giúp người xem cảm nhận được không chỉ Người đã làm gì, mà còn hiểu vì sao Người lại đi đến những quyết định ấy, giữa một thế giới đầy biến động."},{"t":"Một phần của cụm di tích Ba Đình. Bảo tàng Hồ Chí Minh không đứng riêng lẻ, mà nằm trong Cụm di tích lịch sử - văn hóa Ba Đình, liền kề Lăng Chủ tịch Hồ Chí Minh, Phủ Chủ tịch, nhà sàn và ao cá Bác Hồ, chùa Một Cột. Nhiều đoàn khách, sau khi vào Lăng viếng Người, sẽ tiếp tục hành trình sang thăm nơi Người từng sống và làm việc, rồi kết thúc bằng buổi tham quan bảo tàng — nơi toàn bộ câu chuyện được hệ thống lại một lần nữa, đầy đủ và có bối cảnh hơn. Với nhiều học sinh, sinh viên, đây thường là điểm đến trong những chuyến đi thực tế, ngoại khóa tìm hiểu về lịch sử dân tộc."},{"t":"Bạn có biết? Ngoài trụ sở chính ở Hà Nội, hệ thống bảo tàng và khu di tích lưu niệm về Chủ tịch Hồ Chí Minh hiện có mặt tại nhiều tỉnh, thành trong cả nước, trong đó có các chi nhánh tại Thừa Thiên Huế, Cần Thơ và khu vực Quân khu 5 — mỗi nơi giữ một phần câu chuyện gắn với những năm tháng Người từng đi qua."},{"t":"Nơi gặp gỡ của nhiều thế hệ. Không chỉ đón khách tham quan thông thường, bảo tàng còn là nơi tổ chức lễ kết nạp Đảng, lễ báo công, lễ dâng hoa của nhiều cơ quan, đơn vị, trường học mỗi khi có dịp kỷ niệm lớn. Vào những ngày như sinh nhật Bác 19 tháng 5, Quốc khánh 2 tháng 9, dòng người xếp hàng vào bảo tàng thường đông hơn hẳn ngày thường, có cả những đoàn học sinh tiểu học lần đầu được nghe kể về cuộc đời một con người mà trước đó các em chỉ biết qua sách giáo khoa. Với nhiều gia đình, một chuyến thăm bảo tàng cùng con cháu vẫn là cách được chọn để kể lại câu chuyện lịch sử theo một cách trực quan, sống động hơn những trang sách."},{"t":"Ảnh tư liệu và những người gìn giữ. Phần lớn ảnh, tài liệu trưng bày trong bảo tàng là bản gốc hoặc bản sao có kiểm định chặt chẽ, được các cán bộ lưu trữ, nghiên cứu dày công sưu tầm suốt nhiều thập kỷ, từ trong nước lẫn từ các viện lưu trữ, thư viện ở nước ngoài. Nhiều bức ảnh, trong đó có tấm ảnh chụp năm 2008 minh họa cho bài viết này, đến được với công chúng nhờ những người chụp ảnh sẵn lòng chia sẻ tác phẩm của mình theo giấy phép mở, giúp tư liệu về đất nước, con người Việt Nam lan tỏa rộng hơn ra ngoài biên giới. Những năm gần đây, một phần tài liệu, hiện vật của bảo tàng cũng đã được số hóa, giới thiệu trên các nền tảng trực tuyến, giúp công chúng ở xa vẫn có thể tra cứu, tìm hiểu."},{"t":"Dấu tích hôm nay. Hơn ba mươi lăm năm kể từ ngày khánh thành, Bảo tàng Hồ Chí Minh vẫn mở cửa đều đặn các ngày trong tuần, đón khách trong nước và quốc tế, đồng thời là nơi thường xuyên tổ chức các cuộc triển lãm chuyên đề về cuộc đời, sự nghiệp Chủ tịch Hồ Chí Minh và về lịch sử cách mạng Việt Nam. Kho tài liệu, hiện vật của bảo tàng vẫn tiếp tục được bổ sung qua các đợt sưu tầm mới, khi nhiều tư liệu về những năm Người hoạt động ở nước ngoài dần được tìm thấy, hiến tặng hoặc sao chụp về."},{"t":"Nối dài không gian trưng bày. Ngày nay, cách kể về Chủ tịch Hồ Chí Minh không chỉ nằm trong bốn bức tường của bảo tàng. Các chuyên đề, triển lãm lưu động đưa tài liệu về Người đến trường học, cơ quan, địa phương; những ứng dụng số, không gian ảo giúp người ở xa cũng có thể hình dung được những nơi Người từng sống và làm việc. Bảo tàng số mà bạn đang tham quan cũng là một cách nối dài hành trình ấy — từ làng Sen đến Quảng trường Ba Đình, chỉ bằng vài cú chạm."}],"so_chu":1619},{"i":9,"tieu_de_bang":"“Học tập và làm theo” – Chỉ thị 05-CT/TW","tieu_de":"“Học tập và làm theo”: vì sao là tư tưởng, đạo đức và phong cách Hồ Chí Minh","sapo":"Câu chữ trên tấm bảng là tên gọi của một cuộc vận động lớn, được Bộ Chính trị xác định trong Chỉ thị 05-CT/TW năm 2016. Nhưng để đi tới đúng ba chữ “tư tưởng, đạo đức, phong cách”, cuộc vận động đã đi qua một chặng đường gần mười năm, qua ba văn bản khác nhau của Đảng. Điều khó nhất, như chính những người soạn thảo từng nhắc lại, không phải là học, mà là làm theo.","bia":{"src":"textures/bai/G17_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một câu khẩu hiệu, một chặng đường mười năm","text":"Nhiều người quen thuộc với câu “Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh” đến mức ít khi để ý rằng cụm từ này mới chính thức xuất hiện từ năm 2016. Trước đó, trong gần mười năm, cuộc vận động học Bác đã đi qua hai tên gọi khác, mỗi lần đổi tên là một lần nội dung được mở rộng thêm. Đằng sau một dòng khẩu hiệu ngắn gọn, vì vậy, là cả một quá trình Đảng Cộng sản Việt Nam tìm cách đưa di sản tư tưởng của Người vào đời sống, không phải như một khẩu hiệu để đọc, mà như một việc để làm.","doc":1},{"loai":"doan","tieu_de":"Từ tấm gương đạo đức...","text":"Ngày 7 tháng 11 năm 2006, Bộ Chính trị khóa X ban hành Chỉ thị số 06-CT/TW, phát động Cuộc vận động “Học tập và làm theo tấm gương đạo đức Hồ Chí Minh” trong toàn Đảng, toàn dân. Đây là lần đầu tiên việc học Bác được tổ chức thành một cuộc vận động chính thức, có chỉ đạo, có sơ kết, tổng kết ở từng cấp. Năm năm sau, ngày 14 tháng 5 năm 2011, Bộ Chính trị khóa XI ban hành Chỉ thị số 03-CT/TW, tiếp tục đẩy mạnh việc học tập và làm theo tấm gương đạo đức của Người, đưa việc này thành nội dung sinh hoạt thường xuyên của các tổ chức đảng, cơ quan, đơn vị, thay vì chỉ là một đợt vận động có thời hạn. Trọng tâm của cả hai giai đoạn này nằm ở chữ “đạo đức”: cần, kiệm, liêm, chính, chí công vô tư, hết lòng phục vụ nhân dân.","doc":2},{"loai":"anh","src":"textures/bang_w/G17_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc ““Học tập và làm theo” – Chỉ thị 05-CT/TW”, nhìn từ xa."},{"loai":"doan","tieu_de":"...đến tư tưởng, đạo đức, phong cách","text":"Ngày 15 tháng 5 năm 2016, Bộ Chính trị khóa XII, do Tổng Bí thư Nguyễn Phú Trọng ký ban hành, ra Chỉ thị số 05-CT/TW về đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh. So với hai chỉ thị trước, phạm vi được mở rộng thêm một chữ quan trọng: tư tưởng. Nội dung học tập giờ đây bao gồm cả tư tưởng của Người về độc lập dân tộc gắn liền với chủ nghĩa xã hội, về đại đoàn kết toàn dân tộc, về xây dựng Đảng và Nhà nước của dân, do dân, vì dân; học đạo đức cách mạng; và học cả phong cách — cách Người tư duy, làm việc, diễn đạt, ứng xử, sinh hoạt hằng ngày, từ tác phong dân chủ, sâu sát cơ sở, nói đi đôi với làm, đến lối sống giản dị, gần dân. Chỉ thị đặc biệt nhấn mạnh trách nhiệm nêu gương, trước hết là của cán bộ lãnh đạo, người đứng đầu mỗi cơ quan, đơn vị.","doc":3},{"loai":"trich","text":"Đảng ta là một Đảng cầm quyền. Mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư. Phải giữ gìn Đảng ta thật trong sạch, phải xứng đáng là người lãnh đạo, là người đầy tớ thật trung thành của nhân dân.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Di chúc, 1969","doc":4},{"loai":"anh","src":"textures/bang_w/G17_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc ““Học tập và làm theo” – Chỉ thị 05-CT/TW”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Kết luận nối dài một chỉ thị","text":"Năm 2021, khi chặng đường thực hiện Chỉ thị 05-CT/TW đã đi qua trọn một nhiệm kỳ Đại hội Đảng, Bộ Chính trị khóa XIII không ban hành một chỉ thị hoàn toàn mới, mà ra Kết luận số 01-KL/TW, ngày 18 tháng 5 năm 2021, về tiếp tục thực hiện Chỉ thị 05-CT/TW. Cách làm này cho thấy một điểm khác so với hai giai đoạn trước: nội dung tư tưởng, đạo đức, phong cách Hồ Chí Minh không cần thay bằng một cách gọi mới sau mỗi kỳ đại hội, mà tiếp tục được bồi đắp, cụ thể hóa cho phù hợp với yêu cầu công tác xây dựng, chỉnh đốn Đảng trong giai đoạn mới.","doc":5},{"loai":"ban_co_biet","text":"Chỉ thị 05-CT/TW là văn bản do đích thân Tổng Bí thư Nguyễn Phú Trọng ký ban hành ngày 15 tháng 5 năm 2016 — chưa đầy một tháng rưỡi sau khi Đại hội đại biểu toàn quốc lần thứ XII của Đảng bế mạc.","nguon_ten":"Chỉ thị 05-CT/TW ngày 15/5/2016 của Bộ Chính trị","doc":6},{"loai":"doan","tieu_de":"“Làm theo” mới là điều khó","text":"Chủ tịch Hồ Chí Minh luôn đòi hỏi nói phải đi đôi với làm, đã hứa thì phải giữ. Vì vậy, điểm mấu chốt của cả quá trình học tập này không nằm ở việc thuộc lòng một tư tưởng hay nhắc lại một câu nói, mà ở hai chữ “làm theo”: mỗi tổ chức, mỗi cá nhân tự đăng ký những việc làm cụ thể, có thể kiểm tra được, gắn với công việc, vị trí của mình. Trong thực tế thực hiện Chỉ thị 05-CT/TW, nhiều địa phương đã đưa ra những cách làm riêng để việc “làm theo” trở nên thiết thực và dễ đo lường hơn, thay vì dừng lại ở những buổi học nghị quyết trên hội trường.","doc":7},{"loai":"anh","src":"textures/bai/G17_v0.jpg","chu_thich":"Không gian 3D tái hiện toàn cảnh gian Di sản – Học và làm theo Bác.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Một cách làm ở Ninh Bình","text":"Tại Ninh Bình, việc học tập và làm theo Bác được cụ thể hóa bằng những phong trào có tên gọi và cách làm rõ ràng, như “Ngày thứ Hai nêu gương” hay “Gương sáng làm theo Bác mỗi tuần”, được nhiều chi bộ, đảng bộ cơ sở chủ động đưa vào kế hoạch công tác hằng năm, kèm theo các buổi kể chuyện, tọa đàm, biểu dương những tập thể, cá nhân làm tốt. Theo tổng kết của địa phương, phần lớn cán bộ, đảng viên — trên chín mươi phần trăm — hằng năm đăng ký nội dung “làm theo” cụ thể, gắn với nhiệm vụ được giao. Đó là một trong rất nhiều mô hình tương tự đang được duy trì ở các tỉnh, thành trong cả nước, mỗi nơi một cách làm, nhưng cùng chung một tinh thần: biến một tư tưởng lớn thành những việc làm nhỏ, đều đặn mỗi ngày.","doc":8},{"loai":"ban_co_biet","text":"Phải hơn hai mươi năm sau khi Chủ tịch Hồ Chí Minh qua đời, tư tưởng Hồ Chí Minh mới chính thức được Đại hội đại biểu toàn quốc lần thứ VII của Đảng (1991) xác định là nền tảng tư tưởng, cùng với chủ nghĩa Mác – Lênin.","nguon_ten":"Văn kiện Đại hội đại biểu toàn quốc lần thứ VII của Đảng, 1991","doc":9},{"loai":"doan","tieu_de":"Một tinh thần, nhiều hình thức thể hiện","text":"Không chỉ trong sinh hoạt đảng, tinh thần học tập và làm theo Bác còn được nhiều cơ quan, đoàn thể, trường học, doanh nghiệp diễn giải theo cách riêng: có nơi tổ chức hội thi kể chuyện về Bác, có nơi phát động phong trào tiết kiệm, chống lãng phí gắn với lời dạy “cần, kiệm, liêm, chính”, có nơi lồng nội dung này vào các buổi sinh hoạt chuyên môn, sinh hoạt chi đoàn. Với lực lượng vũ trang, việc học và làm theo phong cách của Người thường gắn liền với các phong trào thi đua sẵn có, như rèn luyện kỷ luật, gần dân, giúp dân. Sự đa dạng trong cách vận dụng ấy cũng chính là điều Chỉ thị 05-CT/TW mong muốn: không rập khuôn một hình thức chung, mà để mỗi ngành, mỗi địa phương tìm ra cách làm phù hợp nhất với đặc thù công việc của mình.","doc":10},{"loai":"ban_co_biet","text":"Chỉ thị 05-CT/TW xác định việc học tập và làm theo Bác phải gắn với thực hiện nhiệm vụ chính trị của từng địa phương, đơn vị, thay vì tách rời thành một hoạt động độc lập, hình thức, tách khỏi công việc chuyên môn hằng ngày.","nguon_ten":"Chỉ thị 05-CT/TW ngày 15/5/2016 của Bộ Chính trị","doc":11},{"loai":"anh","src":"textures/bang_w/G17_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc ““Học tập và làm theo” – Chỉ thị 05-CT/TW”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Một cuộc vận động, một câu trong Di chúc","text":"Câu nói được trích trong bảng này — về một Đảng cầm quyền, về đạo đức cách mạng, về việc giữ Đảng thật trong sạch — nằm trong bản Di chúc Người để lại, được công bố tại lễ truy điệu ngày 9 tháng 9 năm 1969. Nửa thế kỷ sau, những dòng ấy vẫn được nhắc lại như một lời nhắc nhở thường trực mỗi khi Đảng bàn về công tác xây dựng, chỉnh đốn Đảng, về trách nhiệm nêu gương của cán bộ, đảng viên — chính là điều mà các Chỉ thị 06, Chỉ thị 03, Chỉ thị 05 nối tiếp nhau tìm cách cụ thể hóa suốt mấy chục năm qua.","doc":12},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hơn nửa thế kỷ sau khi Người qua đời, việc học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh vẫn được duy trì như một nội dung sinh hoạt thường xuyên trong các tổ chức đảng, cơ quan, trường học, doanh nghiệp khắp cả nước, mỗi năm đều có sơ kết, biểu dương những tập thể, cá nhân tiêu biểu. Tấm bảng bạn đang xem, đặt trong gian cuối của bảo tàng số này, chính là một lời nhắc: di sản của Chủ tịch Hồ Chí Minh không chỉ nằm trong sách vở hay ở Ba Đình, mà còn tiếp tục sống trong những việc làm cụ thể, bình dị của rất nhiều người, ở rất nhiều nơi, ngay lúc này.","doc":13}],"nguon":["Chỉ thị 05-CT/TW ngày 15/5/2016 của Bộ Chính trị","Chỉ thị 06-CT/TW ngày 7/11/2006 của Bộ Chính trị","Chỉ thị 03-CT/TW ngày 14/5/2011 của Bộ Chính trị","Kết luận 01-KL/TW ngày 18/5/2021 của Bộ Chính trị","Di chúc của Chủ tịch Hồ Chí Minh, 1969","Đảng bộ tỉnh Ninh Bình (dangcongsan.org.vn)"],"doc":[{"t":"“Học tập và làm theo”: vì sao là tư tưởng, đạo đức và phong cách Hồ Chí Minh. Câu chữ trên tấm bảng là tên gọi của một cuộc vận động lớn, được Bộ Chính trị xác định trong Chỉ thị 05-CT/TW năm 2016. Nhưng để đi tới đúng ba chữ “tư tưởng, đạo đức, phong cách”, cuộc vận động đã đi qua một chặng đường gần mười năm, qua ba văn bản khác nhau của Đảng. Điều khó nhất, như chính những người soạn thảo từng nhắc lại, không phải là học, mà là làm theo."},{"t":"Một câu khẩu hiệu, một chặng đường mười năm. Nhiều người quen thuộc với câu “Học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh” đến mức ít khi để ý rằng cụm từ này mới chính thức xuất hiện từ năm 2016. Trước đó, trong gần mười năm, cuộc vận động học Bác đã đi qua hai tên gọi khác, mỗi lần đổi tên là một lần nội dung được mở rộng thêm. Đằng sau một dòng khẩu hiệu ngắn gọn, vì vậy, là cả một quá trình Đảng Cộng sản Việt Nam tìm cách đưa di sản tư tưởng của Người vào đời sống, không phải như một khẩu hiệu để đọc, mà như một việc để làm."},{"t":"Từ tấm gương đạo đức. Ngày 7 tháng 11 năm 2006, Bộ Chính trị khóa X ban hành Chỉ thị số 06-CT/TW, phát động Cuộc vận động “Học tập và làm theo tấm gương đạo đức Hồ Chí Minh” trong toàn Đảng, toàn dân. Đây là lần đầu tiên việc học Bác được tổ chức thành một cuộc vận động chính thức, có chỉ đạo, có sơ kết, tổng kết ở từng cấp. Năm năm sau, ngày 14 tháng 5 năm 2011, Bộ Chính trị khóa XI ban hành Chỉ thị số 03-CT/TW, tiếp tục đẩy mạnh việc học tập và làm theo tấm gương đạo đức của Người, đưa việc này thành nội dung sinh hoạt thường xuyên của các tổ chức đảng, cơ quan, đơn vị, thay vì chỉ là một đợt vận động có thời hạn. Trọng tâm của cả hai giai đoạn này nằm ở chữ “đạo đức”: cần, kiệm, liêm, chính, chí công vô tư, hết lòng phục vụ nhân dân."},{"t":"...đến tư tưởng, đạo đức, phong cách. Ngày 15 tháng 5 năm 2016, Bộ Chính trị khóa XII, do Tổng Bí thư Nguyễn Phú Trọng ký ban hành, ra Chỉ thị số 05-CT/TW về đẩy mạnh học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh. So với hai chỉ thị trước, phạm vi được mở rộng thêm một chữ quan trọng: tư tưởng. Nội dung học tập giờ đây bao gồm cả tư tưởng của Người về độc lập dân tộc gắn liền với chủ nghĩa xã hội, về đại đoàn kết toàn dân tộc, về xây dựng Đảng và Nhà nước của dân, do dân, vì dân; học đạo đức cách mạng; và học cả phong cách — cách Người tư duy, làm việc, diễn đạt, ứng xử, sinh hoạt hằng ngày, từ tác phong dân chủ, sâu sát cơ sở, nói đi đôi với làm, đến lối sống giản dị, gần dân. Chỉ thị đặc biệt nhấn mạnh trách nhiệm nêu gương, trước hết là của cán bộ lãnh đạo, người đứng đầu mỗi cơ quan, đơn vị."},{"t":"Đảng ta là một Đảng cầm quyền. Mỗi đảng viên và cán bộ phải thật sự thấm nhuần đạo đức cách mạng, thật sự cần kiệm liêm chính, chí công vô tư. Phải giữ gìn Đảng ta thật trong sạch, phải xứng đáng là người lãnh đạo, là người đầy tớ thật trung thành của nhân dân. — Chủ tịch Hồ Chí Minh"},{"t":"Kết luận nối dài một chỉ thị. Năm 2021, khi chặng đường thực hiện Chỉ thị 05-CT/TW đã đi qua trọn một nhiệm kỳ Đại hội Đảng, Bộ Chính trị khóa XIII không ban hành một chỉ thị hoàn toàn mới, mà ra Kết luận số 01-KL/TW, ngày 18 tháng 5 năm 2021, về tiếp tục thực hiện Chỉ thị 05-CT/TW. Cách làm này cho thấy một điểm khác so với hai giai đoạn trước: nội dung tư tưởng, đạo đức, phong cách Hồ Chí Minh không cần thay bằng một cách gọi mới sau mỗi kỳ đại hội, mà tiếp tục được bồi đắp, cụ thể hóa cho phù hợp với yêu cầu công tác xây dựng, chỉnh đốn Đảng trong giai đoạn mới."},{"t":"Bạn có biết? Chỉ thị 05-CT/TW là văn bản do đích thân Tổng Bí thư Nguyễn Phú Trọng ký ban hành ngày 15 tháng 5 năm 2016 — chưa đầy một tháng rưỡi sau khi Đại hội đại biểu toàn quốc lần thứ XII của Đảng bế mạc."},{"t":"“Làm theo” mới là điều khó. Chủ tịch Hồ Chí Minh luôn đòi hỏi nói phải đi đôi với làm, đã hứa thì phải giữ. Vì vậy, điểm mấu chốt của cả quá trình học tập này không nằm ở việc thuộc lòng một tư tưởng hay nhắc lại một câu nói, mà ở hai chữ “làm theo”: mỗi tổ chức, mỗi cá nhân tự đăng ký những việc làm cụ thể, có thể kiểm tra được, gắn với công việc, vị trí của mình. Trong thực tế thực hiện Chỉ thị 05-CT/TW, nhiều địa phương đã đưa ra những cách làm riêng để việc “làm theo” trở nên thiết thực và dễ đo lường hơn, thay vì dừng lại ở những buổi học nghị quyết trên hội trường."},{"t":"Một cách làm ở Ninh Bình. Tại Ninh Bình, việc học tập và làm theo Bác được cụ thể hóa bằng những phong trào có tên gọi và cách làm rõ ràng, như “Ngày thứ Hai nêu gương” hay “Gương sáng làm theo Bác mỗi tuần”, được nhiều chi bộ, đảng bộ cơ sở chủ động đưa vào kế hoạch công tác hằng năm, kèm theo các buổi kể chuyện, tọa đàm, biểu dương những tập thể, cá nhân làm tốt. Theo tổng kết của địa phương, phần lớn cán bộ, đảng viên — trên chín mươi phần trăm — hằng năm đăng ký nội dung “làm theo” cụ thể, gắn với nhiệm vụ được giao. Đó là một trong rất nhiều mô hình tương tự đang được duy trì ở các tỉnh, thành trong cả nước, mỗi nơi một cách làm, nhưng cùng chung một tinh thần: biến một tư tưởng lớn thành những việc làm nhỏ, đều đặn mỗi ngày."},{"t":"Bạn có biết? Phải hơn hai mươi năm sau khi Chủ tịch Hồ Chí Minh qua đời, tư tưởng Hồ Chí Minh mới chính thức được Đại hội đại biểu toàn quốc lần thứ VII của Đảng (1991) xác định là nền tảng tư tưởng, cùng với chủ nghĩa Mác – Lênin."},{"t":"Một tinh thần, nhiều hình thức thể hiện. Không chỉ trong sinh hoạt đảng, tinh thần học tập và làm theo Bác còn được nhiều cơ quan, đoàn thể, trường học, doanh nghiệp diễn giải theo cách riêng: có nơi tổ chức hội thi kể chuyện về Bác, có nơi phát động phong trào tiết kiệm, chống lãng phí gắn với lời dạy “cần, kiệm, liêm, chính”, có nơi lồng nội dung này vào các buổi sinh hoạt chuyên môn, sinh hoạt chi đoàn. Với lực lượng vũ trang, việc học và làm theo phong cách của Người thường gắn liền với các phong trào thi đua sẵn có, như rèn luyện kỷ luật, gần dân, giúp dân. Sự đa dạng trong cách vận dụng ấy cũng chính là điều Chỉ thị 05-CT/TW mong muốn: không rập khuôn một hình thức chung, mà để mỗi ngành, mỗi địa phương tìm ra cách làm phù hợp nhất với đặc thù công việc của mình."},{"t":"Bạn có biết? Chỉ thị 05-CT/TW xác định việc học tập và làm theo Bác phải gắn với thực hiện nhiệm vụ chính trị của từng địa phương, đơn vị, thay vì tách rời thành một hoạt động độc lập, hình thức, tách khỏi công việc chuyên môn hằng ngày."},{"t":"Một cuộc vận động, một câu trong Di chúc. Câu nói được trích trong bảng này — về một Đảng cầm quyền, về đạo đức cách mạng, về việc giữ Đảng thật trong sạch — nằm trong bản Di chúc Người để lại, được công bố tại lễ truy điệu ngày 9 tháng 9 năm 1969. Nửa thế kỷ sau, những dòng ấy vẫn được nhắc lại như một lời nhắc nhở thường trực mỗi khi Đảng bàn về công tác xây dựng, chỉnh đốn Đảng, về trách nhiệm nêu gương của cán bộ, đảng viên — chính là điều mà các Chỉ thị 06, Chỉ thị 03, Chỉ thị 05 nối tiếp nhau tìm cách cụ thể hóa suốt mấy chục năm qua."},{"t":"Dấu tích hôm nay. Hơn nửa thế kỷ sau khi Người qua đời, việc học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh vẫn được duy trì như một nội dung sinh hoạt thường xuyên trong các tổ chức đảng, cơ quan, trường học, doanh nghiệp khắp cả nước, mỗi năm đều có sơ kết, biểu dương những tập thể, cá nhân tiêu biểu. Tấm bảng bạn đang xem, đặt trong gian cuối của bảo tàng số này, chính là một lời nhắc: di sản của Chủ tịch Hồ Chí Minh không chỉ nằm trong sách vở hay ở Ba Đình, mà còn tiếp tục sống trong những việc làm cụ thể, bình dị của rất nhiều người, ở rất nhiều nơi, ngay lúc này."}],"so_chu":1524},{"i":10,"tieu_de_bang":"Lăng Chủ tịch Hồ Chí Minh","tieu_de":"Kiến trúc Lăng: ba lớp đá hoa cương và những vật liệu từ mọi miền đất nước","sapo":"Cao 21,6 mét, không cầu kỳ, không phô trương, Lăng Chủ tịch Hồ Chí Minh là một trong những công trình kiến trúc trang nghiêm bậc nhất của đất nước. Đá, gỗ quý, cát và cây xanh được đưa về từ khắp các miền để dựng nên công trình này, như một cách thể hiện tấm lòng của cả dân tộc hướng về Người. Phía sau vẻ tĩnh lặng ấy còn là một công việc thầm lặng, được duy trì đều đặn suốt nửa thế kỷ, để giữ cho Người luôn như đang yên giấc.","bia":{"src":"textures/bai/G17_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một buổi sáng cuối tháng Tám","text":"Sáng 29 tháng 8 năm 1975, giữa những ngày cả nước còn ngập tràn không khí của năm đầu tiên sau ngày thống nhất, Lăng Chủ tịch Hồ Chí Minh chính thức được khánh thành tại Quảng trường Ba Đình — đúng trên nền lễ đài gỗ giản dị nơi ba mươi năm trước Người từng đọc Tuyên ngôn Độc lập (xem chuyên đề Quảng trường Ba Đình). Từ hôm ấy, hàng triệu người Việt Nam, từ khắp mọi miền đất nước, cùng rất nhiều bạn bè quốc tế, đã nối nhau xếp hàng, đi qua phòng thi hài Người trong im lặng. Không ít người trong dòng người ấy là những cựu chiến binh, những người từng nghe tiếng Bác qua đài, qua thư, mà chưa một lần được gặp Người khi còn sống.","doc":1},{"loai":"doan","tieu_de":"Từ ý định đến ngày khởi công","text":"Ý định xây dựng một nơi an nghỉ trang nghiêm cho Chủ tịch Hồ Chí Minh được đặt ra ngay sau khi Người qua đời năm 1969, nhưng phải đợi đến khi đất nước hoàn toàn thống nhất mới có thể khởi công. Ngày 2 tháng 9 năm 1973, đúng dịp kỷ niệm Quốc khánh, công trình chính thức được khởi công. Suốt gần hai năm xây dựng, hàng vạn cán bộ, chiến sĩ, công nhân, kỹ sư đã tham gia thi công, trong đó có sự hỗ trợ về kỹ thuật, vật tư của các chuyên gia Liên Xô — quốc gia khi đó cũng đang gìn giữ thi hài lãnh tụ Vladimir Lenin theo một kỹ thuật tương tự. Công trình hoàn thành đúng vào dịp kỷ niệm 30 năm Cách mạng Tháng Tám và Quốc khánh 1975, khép lại sáu năm kể từ ngày Người ra đi (xem chuyên đề Sáu năm gìn giữ thi hài Bác giữa chiến tranh).","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_hanoi_vietnam_ba_dinh_square_and_ho_chi_minh_mau.jpg","chu_thich":"Quảng trường Ba Đình và Lăng Chủ tịch Hồ Chí Minh (ảnh chụp năm 2008).","credit":"Ảnh: Vyacheslav Argenberg · CC BY 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ba lớp kiến trúc","text":"Công trình cao 21,6 mét, được thiết kế thành ba lớp rõ rệt. Lớp dưới cùng là phần bệ Lăng, với hai khán đài bậc cấp vươn ra hai bên — nơi các đoàn diễu binh, diễu hành từng đi qua trong những dịp lễ lớn của đất nước. Lớp giữa là khối kiến trúc trung tâm, nơi đặt phòng thi hài, được bao quanh bởi hàng cột vuông ốp đá hoa cương màu xám, tạo cảm giác vững chãi mà thanh thoát. Lớp trên cùng là phần mái giật cấp, cách điệu theo hình dáng những mái đình, mái chùa truyền thống của làng quê Việt Nam. Trên diềm mặt chính, dòng chữ “CHỦ TỊCH HỒ CHÍ MINH” được ghép bằng đá ngọc màu đỏ, lấy từ Cao Bằng — mảnh đất Người đã trở về sau ba mươi năm bôn ba, qua cột mốc 108 ngày 28 tháng 1 năm 1941.","doc":3},{"loai":"anh","src":"textures/bang_w/G17_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lăng Chủ tịch Hồ Chí Minh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vật liệu từ khắp mọi miền","text":"Không chỉ đá ngọc đỏ từ Cao Bằng, nhiều loại vật liệu khác của công trình cũng được đưa về từ những vùng đất khác nhau trong cả nước: đá hoa cương ốp mặt ngoài, đá hoa cương xám, đen, đỏ mài bóng bên trong, gỗ quý dùng cho nội thất, cùng nhiều loại cây được chọn trồng quanh Lăng. Cách làm ấy không đơn thuần là vấn đề kỹ thuật xây dựng, mà mang một ý nghĩa tượng trưng: mỗi phiến đá, mỗi cây gỗ là một phần tấm lòng của một vùng quê, một địa phương, được gửi về góp sức dựng nên nơi an nghỉ cho Người. Phần thiết kế do các kiến trúc sư Việt Nam và Liên Xô cùng thực hiện, kết hợp giữa kỹ thuật xây dựng hiện đại với những yếu tố mang đậm bản sắc dân tộc, để công trình vừa trang nghiêm theo chuẩn mực một lăng mộ hiện đại, vừa gần gũi với truyền thống kiến trúc Việt Nam.","doc":4},{"loai":"ban_co_biet","text":"Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh — đơn vị trực tiếp quản lý, bảo vệ Lăng và tổ chức đón khách vào viếng — được thành lập ngay trong những năm xây dựng công trình, và duy trì hoạt động thường trực cho đến hôm nay.","nguon_ten":"Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","doc":5},{"loai":"doan","tieu_de":"Một công trình được cả nước góp sức","text":"Trong hai năm thi công, không chỉ có bộ đội, kỹ sư, công nhân trực tiếp làm việc tại công trường mà nhiều địa phương trên cả nước cũng tham gia đóng góp theo cách riêng của mình: nơi gửi về loại đá quý, nơi gửi gỗ tốt, có nơi cử cả đoàn nghệ nhân lành nghề ra Hà Nội hỗ trợ những công đoạn đòi hỏi kỹ thuật cao như chạm khắc, ốp đá. Cách huy động sức người, sức của từ khắp mọi miền cho một công trình duy nhất từng được ví như một cuộc vận động toàn dân thu nhỏ, phản ánh đúng tình cảm của cả nước dành cho vị lãnh tụ vừa qua đời, giữa lúc cuộc kháng chiến chống Mỹ, cứu nước còn chưa kết thúc trọn vẹn ở một số nơi.","doc":6},{"loai":"doan","tieu_de":"Từ Lăng Lenin đến Lăng Chủ tịch Hồ Chí Minh","text":"Trước khi bắt tay xây dựng Lăng, một đoàn cán bộ Việt Nam đã sang Moskva tìm hiểu kinh nghiệm bảo quản, xây dựng nơi an nghỉ của lãnh tụ Vladimir Lenin tại Quảng trường Đỏ — công trình đã tồn tại từ những năm 1920. Kinh nghiệm ấy được các chuyên gia Liên Xô truyền lại và điều chỉnh cho phù hợp với khí hậu nhiệt đới của Việt Nam, khác hẳn mùa đông lạnh giá của nước Nga. Đây cũng là lý do vì sao công tác bảo quản thi hài Người đến nay vẫn cần sự phối hợp thường xuyên giữa các chuyên gia y tế hai nước, thay vì chỉ dựa vào đội ngũ trong nước.","doc":7},{"loai":"anh","src":"textures/bang_w/G17_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lăng Chủ tịch Hồ Chí Minh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hàng tre và bảy mươi chín cây vạn tuế","text":"Bao quanh Lăng là một không gian cây xanh được chăm chút kỹ lưỡng. Hai bên đường vào là những hàng tre xanh mát — loài cây vốn gắn liền với hình ảnh làng quê Việt Nam, cũng là loài cây Người từng nhắc đến trong nhiều bài viết, bài nói về đức tính giản dị, kiên cường. Cùng với tre, chung quanh Lăng còn trồng bảy mươi chín cây vạn tuế, con số được chọn để gợi nhớ bảy mươi chín mùa xuân cuộc đời Người, tính theo năm sinh 1890 và năm mất 1969. Vào mùa hoa, những loài hoa quen thuộc của ba miền đất nước cũng được trồng xen trong khuôn viên, khiến khung cảnh quanh Lăng không chỉ trang nghiêm mà còn ấm áp như một khu vườn quê.","doc":8},{"loai":"anh","src":"textures/ht/ht_anh_guards_of_the_ho_chi_minh_mausoleum.jpg","chu_thich":"Tiêu binh danh dự trước Lăng Chủ tịch Hồ Chí Minh (ảnh chụp năm 2018).","credit":"Ảnh: Christophe95 · CC BY-SA 4.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Không gian bên trong","text":"Bên trong Lăng, thi hài Chủ tịch Hồ Chí Minh được đặt trong phòng trung tâm, giữa không gian tĩnh lặng, ánh sáng dịu, nhiệt độ và độ ẩm được kiểm soát nghiêm ngặt. Khách vào viếng đi theo một lối vòng quanh cố định, không dừng lại, giữ im lặng tuyệt đối — một nghi thức đã trở thành thói quen quen thuộc với hàng triệu người Việt Nam. Vào những ngày lễ lớn, dòng người xếp hàng vào viếng có thể kéo dài hàng cây số từ sáng sớm. Không ít nguyên thủ quốc gia, người đứng đầu chính phủ các nước khi thăm Việt Nam cũng dành thời gian đến đặt vòng hoa, vào Lăng viếng Người, coi đó như một nghi lễ ngoại giao trang trọng. Theo thống kê nhiều năm của đơn vị quản lý, mỗi năm có hàng triệu lượt người vào Lăng viếng Chủ tịch Hồ Chí Minh, trong đó phần lớn là các đoàn từ những tỉnh, thành xa Hà Nội, tổ chức thành chuyến đi về nguồn cho cán bộ, đoàn viên, học sinh.","doc":9},{"loai":"ban_co_biet","text":"Mỗi năm, Lăng Chủ tịch Hồ Chí Minh tạm ngừng đón khách trong khoảng hai tháng, thường vào cuối năm, để phục vụ công tác tu bổ định kỳ — quãng thời gian đội ngũ y tế Việt Nam phối hợp cùng các chuyên gia Liên bang Nga thực hiện việc kiểm tra, bảo dưỡng.","nguon_ten":"Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","doc":10},{"loai":"anh","src":"textures/bang_w/G17_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lăng Chủ tịch Hồ Chí Minh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Công việc thầm lặng suốt nửa thế kỷ","text":"Việc gìn giữ thi hài Chủ tịch Hồ Chí Minh là một công việc khoa học đặc biệt, đòi hỏi kỹ thuật nghiêm ngặt, được duy trì liên tục suốt nhiều thập kỷ qua, với sự phối hợp giữa các chuyên gia y tế Việt Nam và Liên bang Nga — quốc gia kế thừa kỹ thuật gìn giữ thi hài mà Liên Xô từng chuyển giao cho Việt Nam từ những năm chiến tranh. Đây là công việc ít được nhắc đến trước công chúng, nhưng lại là điều kiện để hình ảnh Người, hơn nửa thế kỷ sau ngày mất, vẫn hiện diện trước hàng triệu người đến viếng mỗi năm.","doc":11},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, Lăng Chủ tịch Hồ Chí Minh cùng Quảng trường Ba Đình là nơi diễn ra những nghi lễ trọng thể nhất của đất nước: lễ thượng cờ mỗi sáng sớm, lễ hạ cờ mỗi chiều tà, các cuộc mít tinh, diễu binh nhân những ngày kỷ niệm lớn. Đội tiêu binh danh dự đứng gác trước Lăng, thay phiên đổi gác đều đặn suốt ngày đêm, đã trở thành một hình ảnh quen thuộc với bất kỳ ai từng đến Ba Đình (xem chuyên đề Tiêu binh trước Lăng). Với nhiều thế hệ người Việt Nam, được một lần đứng trước Lăng, vào viếng Người, vẫn là một trong những chuyến đi có ý nghĩa nhất trong đời.","doc":12}],"nguon":["Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","Hồ Chí Minh – Biên niên tiểu sử, tập 10, NXB Chính trị quốc gia"],"doc":[{"t":"Kiến trúc Lăng: ba lớp đá hoa cương và những vật liệu từ mọi miền đất nước. Cao 21,6 mét, không cầu kỳ, không phô trương, Lăng Chủ tịch Hồ Chí Minh là một trong những công trình kiến trúc trang nghiêm bậc nhất của đất nước. Đá, gỗ quý, cát và cây xanh được đưa về từ khắp các miền để dựng nên công trình này, như một cách thể hiện tấm lòng của cả dân tộc hướng về Người. Phía sau vẻ tĩnh lặng ấy còn là một công việc thầm lặng, được duy trì đều đặn suốt nửa thế kỷ, để giữ cho Người luôn như đang yên giấc."},{"t":"Một buổi sáng cuối tháng Tám. Sáng 29 tháng 8 năm 1975, giữa những ngày cả nước còn ngập tràn không khí của năm đầu tiên sau ngày thống nhất, Lăng Chủ tịch Hồ Chí Minh chính thức được khánh thành tại Quảng trường Ba Đình — đúng trên nền lễ đài gỗ giản dị nơi ba mươi năm trước Người từng đọc Tuyên ngôn Độc lập (xem chuyên đề Quảng trường Ba Đình). Từ hôm ấy, hàng triệu người Việt Nam, từ khắp mọi miền đất nước, cùng rất nhiều bạn bè quốc tế, đã nối nhau xếp hàng, đi qua phòng thi hài Người trong im lặng. Không ít người trong dòng người ấy là những cựu chiến binh, những người từng nghe tiếng Bác qua đài, qua thư, mà chưa một lần được gặp Người khi còn sống."},{"t":"Từ ý định đến ngày khởi công. Ý định xây dựng một nơi an nghỉ trang nghiêm cho Chủ tịch Hồ Chí Minh được đặt ra ngay sau khi Người qua đời năm 1969, nhưng phải đợi đến khi đất nước hoàn toàn thống nhất mới có thể khởi công. Ngày 2 tháng 9 năm 1973, đúng dịp kỷ niệm Quốc khánh, công trình chính thức được khởi công. Suốt gần hai năm xây dựng, hàng vạn cán bộ, chiến sĩ, công nhân, kỹ sư đã tham gia thi công, trong đó có sự hỗ trợ về kỹ thuật, vật tư của các chuyên gia Liên Xô — quốc gia khi đó cũng đang gìn giữ thi hài lãnh tụ Vladimir Lenin theo một kỹ thuật tương tự. Công trình hoàn thành đúng vào dịp kỷ niệm 30 năm Cách mạng Tháng Tám và Quốc khánh 1975, khép lại sáu năm kể từ ngày Người ra đi (xem chuyên đề Sáu năm gìn giữ thi hài Bác giữa chiến tranh)."},{"t":"Ba lớp kiến trúc. Công trình cao 21,6 mét, được thiết kế thành ba lớp rõ rệt. Lớp dưới cùng là phần bệ Lăng, với hai khán đài bậc cấp vươn ra hai bên — nơi các đoàn diễu binh, diễu hành từng đi qua trong những dịp lễ lớn của đất nước. Lớp giữa là khối kiến trúc trung tâm, nơi đặt phòng thi hài, được bao quanh bởi hàng cột vuông ốp đá hoa cương màu xám, tạo cảm giác vững chãi mà thanh thoát. Lớp trên cùng là phần mái giật cấp, cách điệu theo hình dáng những mái đình, mái chùa truyền thống của làng quê Việt Nam. Trên diềm mặt chính, dòng chữ “CHỦ TỊCH HỒ CHÍ MINH” được ghép bằng đá ngọc màu đỏ, lấy từ Cao Bằng — mảnh đất Người đã trở về sau ba mươi năm bôn ba, qua cột mốc 108 ngày 28 tháng 1 năm 1941."},{"t":"Vật liệu từ khắp mọi miền. Không chỉ đá ngọc đỏ từ Cao Bằng, nhiều loại vật liệu khác của công trình cũng được đưa về từ những vùng đất khác nhau trong cả nước: đá hoa cương ốp mặt ngoài, đá hoa cương xám, đen, đỏ mài bóng bên trong, gỗ quý dùng cho nội thất, cùng nhiều loại cây được chọn trồng quanh Lăng. Cách làm ấy không đơn thuần là vấn đề kỹ thuật xây dựng, mà mang một ý nghĩa tượng trưng: mỗi phiến đá, mỗi cây gỗ là một phần tấm lòng của một vùng quê, một địa phương, được gửi về góp sức dựng nên nơi an nghỉ cho Người. Phần thiết kế do các kiến trúc sư Việt Nam và Liên Xô cùng thực hiện, kết hợp giữa kỹ thuật xây dựng hiện đại với những yếu tố mang đậm bản sắc dân tộc, để công trình vừa trang nghiêm theo chuẩn mực một lăng mộ hiện đại, vừa gần gũi với truyền thống kiến trúc Việt Nam."},{"t":"Bạn có biết? Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh — đơn vị trực tiếp quản lý, bảo vệ Lăng và tổ chức đón khách vào viếng — được thành lập ngay trong những năm xây dựng công trình, và duy trì hoạt động thường trực cho đến hôm nay."},{"t":"Một công trình được cả nước góp sức. Trong hai năm thi công, không chỉ có bộ đội, kỹ sư, công nhân trực tiếp làm việc tại công trường mà nhiều địa phương trên cả nước cũng tham gia đóng góp theo cách riêng của mình: nơi gửi về loại đá quý, nơi gửi gỗ tốt, có nơi cử cả đoàn nghệ nhân lành nghề ra Hà Nội hỗ trợ những công đoạn đòi hỏi kỹ thuật cao như chạm khắc, ốp đá. Cách huy động sức người, sức của từ khắp mọi miền cho một công trình duy nhất từng được ví như một cuộc vận động toàn dân thu nhỏ, phản ánh đúng tình cảm của cả nước dành cho vị lãnh tụ vừa qua đời, giữa lúc cuộc kháng chiến chống Mỹ, cứu nước còn chưa kết thúc trọn vẹn ở một số nơi."},{"t":"Từ Lăng Lenin đến Lăng Chủ tịch Hồ Chí Minh. Trước khi bắt tay xây dựng Lăng, một đoàn cán bộ Việt Nam đã sang Moskva tìm hiểu kinh nghiệm bảo quản, xây dựng nơi an nghỉ của lãnh tụ Vladimir Lenin tại Quảng trường Đỏ — công trình đã tồn tại từ những năm 1920. Kinh nghiệm ấy được các chuyên gia Liên Xô truyền lại và điều chỉnh cho phù hợp với khí hậu nhiệt đới của Việt Nam, khác hẳn mùa đông lạnh giá của nước Nga. Đây cũng là lý do vì sao công tác bảo quản thi hài Người đến nay vẫn cần sự phối hợp thường xuyên giữa các chuyên gia y tế hai nước, thay vì chỉ dựa vào đội ngũ trong nước."},{"t":"Hàng tre và bảy mươi chín cây vạn tuế. Bao quanh Lăng là một không gian cây xanh được chăm chút kỹ lưỡng. Hai bên đường vào là những hàng tre xanh mát — loài cây vốn gắn liền với hình ảnh làng quê Việt Nam, cũng là loài cây Người từng nhắc đến trong nhiều bài viết, bài nói về đức tính giản dị, kiên cường. Cùng với tre, chung quanh Lăng còn trồng bảy mươi chín cây vạn tuế, con số được chọn để gợi nhớ bảy mươi chín mùa xuân cuộc đời Người, tính theo năm sinh 1890 và năm mất 1969. Vào mùa hoa, những loài hoa quen thuộc của ba miền đất nước cũng được trồng xen trong khuôn viên, khiến khung cảnh quanh Lăng không chỉ trang nghiêm mà còn ấm áp như một khu vườn quê."},{"t":"Không gian bên trong. Bên trong Lăng, thi hài Chủ tịch Hồ Chí Minh được đặt trong phòng trung tâm, giữa không gian tĩnh lặng, ánh sáng dịu, nhiệt độ và độ ẩm được kiểm soát nghiêm ngặt. Khách vào viếng đi theo một lối vòng quanh cố định, không dừng lại, giữ im lặng tuyệt đối — một nghi thức đã trở thành thói quen quen thuộc với hàng triệu người Việt Nam. Vào những ngày lễ lớn, dòng người xếp hàng vào viếng có thể kéo dài hàng cây số từ sáng sớm. Không ít nguyên thủ quốc gia, người đứng đầu chính phủ các nước khi thăm Việt Nam cũng dành thời gian đến đặt vòng hoa, vào Lăng viếng Người, coi đó như một nghi lễ ngoại giao trang trọng. Theo thống kê nhiều năm của đơn vị quản lý, mỗi năm có hàng triệu lượt người vào Lăng viếng Chủ tịch Hồ Chí Minh, trong đó phần lớn là các đoàn từ những tỉnh, thành xa Hà Nội, tổ chức thành chuyến đi về nguồn cho cán bộ, đoàn viên, học sinh."},{"t":"Bạn có biết? Mỗi năm, Lăng Chủ tịch Hồ Chí Minh tạm ngừng đón khách trong khoảng hai tháng, thường vào cuối năm, để phục vụ công tác tu bổ định kỳ — quãng thời gian đội ngũ y tế Việt Nam phối hợp cùng các chuyên gia Liên bang Nga thực hiện việc kiểm tra, bảo dưỡng."},{"t":"Công việc thầm lặng suốt nửa thế kỷ. Việc gìn giữ thi hài Chủ tịch Hồ Chí Minh là một công việc khoa học đặc biệt, đòi hỏi kỹ thuật nghiêm ngặt, được duy trì liên tục suốt nhiều thập kỷ qua, với sự phối hợp giữa các chuyên gia y tế Việt Nam và Liên bang Nga — quốc gia kế thừa kỹ thuật gìn giữ thi hài mà Liên Xô từng chuyển giao cho Việt Nam từ những năm chiến tranh. Đây là công việc ít được nhắc đến trước công chúng, nhưng lại là điều kiện để hình ảnh Người, hơn nửa thế kỷ sau ngày mất, vẫn hiện diện trước hàng triệu người đến viếng mỗi năm."},{"t":"Dấu tích hôm nay. Ngày nay, Lăng Chủ tịch Hồ Chí Minh cùng Quảng trường Ba Đình là nơi diễn ra những nghi lễ trọng thể nhất của đất nước: lễ thượng cờ mỗi sáng sớm, lễ hạ cờ mỗi chiều tà, các cuộc mít tinh, diễu binh nhân những ngày kỷ niệm lớn. Đội tiêu binh danh dự đứng gác trước Lăng, thay phiên đổi gác đều đặn suốt ngày đêm, đã trở thành một hình ảnh quen thuộc với bất kỳ ai từng đến Ba Đình (xem chuyên đề Tiêu binh trước Lăng). Với nhiều thế hệ người Việt Nam, được một lần đứng trước Lăng, vào viếng Người, vẫn là một trong những chuyến đi có ý nghĩa nhất trong đời."}],"so_chu":1630},{"i":11,"tieu_de_bang":"Quảng trường Ba Đình","tieu_de":"Quảng trường Ba Đình: nơi đất nước làm lễ trong những ngày trọng đại","sapo":"Không chỉ là nơi khai sinh nước Việt Nam Dân chủ Cộng hòa, Quảng trường Ba Đình còn chứng kiến những cuộc mít tinh, diễu binh và những buổi lễ trọng thể nhất của đất nước suốt tám mươi năm qua. Một lễ đài dựng tạm trong vài ngày của năm 1945, về sau lại trở thành nơi đặt một trong những công trình vĩnh cửu nhất của dân tộc.","bia":{"src":"textures/bai/G17_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Buổi trưa ngày 2 tháng 9","text":"Trưa ngày 2 tháng 9 năm 1945, trên một lễ đài gỗ dựng tạm giữa khu vườn hoa khi ấy còn chưa mang tên Ba Đình, trước hàng vạn người dân Hà Nội đứng chật kín, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Lễ đài hôm ấy chỉ được dựng trong vài ngày, đơn sơ đến mức nhiều người sau này khó hình dung nó từng đứng ở đúng vị trí nơi một công trình bằng đá hoa cương đồ sộ mọc lên ba mươi năm sau (xem chuyên đề Lăng Chủ tịch Hồ Chí Minh). Nhưng chính buổi trưa hôm ấy đã biến một quảng trường vốn chỉ quen thuộc với người dân quanh vùng thành một địa danh mà sau này bất kỳ người Việt Nam nào cũng biết tên.","doc":1},{"loai":"trich","text":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc.","nguoi":"Chủ tịch Hồ Chí Minh","nguon_ten":"Tuyên ngôn Độc lập, 2/9/1945","doc":2},{"loai":"doan","tieu_de":"Từ vườn hoa thời Pháp đến quảng trường của một nước độc lập","text":"Trước năm 1945, khu vực này được người Pháp quy hoạch thành một vườn hoa nằm trước Phủ Toàn quyền Đông Dương, quen gọi theo tên một giám mục Pháp. Đây là một trong những không gian công cộng lớn hiếm hoi ở Hà Nội thời thuộc địa. Sau Cách mạng Tháng Tám, khu vườn được đổi tên thành Quảng trường Ba Đình, theo tên gọi vùng đất Ba Đình ở Thanh Hóa — nơi từng nổ ra cuộc khởi nghĩa chống Pháp cuối thế kỷ 19 của các sĩ phu yêu nước, trong phong trào Cần Vương. Từ một địa danh gắn với phong trào chống Pháp, Ba Đình trở thành tên gọi của quảng trường trung tâm chính trị của nước Việt Nam mới.","doc":3},{"loai":"doan","tieu_de":"Một khoảng đất chứng kiến hai chế độ","text":"Trước khi trở thành trung tâm chính trị của một nước độc lập, khu vực quanh Ba Đình từng là nơi đặt các dinh thự, công sở của chính quyền thuộc địa Pháp: Phủ Toàn quyền Đông Dương, các trại lính, các biệt thự dành cho quan chức cao cấp. Việc chọn chính khu vực này để tổ chức lễ Tuyên ngôn Độc lập năm 1945, thay vì một địa điểm nào khác trong thành phố, vì vậy còn mang một ý nghĩa biểu tượng: nơi từng là trung tâm quyền lực của chế độ thực dân, nay trở thành nơi công bố nền độc lập của một dân tộc vừa tự giải phóng mình.","doc":4},{"loai":"anh","src":"textures/bang_w/G17_11_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình”, nhìn từ xa."},{"loai":"doan","tieu_de":"Bố cục của một không gian nghi lễ","text":"Quảng trường Ba Đình ngày nay trải rộng trước Lăng Chủ tịch Hồ Chí Minh, gồm nhiều ô cỏ vuông xanh mướt, xen giữa là hệ thống đường dạo lát đá, đủ rộng cho hàng nghìn người xếp hàng cùng lúc. Chính giữa quảng trường là cột cờ cao, nơi lá quốc kỳ được kéo lên mỗi sáng và hạ xuống mỗi chiều trong nghi thức đã trở thành một phần đời sống của Thủ đô. Bố cục rộng, thoáng, không vướng cây cao che khuất tầm nhìn, được thiết kế có chủ đích để phục vụ những cuộc mít tinh, diễu binh, diễu hành quy mô lớn — nơi các khối quần chúng, các đơn vị quân đội có thể di chuyển thành hàng lối chỉnh tề trước lễ đài.","doc":5},{"loai":"ban_co_biet","text":"Tên gọi Ba Đình không có sẵn ở Hà Nội, mà được đặt theo địa danh Ba Đình ở huyện Nga Sơn, tỉnh Thanh Hóa, nơi diễn ra cuộc khởi nghĩa Ba Đình chống thực dân Pháp những năm 1886–1887, một trong những cuộc khởi nghĩa tiêu biểu của phong trào Cần Vương.","nguon_ten":"Cổng thông tin điện tử thành phố Hà Nội","doc":6},{"loai":"anh","src":"textures/ht/ht_anh_quang_truong_ba_dinh_ve_dem.jpg","chu_thich":"Quảng trường Ba Đình về đêm (ảnh chụp năm 2010).","credit":"Ảnh: Nguyễn Thanh Quang · CC BY-SA 3.0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những ngày lịch sử nối tiếp nhau","text":"Sau ngày 2 tháng 9 năm 1945, Ba Đình tiếp tục là nơi chứng kiến nhiều thời khắc quan trọng của đất nước. Sáng 1 tháng 1 năm 1955, hàng vạn người dân Hà Nội tề tựu tại quảng trường dự lễ mừng Trung ương Đảng, Chính phủ và Chủ tịch Hồ Chí Minh trở về Thủ đô, sau chín năm kháng chiến chống thực dân Pháp và tiếp quản Hà Nội ngày 10 tháng 10 năm 1954. Ngày 9 tháng 9 năm 1969, lễ truy điệu Chủ tịch Hồ Chí Minh được tổ chức trọng thể ngay tại quảng trường này, giữa những dòng người không cầm được nước mắt. Những thập niên sau đó, Ba Đình tiếp tục là nơi diễn ra các lễ diễu binh, diễu hành lớn: dịp Đại lễ kỷ niệm 1000 năm Thăng Long – Hà Nội ngày 10 tháng 10 năm 2010, lễ kỷ niệm 70 năm Cách mạng Tháng Tám và Quốc khánh ngày 2 tháng 9 năm 2015, và lễ kỷ niệm 80 năm vào ngày 2 tháng 9 năm 2025.","doc":7},{"loai":"anh","src":"textures/bang_w/G17_11_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Nơi lễ đài tạm nhường chỗ cho công trình vĩnh cửu","text":"Suốt gần ba mươi năm sau ngày Tuyên ngôn Độc lập, lễ đài trước Ba Đình vẫn chỉ là một kết cấu dựng tạm, được dùng đi dùng lại, sửa chữa qua từng lần mít tinh lớn. Phải đến khi Chủ tịch Hồ Chí Minh qua đời năm 1969 và đất nước thống nhất năm 1975, một công trình vĩnh cửu — Lăng Chủ tịch Hồ Chí Minh — mới được xây dựng đúng trên nền lễ đài cũ ấy. Từ đó, lễ đài phía trước Lăng trở thành nơi lãnh đạo Đảng, Nhà nước đứng dự các nghi lễ lớn của đất nước, còn quảng trường phía trước vẫn giữ nguyên vai trò không gian tập hợp quần chúng như suốt tám mươi năm qua.","doc":8},{"loai":"ban_co_biet","text":"Quảng trường Ba Đình hiện có diện tích khoảng hơn ba mươi nghìn mét vuông, đủ chỗ cho hàng vạn người cùng tham dự trong những dịp mít tinh, diễu binh lớn nhất của đất nước.","nguon_ten":"Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","doc":9},{"loai":"doan","tieu_de":"Một quảng trường luôn đông người","text":"Không chỉ vào những dịp lễ lớn, Quảng trường Ba Đình gần như lúc nào cũng có người qua lại: sáng sớm là những người tập thể dục quanh khu vực lân cận, ban ngày là dòng khách du lịch trong nước, quốc tế xếp hàng vào Lăng hoặc đứng chụp ảnh bên cột cờ, buổi tối là những gia đình, đôi bạn trẻ ra hóng mát dưới ánh đèn. Vào những dịp đặc biệt như Tết Nguyên đán hay các ngày lễ lớn của đất nước, khu vực quanh quảng trường còn được trang trí thêm hoa, cờ, tạo nên một không khí vừa trang trọng vừa rộn ràng, thu hút hàng vạn lượt người đến chụp ảnh mỗi ngày.","doc":10},{"loai":"ban_co_biet","text":"Vào các dịp diễu binh, diễu hành lớn, quảng trường và các tuyến phố xung quanh thường được thiết lập hàng rào an ninh nhiều giờ trước khi buổi lễ chính thức bắt đầu, để bảo đảm an toàn cho hàng vạn người tham dự.","nguon_ten":"Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","doc":11},{"loai":"anh","src":"textures/bang_w/G17_11_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Quảng trường Ba Đình”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Nghi thức mỗi ngày","text":"Không cần đợi đến những dịp lễ lớn, Ba Đình vẫn có nhịp sống nghi lễ của riêng mình mỗi ngày. Sáng sớm, đội tiêu binh danh dự làm lễ thượng cờ, kéo lá quốc kỳ lên đỉnh cột cờ giữa quảng trường; chiều tà, nghi lễ hạ cờ diễn ra theo đúng trình tự ấy, thu hút không ít người dân, du khách đứng xem, chụp ảnh (xem chuyên đề Tiêu binh trước Lăng). Ban ngày, dòng người xếp hàng vào viếng Lăng thường bắt đầu tập trung từ khu vực quảng trường; buổi tối, khi ánh đèn được bật lên, không gian quanh cột cờ và mặt tiền Lăng lại trở thành một điểm đến quen thuộc của người Hà Nội và du khách muốn dạo bộ, ngắm cảnh (xem chuyên đề Quảng trường Ba Đình về đêm).","doc":12},{"loai":"doan","tieu_de":"Không gian cần được gìn giữ","text":"Là nơi thiêng liêng bậc nhất của cả nước, Quảng trường Ba Đình được quản lý, gìn giữ cẩn thận: người đến thăm đi trên các lối đi lát đá, không giẫm lên thảm cỏ, giữ trật tự, ăn mặc lịch sự khi vào khu vực trước Lăng. Những quy định tưởng như nhỏ ấy là cách mỗi người thể hiện sự tôn trọng với lịch sử — tiếp nối tâm thế của những con người đã đứng ở chính quảng trường này, buổi trưa ngày 2 tháng 9 năm 1945, lặng nghe lời tuyên bố độc lập của một dân tộc vừa giành lại chủ quyền sau gần một thế kỷ bị đô hộ.","doc":13},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, Quảng trường Ba Đình cùng Lăng Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh và Phủ Chủ tịch hợp thành Cụm di tích lịch sử - văn hóa Ba Đình — điểm đến gần như bắt buộc với bất kỳ ai lần đầu tới Hà Nội. Mỗi năm, hàng triệu lượt người trong nước và quốc tế ghé qua đây, phần lớn dừng chân chụp ảnh bên cột cờ, một số ở lại xem trọn nghi lễ thượng cờ hoặc hạ cờ. Với người Hà Nội, quảng trường này còn là nơi quen thuộc trong đời sống hằng ngày: nơi các gia đình đưa con nhỏ ra hóng gió buổi chiều, nơi những đoàn học sinh tập trung trước mỗi chuyến đi tham quan Lăng, Bảo tàng — một không gian vừa trang nghiêm, vừa gần gũi, đúng như cách nó đã tồn tại suốt tám mươi năm qua.","doc":14}],"nguon":["Ban Quản lý Lăng Chủ tịch Hồ Chí Minh","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Bộ Tư lệnh Bảo vệ Lăng Chủ tịch Hồ Chí Minh","Tuyên ngôn Độc lập, 2/9/1945","Cổng thông tin điện tử thành phố Hà Nội"],"doc":[{"t":"Quảng trường Ba Đình: nơi đất nước làm lễ trong những ngày trọng đại. Không chỉ là nơi khai sinh nước Việt Nam Dân chủ Cộng hòa, Quảng trường Ba Đình còn chứng kiến những cuộc mít tinh, diễu binh và những buổi lễ trọng thể nhất của đất nước suốt tám mươi năm qua. Một lễ đài dựng tạm trong vài ngày của năm 1945, về sau lại trở thành nơi đặt một trong những công trình vĩnh cửu nhất của dân tộc."},{"t":"Buổi trưa ngày 2 tháng 9. Trưa ngày 2 tháng 9 năm 1945, trên một lễ đài gỗ dựng tạm giữa khu vườn hoa khi ấy còn chưa mang tên Ba Đình, trước hàng vạn người dân Hà Nội đứng chật kín, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập, khai sinh nước Việt Nam Dân chủ Cộng hòa. Lễ đài hôm ấy chỉ được dựng trong vài ngày, đơn sơ đến mức nhiều người sau này khó hình dung nó từng đứng ở đúng vị trí nơi một công trình bằng đá hoa cương đồ sộ mọc lên ba mươi năm sau (xem chuyên đề Lăng Chủ tịch Hồ Chí Minh). Nhưng chính buổi trưa hôm ấy đã biến một quảng trường vốn chỉ quen thuộc với người dân quanh vùng thành một địa danh mà sau này bất kỳ người Việt Nam nào cũng biết tên."},{"t":"Tất cả mọi người đều sinh ra có quyền bình đẳng. Tạo hóa cho họ những quyền không ai có thể xâm phạm được; trong những quyền ấy, có quyền được sống, quyền tự do và quyền mưu cầu hạnh phúc. — Chủ tịch Hồ Chí Minh"},{"t":"Từ vườn hoa thời Pháp đến quảng trường của một nước độc lập. Trước năm 1945, khu vực này được người Pháp quy hoạch thành một vườn hoa nằm trước Phủ Toàn quyền Đông Dương, quen gọi theo tên một giám mục Pháp. Đây là một trong những không gian công cộng lớn hiếm hoi ở Hà Nội thời thuộc địa. Sau Cách mạng Tháng Tám, khu vườn được đổi tên thành Quảng trường Ba Đình, theo tên gọi vùng đất Ba Đình ở Thanh Hóa — nơi từng nổ ra cuộc khởi nghĩa chống Pháp cuối thế kỷ 19 của các sĩ phu yêu nước, trong phong trào Cần Vương. Từ một địa danh gắn với phong trào chống Pháp, Ba Đình trở thành tên gọi của quảng trường trung tâm chính trị của nước Việt Nam mới."},{"t":"Một khoảng đất chứng kiến hai chế độ. Trước khi trở thành trung tâm chính trị của một nước độc lập, khu vực quanh Ba Đình từng là nơi đặt các dinh thự, công sở của chính quyền thuộc địa Pháp: Phủ Toàn quyền Đông Dương, các trại lính, các biệt thự dành cho quan chức cao cấp. Việc chọn chính khu vực này để tổ chức lễ Tuyên ngôn Độc lập năm 1945, thay vì một địa điểm nào khác trong thành phố, vì vậy còn mang một ý nghĩa biểu tượng: nơi từng là trung tâm quyền lực của chế độ thực dân, nay trở thành nơi công bố nền độc lập của một dân tộc vừa tự giải phóng mình."},{"t":"Bố cục của một không gian nghi lễ. Quảng trường Ba Đình ngày nay trải rộng trước Lăng Chủ tịch Hồ Chí Minh, gồm nhiều ô cỏ vuông xanh mướt, xen giữa là hệ thống đường dạo lát đá, đủ rộng cho hàng nghìn người xếp hàng cùng lúc. Chính giữa quảng trường là cột cờ cao, nơi lá quốc kỳ được kéo lên mỗi sáng và hạ xuống mỗi chiều trong nghi thức đã trở thành một phần đời sống của Thủ đô. Bố cục rộng, thoáng, không vướng cây cao che khuất tầm nhìn, được thiết kế có chủ đích để phục vụ những cuộc mít tinh, diễu binh, diễu hành quy mô lớn — nơi các khối quần chúng, các đơn vị quân đội có thể di chuyển thành hàng lối chỉnh tề trước lễ đài."},{"t":"Bạn có biết? Tên gọi Ba Đình không có sẵn ở Hà Nội, mà được đặt theo địa danh Ba Đình ở huyện Nga Sơn, tỉnh Thanh Hóa, nơi diễn ra cuộc khởi nghĩa Ba Đình chống thực dân Pháp những năm 1886–1887, một trong những cuộc khởi nghĩa tiêu biểu của phong trào Cần Vương."},{"t":"Những ngày lịch sử nối tiếp nhau. Sau ngày 2 tháng 9 năm 1945, Ba Đình tiếp tục là nơi chứng kiến nhiều thời khắc quan trọng của đất nước. Sáng 1 tháng 1 năm 1955, hàng vạn người dân Hà Nội tề tựu tại quảng trường dự lễ mừng Trung ương Đảng, Chính phủ và Chủ tịch Hồ Chí Minh trở về Thủ đô, sau chín năm kháng chiến chống thực dân Pháp và tiếp quản Hà Nội ngày 10 tháng 10 năm 1954. Ngày 9 tháng 9 năm 1969, lễ truy điệu Chủ tịch Hồ Chí Minh được tổ chức trọng thể ngay tại quảng trường này, giữa những dòng người không cầm được nước mắt. Những thập niên sau đó, Ba Đình tiếp tục là nơi diễn ra các lễ diễu binh, diễu hành lớn: dịp Đại lễ kỷ niệm 1000 năm Thăng Long – Hà Nội ngày 10 tháng 10 năm 2010, lễ kỷ niệm 70 năm Cách mạng Tháng Tám và Quốc khánh ngày 2 tháng 9 năm 2015, và lễ kỷ niệm 80 năm vào ngày 2 tháng 9 năm 2025."},{"t":"Nơi lễ đài tạm nhường chỗ cho công trình vĩnh cửu. Suốt gần ba mươi năm sau ngày Tuyên ngôn Độc lập, lễ đài trước Ba Đình vẫn chỉ là một kết cấu dựng tạm, được dùng đi dùng lại, sửa chữa qua từng lần mít tinh lớn. Phải đến khi Chủ tịch Hồ Chí Minh qua đời năm 1969 và đất nước thống nhất năm 1975, một công trình vĩnh cửu — Lăng Chủ tịch Hồ Chí Minh — mới được xây dựng đúng trên nền lễ đài cũ ấy. Từ đó, lễ đài phía trước Lăng trở thành nơi lãnh đạo Đảng, Nhà nước đứng dự các nghi lễ lớn của đất nước, còn quảng trường phía trước vẫn giữ nguyên vai trò không gian tập hợp quần chúng như suốt tám mươi năm qua."},{"t":"Bạn có biết? Quảng trường Ba Đình hiện có diện tích khoảng hơn ba mươi nghìn mét vuông, đủ chỗ cho hàng vạn người cùng tham dự trong những dịp mít tinh, diễu binh lớn nhất của đất nước."},{"t":"Một quảng trường luôn đông người. Không chỉ vào những dịp lễ lớn, Quảng trường Ba Đình gần như lúc nào cũng có người qua lại: sáng sớm là những người tập thể dục quanh khu vực lân cận, ban ngày là dòng khách du lịch trong nước, quốc tế xếp hàng vào Lăng hoặc đứng chụp ảnh bên cột cờ, buổi tối là những gia đình, đôi bạn trẻ ra hóng mát dưới ánh đèn. Vào những dịp đặc biệt như Tết Nguyên đán hay các ngày lễ lớn của đất nước, khu vực quanh quảng trường còn được trang trí thêm hoa, cờ, tạo nên một không khí vừa trang trọng vừa rộn ràng, thu hút hàng vạn lượt người đến chụp ảnh mỗi ngày."},{"t":"Bạn có biết? Vào các dịp diễu binh, diễu hành lớn, quảng trường và các tuyến phố xung quanh thường được thiết lập hàng rào an ninh nhiều giờ trước khi buổi lễ chính thức bắt đầu, để bảo đảm an toàn cho hàng vạn người tham dự."},{"t":"Nghi thức mỗi ngày. Không cần đợi đến những dịp lễ lớn, Ba Đình vẫn có nhịp sống nghi lễ của riêng mình mỗi ngày. Sáng sớm, đội tiêu binh danh dự làm lễ thượng cờ, kéo lá quốc kỳ lên đỉnh cột cờ giữa quảng trường; chiều tà, nghi lễ hạ cờ diễn ra theo đúng trình tự ấy, thu hút không ít người dân, du khách đứng xem, chụp ảnh (xem chuyên đề Tiêu binh trước Lăng). Ban ngày, dòng người xếp hàng vào viếng Lăng thường bắt đầu tập trung từ khu vực quảng trường; buổi tối, khi ánh đèn được bật lên, không gian quanh cột cờ và mặt tiền Lăng lại trở thành một điểm đến quen thuộc của người Hà Nội và du khách muốn dạo bộ, ngắm cảnh (xem chuyên đề Quảng trường Ba Đình về đêm)."},{"t":"Không gian cần được gìn giữ. Là nơi thiêng liêng bậc nhất của cả nước, Quảng trường Ba Đình được quản lý, gìn giữ cẩn thận: người đến thăm đi trên các lối đi lát đá, không giẫm lên thảm cỏ, giữ trật tự, ăn mặc lịch sự khi vào khu vực trước Lăng. Những quy định tưởng như nhỏ ấy là cách mỗi người thể hiện sự tôn trọng với lịch sử — tiếp nối tâm thế của những con người đã đứng ở chính quảng trường này, buổi trưa ngày 2 tháng 9 năm 1945, lặng nghe lời tuyên bố độc lập của một dân tộc vừa giành lại chủ quyền sau gần một thế kỷ bị đô hộ."},{"t":"Dấu tích hôm nay. Ngày nay, Quảng trường Ba Đình cùng Lăng Chủ tịch Hồ Chí Minh, Bảo tàng Hồ Chí Minh và Phủ Chủ tịch hợp thành Cụm di tích lịch sử - văn hóa Ba Đình — điểm đến gần như bắt buộc với bất kỳ ai lần đầu tới Hà Nội. Mỗi năm, hàng triệu lượt người trong nước và quốc tế ghé qua đây, phần lớn dừng chân chụp ảnh bên cột cờ, một số ở lại xem trọn nghi lễ thượng cờ hoặc hạ cờ. Với người Hà Nội, quảng trường này còn là nơi quen thuộc trong đời sống hằng ngày: nơi các gia đình đưa con nhỏ ra hóng gió buổi chiều, nơi những đoàn học sinh tập trung trước mỗi chuyến đi tham quan Lăng, Bảo tàng — một không gian vừa trang nghiêm, vừa gần gũi, đúng như cách nó đã tồn tại suốt tám mươi năm qua."}],"so_chu":1597}],"do_vat":[]};
